const n=[{id:"vb08-1",s:"",cc:"Khoản 1 Điều 1 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Cán bộ là công dân Việt Nam được bầu cử, phê chuẩn, bổ nhiệm hoặc chỉ định giữ chức vụ, chức danh theo nhiệm kỳ, trong biên chế và hưởng lương từ ngân sách nhà nước. Đặc trưng của cán bộ là gắn với bầu cử/phê chuẩn/bổ nhiệm/chỉ định theo nhiệm kỳ, khác với công chức (được tuyển dụng).",mn:"Cán bộ: bầu cử - phê chuẩn - bổ nhiệm ~- chỉ định theo nhiệm kỳ.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, cán bộ được xác định là công dân Việt Nam được hình thành theo phương thức và chế độ làm việc nào sau đây?",o:["Được bầu cử, phê chuẩn, bổ nhiệm hoặc chỉ định giữ chức vụ, chức danh theo nhiệm kỳ, trong biên chế và hưởng lương từ ngân sách nhà nước","Được tuyển dụng vào vị trí việc làm, trong biên chế và hưởng lương từ ngân sách nhà nước","Được ký hợp đồng làm việc theo vị trí việc làm và hưởng lương từ ngân sách nhà nước","Được bổ nhiệm vào ngạch và hưởng lương theo ngạch, bậc từ ngân sách nhà nước"],c:0},{id:"vb08-2",s:"",cc:"Khoản 2 Điều 1 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Công chức là công dân Việt Nam được tuyển dụng vào vị trí việc làm trong cơ quan của Đảng, Nhà nước, Mặt trận Tổ quốc Việt Nam, các tổ chức chính trị - xã hội.... trong biên chế và hưởng lương từ ngân sách nhà nước. Đặc trưng của công chức là được tuyển dụng vào vị trí việc làm.",mn:"Công chức: tuyển dụng vào vị trí việc làm.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, công chức được xác định là công dân Việt Nam được hình thành theo phương thức nào sau đây?",o:["Được bầu cử, phê chuẩn giữ chức vụ theo nhiệm kỳ","Được tuyển dụng vào vị trí việc làm trong cơ quan của Đảng, Nhà nước, Mặt trận Tổ quốc Việt Nam, các tổ chức chính trị - xã hội, trung biên chế và hưởng lương từ ngân sách nhà nước","Được ký hợp đồng lao động và hướng lương theo thỏa thuận","Được chỉ định giữ chức vụ lãnh đạo, quản lý không qua bầu cử"],c:1},{id:"vb08-3",s:"",cc:"Khoan! và khoản 2 Điều Ì Luật (án hộ, công chức số 80/20)25/0)HI5.",gt:"Tiêu chí cốt lõi: cán bộ gắn với bầu cử, phê chuẩn, bổ nhiệm, chỉ định giữ chức vụ, chức danh theo nhiệm kỳ; công chức gắn với tuyển dụng vào vị trí việc làm. Cả hai đều trong biên chế và hưởng lương từ ngân sách nhà nước, đều có thể ở trung ương hoặc địa phương.",mn:"Cán bộ: theo nhiệm kỳ (bầu/bổ nhiệm); Công chức: tuyển dụng vào vị trí việc làm.",t:"m",q:"Phân biệt giữa cán bộ và công chức theo Luật Cán bộ, công chức số 80/2025/QH15, tiêu chí cốt lợi để phân biệt là gì?",o:["Cán bộ hưởng lương từ ngân sách nhà nước, còn công chức hưởng lương theo thỏa thuận","Cán bộ trong biên chế, còn công chức không trong biên chế","Cán bộ làm việc ở trung ương, còn công chức làm việc ở địa phương","Cán bộ được bầu cử, phê chuẩn, bổ nhiệm, chỉ định giữ chức vụ, chức danh theo nhiệm kỳ; con công chức được tuyển dụng vào vị trí việc làm"],c:3},{id:"vb08-4",s:"",cc:"Điều 1 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Cán bộ, công chức làm việc ở trung ương, ở cấp tỉnh, ở cấp xã - phù hợp với mô hình chính quyền địa phương hai cấp (không còn cấp huyện). Đẩy là điểm mới gắn với việc kết thúc hoạt động của đơn vị hành chính cấp huyện.",mn:"Cấp làm việc: trung ương - tỉnh - xã (không còn cấp huyện).",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, cán bộ, công chức được xác định làm việc ở những cấp nào trong hệ thống chính trị?",o:["Ở trung ương, ở cấp tỉnh và ở cấp xã","Ở trung ương, ở cấp tỉnh, ở cấp huyện và ở cấp xã","Chỉ ở trung ương và cấp tỉnh","Ở trung ương, cấp tỉnh, cấp huyện, cấp xã và cấp thôn"],c:0},{id:"vb08-5",s:"",cc:"Khoản 2 Điều 1 Luật Cán bộ, công chức số 60/2025/QH15.",gt:"Trong Quân đội nhân dân, công chức là người không phải là sĩ quan, quân nhân chuyên nghiệp, công nhân, viên chức quốc phòng, được tuyển dụng vào vị trí việc làm, trong hiện chế và hướng lương từ ngân sách nhà nước.",mn:"Công chức trong quân đội: KHÔNG phải sĩ quan, QNCN, công nhân, viên chức quốc phòng.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, người làm việc trong cơ quan, đơn vị thuộc Quân đội nhân dân thuộc nhóm đối tượng nào sau đây thì được xác định là công chức?",o:["Toàn bộ sĩ quan và quân nhân chuyên nghiệp trong biên chế","Người mà không phải là sĩ quan, quân nhân chuyên nghiệp, công nhân, viên chức quốc phòng, trong biên chế và hưởng lương từ ngân sách nhà nước","Công nhân và viên chức quốc phòng trong các đơn vị quân đội","Người làm việc theo chế độ hợp đồng trong các đơn vị quân đội"],c:1},{id:"vb08-6",s:"",cc:"Khoản 2 Điều 1 Luật Cán bộ, công chức số 60/2025/QH15.",gt:"Trong Công an nhân dân, công chức là người không phải là sĩ quan, hạ sĩ quan, chiến sĩ phục vụ theo chế độ chuyên nghiệp, công nhân công an, được tuyển dụng vào vị trí việc làm, trong biên chế và hưởng lương từ ngân sách nhà nước.",mn:"Công chức trong công an: KHÔNG phải sĩ quan, hạ sĩ quan, chiến sĩ chuyên nghiệp, công nhân công an.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, người làm việc trong cơ quan, đơn vị thuộc Công an nhân dân thuộc nhóm nào sau đây thì được xác định là công chức?",o:["Người làm việc theo hợp đồng trong các đơn vị công an","Toàn bộ sĩ quan và hạ sĩ quan công an trong biên chế","Công nhân công an và chiến sĩ phục vụ theo chế độ chuyên nghiệp","Người mà không phải là sĩ quan, hạ sĩ quan, chiến sĩ phục vụ theo chế độ chuyên nghiệp, công nhân công an, trong biên chế và hưởng lương từ ngân sách nhà nước 2"],c:3},{id:"vb08-7",s:"",cc:"Điều 2 Luật Cán bộ. công chức số 90/2025/QH15.",gt:"Năm nguyên tắc trong thi hành công vụ gồm: tuân thủ Hiến pháp và pháp luật; tôn trọng, bảo đảm, bảo vệ quyền con người, quyền công dân, lợi ích của Nhà nước, tổ chức, cá nhân; công khai, minh bạch, đúng thẩm quyền và có kiểm tra, giám sát; bảo đảm tính hệ thống, thống nhất, liên tục, thông suốt, chuyên nghiệp, hiện đại, hiệu quả: bảo đảm thứ bậc hành chính và phối hợp chặt chẽ. Phương án B, C thuộc nguyên tắc quản lý cán bộ, công chức.",mn:"Thi hành công vụ: tuân thủ HP-PI. - bảo vệ quyền - công khai, minh bạch - hệ thống, thông suốt — thi bậc hành chính.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, nguyên tắc trong thi hành công vụ bao gồm những nội dung nào sau đây?",o:["Bảo đảm sự lãnh đạo của Đảng; kết hợp tiêu chuẩn chức danh với chỉ tiêu biên chế; thực hiện bình đẳng giới","Tập trung dân chủ; chế độ trách nhiệm cá nhân; phân công, phân cấp rõ ràng: bình đẳng giới; tu tiền người dân tộc thiểu số","Tuân thủ Hiến pháp và pháp luật; tôn trọng, bảo đảm, bảo vệ quyền con người, quyền công dân; công khai, minh bạch, đúng thẩm quyền và có sự kiểm tra, giám sát; bảo đảm tính hệ thống, thống nhất, liên tục, thông suốt, chuyên nghiệp, hiện đại và hiệu quả; bảo đảm thứ bậc hành chính và sự phối hợp chặt chẽ","Tuân thủ pháp luật; bảo đảm quyền lợi của cán bộ, công chức; thực hiện dân chủ Ở CƠ SỞ"],c:2},{id:"vb08-8",s:"",cc:"Điều 3 Luật Cán bộ. công chức số 80/2025/QH15.",gt:"Nguyên tác quản lý cán bộ, công chức gồm: bảo đảm sự lãnh đạo của Đảng, quản lý của Nhà nước; kết hợp tiêu chuẩn chức danh, vị trí việc làm và chỉ tiêu biên chế; tập trung dân chủ; đánh giá theo phẩm chất, năng lực, kết quả; thống nhất, đồng bộ, liên thông; bình đẳng giới; ưu tiên người dân tộc thiểu số. Các phương án B, C, D thuộc nguyên tắc thi hành công vụ.",mn:"Quản lý CBCC: Đảng lãnh đạo - chức danh+VTVL+biên chế - tập trung dân chủ - bình đẳng giới — ưu tiên dân tộc thiểu số. LuôcCHUC2UD2S | Trung 3",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, nguyên tắc nào sau đây thuộc về nguyên tắc quản lý cán bộ, công chức (không phải nguyên tắc thi hành công vụ)?",o:["Bảo đảm thứ bậc hành chính và sự phối hợp chặt chẽ","Tuân thủ Hiến pháp và pháp luật","Công khai, minh bạch, đúng thẩm quyền và có sự kiểm tra, giám sát","Bảo đảm sự lãnh đạo của Đảng Cộng sản Việt Nam, sự quản lý của Nhà nước; kết hợp giữa tiêu chuẩn chức danh, vị trí việc làm và chỉ tiêu biên chế"],c:3},{id:"vb08-9",s:"",cc:"Khoản 4 Điều 3 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Việc đánh giá, bố trí, sử dụng cán bộ, công chức phải căn cứ vào phẩm chất chính trị, đạo đức, năng lực và kết quả, hiệu quả thực thi nhiệm vụ theo yêu cầu vị trí việc làm - lấy kết quả công việc và vị trí việc làm làm trung tâm.",mn:"Đánh giá, bố trí: phẩm chất - đạo đức - năng lực - kết quả theo vị trí việc làm.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, trong nguyên tắc quản lý cán bộ, công chức, việc đánh giá, bố trí, sử dụng cán bộ, công chức phải căn cứ vào những yếu tố nào?",o:["Phẩm chất chính trị, đạo đức, năng lực và kết quả, hiệu quả thực thi nhiệm vụ theo yêu cầu vị trí việc làm","Thâm niên công tác, bằng cấp và chức vụ hiện giữ","Quá trình đào tạo, bồi dưỡng và nguyện vọng cá nhân","Kết quả thi tuyển và thời gian giữ ngạch"],c:0},{id:"vb08-10",s:"",cc:"Điều 2 và Điều 3 Luật Cán bộ, công chức số 60/2025/QH15.",gt:"Nguyên tắc bảo đảm tính hệ thống, thống nhất, liên tục, thông suốt, chuyên nghiệp, hiện đại và hiệu quả thuộc nhóm nguyên tắc trong thi hành công vụ, không phải nguyên tắc quản lý cán bộ, công chức. Các phương án A, B, C đều là nguyên tắc quản lý cán bộ, công chức.",mn:"'Hệ thống, thông suốt, chuyên nghiệp, hiện đại' là nguyên tắc thi hành công vụ.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, các nguyên tắc nào sau đây cùng thuộc nguyên tác quản lý cán bộ, công chức, NGOẠI TRỪ nguyên tắc nào?",o:["Thực hiện bình đẳng giới","Bảo đảm tính hệ thống, thống nhất, liên tục, thông suốt, chuyên nghiệp, hiện đại và hiệu quả","Thực hiện nguyên tắc tập trung dân chủ, chế độ trách nhiệm cá nhân và phân công, phân cấp rõ ràng","Ưu tiên trong tuyển dụng, bổ nhiệm và thực hiện chế độ, chính sách đối với người dân tộc thiểu số"],c:1},{id:"vb08-11",s:"",cc:"Khoản 1 Điều 4 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Nhà nước có cơ chế đặc biệt thu hút chuyên gia, nhà khoa học, luật gia, luật sư giỏi, doanh nhân tiêu biểu, xuất sắc, sinh viên tốt nghiệp xuất sắc và Luậtt lì 6 2(25 Liũne 4 nguồn nhân lực chất lượng cao khác; đồng thời có chính sách trọng dụng, đãi ngộ xứng đáng người có tài năng trong hoạt động công vụ.",mn:"Thu hút: chuyên gia - nhà khoa học - luật gia, luật sư giỏi — doanh nhân tiêu biểu — sinh viên xuất sắc.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, Nhà nước có cơ chế đặc biệt để thu hút những đối tượng nào vào làm việc trong hệ thống chính trị?",o:["Cán bộ, công chức đã có thời gian công tác lâu năm","Toàn bộ sinh viên tốt nghiệp đại học loại khá trở lên","Chuyên gia, nhà khoa học, luật gia, luật sư giỏi, doanh nhân tiêu biểu, xuất sắc, sinh viên tốt nghiệp xuất sắc và nguồn nhân lực chất lượng cao khác","Người lao động có trình độ chuyên môn trong khu vực tư nhân"],c:2},{id:"vb08-12",s:"",cc:"Khoản 2 Điều 4 Luật Cán bộ, công chức số 60/2025/031115.",gt:"Người có tài năng trong hoạt động công vụ là người có phẩm chất chính trị, đạo đức tốt, khát vọng cống hiến; năng lực chuyên môn, kỹ năng vượt trội; tư duy đổi mới, dám nghĩ, dám làm, dám chịu trách nhiệm vì lợi ích chung: đất thành tích nổi bật bằng kết quả, sản phẩm cụ thể. Trọng tâm là kết quả, sản phẩm cụ thể chủ không phải bằng cấp hay chức vụ.",mn:"Người tài năng: phẩm chất + năng lực vượt trội + dám nghĩ dám làm + kết quả, sản phẩm cụ thể.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, 'người có tài năng trong hoạt động công vụ' được xác định gồm những đặc điểm nào sau đây?",o:["Có trình độ ngoại ngữ, tin học và kỹ năng quản lý tốt","Có bằng cấp chuyên môn cao và thâm niên công tác lâu năm","Có chức vụ lãnh đạo, quản lý và được khen thưởng nhiều lần","Có phẩm chất chính trị, đạo đức tốt, khát vọng cống hiến; có năng lực chuyên môn, kỹ năng vượt trội; có tư duy đổi mới, dám nghĩ, dám làm, dám chịu trách nhiệm; đạt thành tích nổi bật thể hiện bằng kết quả, sản phẩm cụ thể"],c:3},{id:"vb08-13",s:"",cc:"Khoản 1 Điều 5 Luật Cán bộ, công chức số 80/2025/00H15.",gt:"Công vụ là hoạt động do cán bộ, công chức thực hiện nghĩa vụ, quyền hạn được giao theo quy định của cấp có thẩm quyền và của pháp luật, nhằm thực hiện quản lý nhà nước và đáp ứng nhu cầu chung của xã hội.",mn:"Công vụ; hoạt động của CBCGC thực hiện nghĩa vụ, quyền hạn được giao.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, 'công vụ' được hiểu là gì?",o:["Là toàn bộ hoạt động của cơ quan nhà nước trong việc quản lý xã hội","Là hoạt động do cán bộ, công chức thực hiện nghĩa vụ, quyền hạn được giao theo quy định của cấp có thẩm quyền và của pháp luật nhằm thực hiện quản lý nhà nước và đáp ứng nhu cầu chung của xã hội","Là hoạt động cung cấp dịch vụ công cho người dân và doanh nghiệp","Là hoạt động chấp hành và điều hành của cơ quan hành chính nhà nước"],c:1},{id:"vb08-14",s:"",cc:"Khoản 4 Điều 5 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Vị trí việc làm là công việc gắn với chức vụ, chức danh, ngạch công chức trên cơ sở chức năng, nhiệm vụ cụ thể của cơ quan, tổ chức, đơn vị. Cần phân biệt với 'ngạch' (tên gọi thể hiện thứ bậc chuyên môn, nghiệp vụ).",mn:"Vị trí việc làm = công việc gắn với chức vụ, chức danh, ngạch.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, 'vị trí việc làm' được định nghĩa như thế nào?",o:["Là công việc gắn với chức vụ, chức danh, ngạch công chức trên cơ sở chức năng, nhiệm vụ cụ thể của cơ quan, tổ chức, đơn vị","Là tên gọi thể hiện thứ bậc về chuyên môn, nghiệp vụ của công chức","Là chức vụ lãnh đạo, quản lý mà công chức được bố nhiệm","Là biên chế được giao cho mỗi cơ quan, tổ chức, đơn vị"],c:0},{id:"vb08-15",s:"",cc:"Khoản 5 Điều 5 Luật Còn bộ, công chức số 80/2025/QH15.",gt:"Ngạch là tên gọi thể hiện thứ bậc về chuyên môn, nghiệp vụ của công chức. Đây là khái niệm hay bị nhầm với 'vị trí việc làm' (công việc gắn với chức vụ, chức danh, ngạch).",mn:"Ngạch = thứ bậc chuyên môn, nghiệp vụ của công chức.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, 'ngạch' được hiểu là gì?",o:["Là chức vụ lãnh đạo, quản lý trong cơ quan, tổ chức, đơn vị","Là công việc gắn với chức vụ, chức danh của công chức","Là tên gọi thể hiện thứ bậc về chuyên môn, nghiệp vụ của công chức","Là cấp bậc hành chính trong hệ thống cơ quan nhà nước"],c:2},{id:"vb08-16",s:"",cc:"Khoản 7 Điều 5 Luật Cán bộ. công chức số 80/2025/QH15.",gt:"Điều động là việc chuyển cán bộ, công chức từ cơ quan, đơn vị này đến làm việc ở cơ quan, đơn vị khác. Cần phân biệt với biệt phái (cứ có thời hạn, ngoài phạm vì cơ quan quản lý), luân chuyển (gắn với cán bộ lãnh đạo, quản lý, để đào tạo, rèn luyện) và bố nhiệm (giáo giữ chức vụ).",mn:"Điều động: chuyến hắn sang cơ quan, đơn vị khác.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, hành vi 'điều động' được hiểu như thế nào?",o:["Là việc phân công hoặc bổ nhiệm cán bộ, công chức lãnh đạo, quản lý giữ chức vụ tại cơ quan khác trong một thời hạn nhất định","Là việc cử công chức đến làm việc có thời hạn tại cơ quan, đơn vị khác ngoài phạm vi cơ quan quản lý","Là việc cơ quan, tổ chức có thẩm quyền quyết định chuyển cán bộ, công chức từ cơ quan, tổ chức, đơn vị này đến làm việc ở cơ quan, tổ chức, đơn vị khác","Là việc giao cán bộ, công chức giữ một chức vụ, chức danh trong cơ quan, tổ chức, đơn vị"],c:2},{id:"vb08-17",s:"",cc:"Khoản 10 Điều 5 Luật Cán bộ, công chức số 80/2025/QH115. Luậtt lì 6 2(25 L0ae G",gt:"Biệt phái là việc công chức được cử đến làm việc CÓ THỜI HẠN tại cơ quan, đơn vị khác ngoài phạm vi cơ quan quản lý theo yêu cầu nhiệm vụ. Khác với điều động (chuyển hắn), biệt phái mang tính 'có thời hạn'.",mn:"Biệt phái: cử đi làm có thời hạn ở nơi khác (rồi quay về).",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, hành vi 'biệt phái' được hiểu như thế nào?",o:["Là việc chuyển hạn công chức từ cơ quan này sang làm việc ở cơ quan khác","Là việc công chức của cơ quan, tổ chức, đơn vị này được cử đến làm việc có thời hạn tại cơ quan, tổ chức, đơn vị khác ngoài phạm vi cơ quan quản lý theo yêu cầu nhiệm vụ","Là việc bổ nhiệm công chức lãnh đạo, quản lý giữ chức vụ ở cơ quan khác để đào tạo, rèn luyện","Là việc giao công chức giữ một chức vụ, chức danh trong cơ quan, tổ chức, đơn vị"],c:1},{id:"vb08-18",s:"",cc:"Khoản 9 Điều 5 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Luân chuyển áp dụng đối với cán bộ, công chức lãnh đạo, quản lý. được phân công hoặc bổ nhiệm giữ chức vụ lãnh đạo, quản lý tại cơ quan khác truong một thời hạn nhất định để tiếp tục đào tạo, bồi dưỡng, rèn luyện hoặc theo yêu cầu của chức danh được quy hoạch. Đặc trưng: gắn với cán bộ lãnh đạo, quản lý và mục đích đào tạo, quy hoạch.",mn:"Luân chuyển: dành cho cán bộ lãnh đạo, quản lý, để đào tạo, rèn luyện, quy hoạch.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, hành vi 'luân chuyển' có đặc điểm nào sau đây để phân biệt với điều động và biệt phái?",o:["Áp dụng để giao công chức giữ một chức vụ trong cùng cơ quan","Áp dụng đối với mọi công chức để chuyển hắn sang cơ quan khác","Áp dụng đối với công chức để cử đi làm việc có thời hạn rồi quay về cơ quan cử","Áp dụng đối với cán bộ, công chức lãnh đạo, quản lý, giữ chức vụ, chức danh lãnh đạo, quản lý tại cơ quan khác trong một thời hạn nhất định để tiếp tục đào tạo, bồi dưỡng, rèn luyện hoặc theo yêu cầu của chức danh được quy hoạch"],c:3},{id:"vb08-19",s:"",cc:"Khoản 1] và khoản 12 ‡iểu 5 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Từ chức là việc cán bộ, công chức lãnh đạo, quản lý tự nguyện xin thôi giữ chức vụ; miễn nhiệm là việc cơ quan có thẩm quyền quyết định cho thôi giữ chức vụ. Cả hai đều khi chưa hết nhiệm kỳ hoặc chưa hết thời hạn bổ nhiệm, nhưng khác nhau ở chủ thể: tự nguyện (từ chức) hay cơ quan quyết định (miễn nhiệm).",mn:"Từ chức: tự nguyện; Miễn nhiệm: cơ quan quyết định.",t:"m",q:"Phân biệt 'từ chức' và 'miễn nhiệm' theo Luật Cán bộ, công chức số 80/2025/QH15, nội dung nào sau đây là DÙNG?",o:["Từ chức là việc cán bộ, công chức lãnh đạo, quản lý tự nguyện xin thôi giữ chức vụ; con miễn nhiệm là việc cơ quan có thẩm quyền quyết định cho thôi giữ chức vụ khi chưa hết nhiệm kỳ hoặc chưa hết thời hạn bổ nhiệm","Từ chức và miễn nhiệm đều do cơ quan có thẩm quyền quyết định","Từ chức do cơ quan quyết định, còn miễn nhiệm do cá nhân tự nguyện","Cả hai đều chỉ áp dụng khi đã hết nhiệm kỳ hoặc hết thời hạn bổ nhiệm"],c:0},{id:"vb08-20",s:"",cc:"Khoản 6 Điều 5 Luật Cán bộ, công chức số 80/2025/QH15. -, w— 7 Luật CDUC 2025 |J-/JƯráng ý",gt:"Chỉ định là việc cơ quan có thẩm quyền quyết định giao cán bộ giữ chức vụ, chức danh lãnh đạo, quản lý KHÔNG QUA BẦU CỬ. Đặc trưng: 'không qua bầu cử.",mn:"Chỉ định: giao chức vụ lãnh đạo không qua bầu cử.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, 'chỉ định' được hiểu là gì?",o:["Là việc tuyển dụng công chức vào vị trí việc làm","Là việc giao công chức giữ một chức vụ thông qua thi tuyển","Là việc bầu cán bộ vào chức vụ lãnh đạo theo nhiệm kỳ","Là việc cơ quan, tổ chức có thẩm quyền quyết định giao cán bộ giữ chức vụ, chức danh lãnh đạo, quản lý không qua bầu cử"],c:3},{id:"vb08-21",s:"",cc:"Khoản 13 Điều 5 Luật Cán bộ, công chức số 90/2025/QH115.",gt:"Tạm đình chỉ công tác là việc cơ quan có thẩm quyền quyết định việc cán bộ, công chức dừng thực hiện chức trách, nhiệm vụ được giao trung thời hạn nhất định. Đây là biện pháp tạm thời, không phải hình thức kỷ luật.",mn:"Tạm đình chỉ công tác: đúng nhiệm vụ tạm thời (không phải kỷ luật).",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, 'tạm đình chỉ công tác' được hiểu là gì?",o:["Là việc cho cán bộ, công chức thôi giữ chức vụ khi chưa hết nhiệm kỳ","Là việc cơ quan, tổ chức có thẩm quyền quyết định việc cán bộ, công chức dừng thực hiện chức trách, nhiệm vụ được giao trong thời hạn nhất định","Là việc chuyển cán bộ, công chức sang làm việc ở cơ quan khác","Là việc buộc thôi việc đối với cán bộ, công chức vi phạm"],c:1},{id:"vb08-22",s:"",cc:"Khoản 7 Điều 5 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Việc chuyển hạn công chức từ cơ quan này (Số A) đến làm việc ở cơ quan khác (Sở B) là điều động. Nếu chi cử đi có thời hạn rõi quay về thì là biệt phái; nếu gắn với cán bộ lãnh đạo để đào tạo, quy hoạch thì là luân chuyển.",mn:"Chuyển hắn sang cơ quan khác = điều động.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, một công chức được cơ quan có thẩm quyền quyết định chuyển hạn từ Số A sang công tác tại Sở B. Trường hợp này thuộc hình thức nào sau đây?",o:["Điều động","Biệt phái","Luân chuyển","Bổ nhiệm"],c:0},{id:"vb08-23",s:"",cc:"Khoản 10 Điều 5 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Việc công chức được cử đến làm việc CÓ THỜI HẠN tại cơ quan, đơn vị khác ngoài phạm vi cơ quan quản lý, sau đó trở về, là biệt phái. Khác với điều động (chuyến hắn).",mn:"Cử đi có thời hạn rồi quay về = biệt phái. Luậtt lì 6 2(25 lung 8",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, một công chức của Bộ X được cử sang làm việc tại một dự án của Bộ Y trong thời hạn 02 năm, sau đó trở về Bộ X. Trường hợp này thuộc hình thức nào?",o:["Luân chuyển","Điều động","Biệt phái","Bổ nhiệm"],c:2},{id:"vb08-24",s:"",cc:"Điều 5 Luật Cần hộ, công chức số 80/2025/02H15.",gt:"Điều 5 giải thích các từ ngữ như công vụ, vị trí việc làm, ngạch, điều động, biệt phái, luân chuyển, bổ nhiệm, từ chức, miễn nhiệm, chỉ định, tạm đình chỉ công tác... Viên chức không thuộc phạm vi giải thích của Luật Cán bộ, công chức (viên chức do Luật Viên chức điều chỉnh).",mn:"Luật CBCC không giải thích 'viên chức' (thuộc Luật Viên chức).",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, các từ ngữ nào sau đây cùng được giải thích trong Luật, NGOẠI TRÚ từ ngữ nào?",o:["Viên chức","Vị trí việc làm","Ngạch","Công vụ"],c:0},{id:"vb08-25",s:"",cc:"Khoản 3 Điều 5 Luật Còn bộ, công chức số 90/2025/QH15.",gt:"Cơ quan sử dụng cán bộ, công chức là cơ quan được giao thẩm quyền sử dụng, phân công, bố trí, kiểm tra, đánh giá việc thực hiện nhiệm vụ của cán bộ, công chức. Cần phân biệt với cơ quan quản lý cán bộ, công chức (cơ quan có thẩm quyền thực hiện các nội dung quản lý).",mn:"Cơ quan sử dụng: phân công, bố trí, kiểm tra, đánh giá CBCC.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, 'cơư quan sử dụng cán bộ, công chức' được xác định là cơ quan nào?",o:["Cơ quan có thẩm quyền tuyển dụng và bố nhiệm cán bộ, công chức","Cơ quan, tổ chức có thẩm quyền thực hiện các nội dung quản lý cán bộ, công chức","Cơ quan trực tiếp trả lương cho cán bộ, công chức","Cơ quan, tổ chức, đơn vị được giao thẩm quyền sử dụng, phân công, bố trí, kiểm tra, đánh giá việc thực hiện nhiệm vụ, quyền hạn của cán bộ, công chức và các thẩm quyền khác theo phân cấp, ủy quyền"],c:3},{id:"vb08-26",s:"",cc:"Khoản 3 Điều 4 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Chính phủ quy định khung cơ chế, chính sách thu hút, trọng dụng và đãi ngộ đối với nguồn nhân lực chất lượng cao và người có tài năng trong hoạt động công vụ.",mn:"Khung cơ chế thu hút nhân tài: do Chính phủ quy định. Luậtt lì 6 2(25 L-uae 9",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, chủ thể nào quy định khung cơ chế, chính sách thu hút, trọng dụng và đãi ngộ đối với nguồn nhân lực chất lượng cao và người có tài năng trong hoạt động công vụ?",o:["Quốc hội","Chính phủ","Bộ Nội vụ","Ủy ban Thường vụ Quốc hội"],c:1},{id:"vb08-27",s:"",cc:"Khoản 5 Điều 4 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Ngân sách nhà nước bảo đảm kinh phí thực hiện chính sách; ngoài ra Độ, ngành, cơ quan trung ương và địa phương được huy động các nguồn hợp pháp khác để thực hiện chính sách.",mn:"Kinh phí thu hút nhân tài: ngân sách nhà nước + nguồn hợp pháp khác.",t:"m",q:"Theo Luật Cán bộ, công chức số 90/2025/QH15, kinh phí để thực hiện chính sách đối với nguồn nhân lực chất lượng cao và người có tài năng trong hoạt động công vụ được bảo đảm từ nguồn nào?",o:["Từ quỹ tiền lương của cơ quan, tổ chức, đơn vị","Hoàn toàn từ nguồn xã hội hóa và đóng góp của doanh nghiệp","Ngân sách nhà nước bảo đảm; ngoài ra, các Bộ, ngành, cơ quan trung ương và địa phương được huy động các nguồn hợp pháp khác để thực hiện chính sách","Từ nguồn thu phí, lễ phí của cơ quan nhà nước"],c:2},{id:"vb08-28",s:"",cc:"Điều 1 Luật Cán bộ, công chức số 60/2025/QH15.",gt:"Cán bộ, công chức được xác định làm việc ở trung ương, cấp tỉnh, cấp xã (mô hình hai cấp, không còn cấp huyện). Vì vậy phương án D nêu cấp huyện' là không đúng. Các nhận định A, B, C đều đúng.",mn:"Không còn 'cấp huyện - chi trung ương, tính, xã.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, nhận định nào sau đây về khái niệm cán bộ, công chức là KHÔNG đúng?",o:["Cán bộ được bầu cử, phê chuẩn, bổ nhiệm hoặc chỉ định giữ chức vụ, chức danh theo nhiệm kỳ","Cán bộ, công chức được xác định làm việc ở trung ương, cấp tỉnh, cấp huyện và cấp xã","Cán bộ, công chức đều trong biên chế và hưởng lương từ ngân sách nhà nước","Công chức được tuyển dụng vào vị trí việc làm"],c:1},{id:"vb08-29",s:"",cc:"Khoản 3 Điều 3 Luật Cán bộ, công chức số 80/2025/QH15. (;iái thích: Nguyên tắc tập trung dân chủ, chế độ trách nhiệm cá nhân và phân công, phân cấp rõ ràng thuộc nhóm nguyên tắc quản lý cán bộ, công chức (Điều 3).",mn:'Tập trung dân chủ + trách nhiệm cá nhân + phân công, phân cấp = nguyên tắc quản lý CBCC. Luôi CBCC 2025 "nang 10',t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, nguyên tắc 'tập trung dân chủ, chế độ trách nhiệm cá nhân và phân công, phân cấp rõ ràng' thuộc nhóm nguyên tắc nào?",o:["Nguyên tắc đánh giá công chức","Nguyên tắc trong thi hành công vụ","Nguyên tắc tuyển dụng công chức","Nguyên tắc quản lý cán bộ, công chức"],c:3},{id:"vb08-30",s:"",cc:"Khoản 4 P)leu 4 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Căn cứ quy định của Chính phủ và định hướng phát triển ngành, lĩnh vực chiến lược, người đứng đầu Bộ, ngành, cơ quan trung ương hoặc Hội đồng nhân dân cấp tỉnh xác định ngành, lĩnh vực cần ưu tiên sử dụng nguồn nhân lực chất lượng cao và quyết định chính sách phù hợp.",mn:"Xác định ngành ưu tiên nhân lực CLC: người đứng đầu Bộ, ngành hoặc HĐND cấp tỉnh.",t:"m",q:"Theo Luật Cán bộ, công chức số 90/2025/QH15, việc xác định ngành, lĩnh vực cần ưu tiên sử dụng nguồn nhân lực chất lượng cao trong từng giai đoạn thuộc thẩm quyền của chủ thể nào?",o:["Người đứng đầu Bộ, ngành, cơ quan trung ương hoặc Hội đồng nhân dân cấp tỉnh","Chính phủ và Thủ tướng Chính phủ","Bộ Nội vụ và Ủy ban nhân dân cấp tỉnh","Quốc hội và Ủy ban Thường vụ Quốc hội"],c:0},{id:"vb08-31",s:"",cc:"Điều 2 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Cả ba đều thuộc nguyên tắc trong thi hành công vụ: tuân thủ Hiến pháp và pháp luật; công khai, minh bạch, đúng thẩm quyền và có kiểm tra, giám sát; bảo đảm thứ bậc hành chính và phối hợp chặt chẽ.",mn:"Thi hành công vụ: tuân thủ PL, + công khai, minh bạch + thứ bậc hành chính.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, các nội dung sau có cùng thuộc nguyên tắc trong thi hành công vụ hay không: (i) tuân thủ Hiến pháp và pháp luật; (ii) công khai, minh bạch, đúng thẩm quyền và có sự kiểm tra, giám sát; (III) bảo đảm thứ bậc hành chính và sự phối hợp chặt chẽ?",o:["Chỉ nội dung (1) đúng","Chỉ nội dung (i) và (II) đúng","Cả ba nội dung đều thuộc nguyên tắc trong thi hành công vụ","Không nội dung nào thuộc nguyên tắc trong thi hành công vụ"],c:2},{id:"vb08-32",s:"",cc:"Khoản 2 Điều 1 Luật Cán bộ, công chức số 80/2025/QH l5.",gt:"Trong tổ chức cơ yếu, công chức là người không phải là người làm công tác cơ yếu, trong biên chế và hưởng lương từ ngân sách nhà nước.",mn:'Công chức trong cơ yếu: KHÔNG phải người làm công tác cơ yếu. Luôi CBCC 2025 "nang 11',t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, người làm việc trong tổ chức cơ yếu được xác định là công chức khi thuộc trường hợp nào?",o:["Khi không phải là người làm công tác cơ yếu, trong biên chế và hưởng lương từ ngân sách nhà nước","Khi là người trực tiếp làm công tác cơ yếu","Khi làm việc theo chế độ hợp đồng trong tổ chức cơ yếu","Khi được biệt phái đến tổ chức cơ yếu"],c:0},{id:"vb08-33",s:"",cc:"Khoản 2 Điều 3 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Nguyên tắc này bảo đảm việc quản lý, bố trí cán bộ, công chức gắn với tiêu chuẩn chức danh, yêu cầu của vị trí việc làm và trong giới hạn chỉ tiêu biên chế được giao - tránh tuyển dụng, bố trí tùy tiện.",mn:"Kết hợp: tiêu chuẩn chức danh + vị trí việc làm + chỉ tiêu biên chế.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, nguyên tắc 'kết hợp giữa tiêu chuẩn chức danh, vị trí việc làm và chỉ tiêu biên chế' có ý nghĩa nào sau đây trong quản lý cán bộ, công chức?",o:["Cho phép tuyển dụng cán bộ, công chức không giới hạn theo nhu cầu công việc","Bảo đảm việc quản lý, bố trí cán bộ, công chức gắn với tiêu chuẩn chức danh, yêu cầu của vị trí việc làm và trong giới hạn chỉ tiêu biên chế được giao","Ưu tiên bố trí cán bộ, công chức theo thâm niên công tác","Bảo đảm mọi cán bộ, công chức đều được bố nhiệm vào chức danh lãnh đạo"],c:1},{id:"vb08-34",s:"",cc:"Khoản 2 Điều 5 Luật Còn bộ, công chức số 90/2025/QH15.",gt:"Cơ quan quản lý cán bộ, công chức là cơ quan, tổ chức có thẩm quyền thực hiện các nội dung quản lý cán bộ, công chức. Cần phân biệt với cơ quan sử dụng cán bộ, công chức (phân công, bố trí, kiểm tra, đánh giá).",mn:"Cơ quan quản lý: thực hiện các nội dung quản lý CBCC.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, 'cơư quan quản lý cán bộ, công chức' được hiểu là gì?",o:["Cơ quan trực tiếp chỉ trả lương cho cán bộ, công chức","Cơ quan, tổ chức, đơn vị được giao thẩm quyền sử dụng, phân công, bố trí cán bộ, công chức","Cơ quan, tổ chức có thẩm quyền thực hiện các nội dung quản lý cán bộ, công chức","Cơ quan có thẩm quyền khen thưởng, kỷ luật cán bộ, công chức"],c:2},{id:"vb08-35",s:"",cc:"khoản 8 Điều 5 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Bổ nhiệm là việc cơ quan có thẩm quyền quyết định giao cán bộ, công chức giữ một chức vụ, chức danh trong cơ quan, tổ chức, đơn vị.",mn:"Bổ nhiệm: giao giữ một chức vụ, chức danh.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, hành vi 'bổ nhiệm' được hiểu như thế nào?",o:["Là việc cho cán bộ, công chức thôi giữ chức vụ khi chưa hết nhiệm kỳ","Là việc chuyển cán bộ, công chức từ cơ quan này sang cơ quan khác","Là việc cử công chức đi làm việc có thời hạn ở cơ quan khác","Là việc cơ quan, tổ chức có thẩm quyền quyết định giao cán bộ, công chức giữ một chức vụ, chức danh trong cơ quan, tổ chức, đơn vị"],c:3},{id:"vb08-36",s:"",cc:"Điều 4 Luật Cán bộ, công chức số 60/2025/0)1115.",gt:"Ngân sách nhà nước bảo đảm kinh phí thực hiện chính sách (ngoài ra mới huy động các nguồn hợp pháp khác). Vì vậy nhận định 'hoàn toàn do doanh nghiệp tài trợ, ngân sách không tham gia' là sai. Các nhận định A, B, C đều đúng.",mn:"Kinh phí thu hút nhân tại: ngân sách nhà nước bảo đảm (không phải hoàn toàn xã hội hóa).",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, nhận định nào sau đây về cơ chế thu hút và sử dụng người có tài năng là KHÔNG đúng?",o:["Nhà nước có cơ chế đặc biệt để thu hút chuyên gia, nhà khoa học, sinh viên tốt nghiệp xuất sắc và nguồn nhân lực chất lượng cao khác Lưới t BCtC 2095 gi 12","Kinh phí thực hiện chính sách hoàn toàn do doanh nghiệp tài trợ, ngân sách nhà nước không tham gia","Chính phủ quy định khung cơ chế, chính sách thu hút, trọng dụng và đãi ngộ","Người có tài năng trong hoạt động công vụ phải đạt thành tích nổi bật thể hiện bằng kết quả, sản phẩm cụ thể"],c:1},{id:"vb08-37",s:"",cc:"liệu 1, Điều 3 và Điều 5 Luật t.dn bộ, công chức số 80/2025/QH15.",gt:"Bản chất chế độ công vụ theo vị trí việc làm: công chức được tuyển dụng vào vị trí việc làm; việc quản lý, đánh giá, bố trí, sử dụng gắn với vị trí việc làm, tiêu chuẩn chức danh, ngạch và kết quả, hiệu quả thực thi nhiệm vụ. Đây là định hướng xuyên suốt của Luật.",mn:"Công vụ theo vị trí việc làm: tuyển dụng - quản lý - đánh giá đều gắn với vị trí việc làm.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, phương án nào sau đây phản ánh ĐÚNG và ĐẦY ĐỦ nhất bản chất của chế độ công vụ theo vị trí việc làm?",o:["Công chức được tuyển dụng vào vị trí việc làm; việc quản lý, đánh giá, bố trí, sử dụng công chức gắn với vị trí việc làm, tiêu chuẩn chức danh, ngạch và kết quả, hiệu quả thực thi nhiệm vụ","Công chức được tuyển dụng và bố trí chủ yếu theo thâm niên công tác và bằng cấp","Công chức được quản lý theo ngạch, bậc lương mà không gắn với vị trí việc làm","Công chức được bổ nhiệm vào chức vụ lãnh đạo ngay khi được tuyển dụng"],c:0},{id:"vb08-38",s:"",cc:"Các khoản 7, 9, 10 Điều 5 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Cả ba từ ngữ luân chuyển, biệt phái, điều động đều được giải thích truong Luật, với nội hàm khác nhau: điều động (chuyến hắn), biệt phái (cử có thời hạn nguài cư quan quản lý), luân chuyển (cán bộ lãnh đạo, quản lý, để đào tạo, quy huạch).",mn:"3 khái niệm: điều động (chuyến hắn) — hiệt phái (có thời hạn) ~ luân chuyển (lãnh đạo, đào tạo). Lưới t BCtC 2095 gi 13",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, các nội dung sau có cùng là từ ngữ được giải thích trong Luật hay không: 'luân chuyển', 'biệt phái', 'điều động?",o:["Chỉ 'điều động' được giải thích","Chỉ luân chuyển' và biệt phái' được giải thích","Cả ba từ ngữ đều được giải thích trong Luật","Không từ ngữ nào được giải thích trong Luật"],c:2},{id:"vb08-39",s:"",cc:"Điều 2 và Điều 3 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Các nguyên tắc nền tảng: bảo đảm sự lãnh đạo của Đảng, quản lý của Nhà nước; thi hành công vụ tuân thủ Hiến pháp, pháp luật, công khai, minh bạch; quản lý gắn với vị trí việc làm, tiêu chuẩn chức danh, kết quả công việc; bình đẳng giới và ưu tiên người dân tộc thiểu số.",mn:"Nền tảng: Đảng lãnh đạo + tuân thủ PỊ., công khai + vị trí việc làm, kết quả + bình đẳng giới. Phạm vi phân I: Điều 6 đến Điều 1 Ï — nghĩa vụ của cán bộ, công chức đối với Đảng, Nhà nước và Nhân dân; nghĩa vụ trong thi hành công vụ; nghĩa vụ của người đứng đầu; các quyền về bảo đảm điều kiện thi hành công vụ, về tin hương, tiền thưởng và về nghỉ ngơi.",t:"m",q:"Theo Luật Cán bộ, công chức số 90/2025/QH15, phương án nào sau đây phản ánh ĐÚNG nhất các nguyên tắc nền tảng của chế độ cán bộ, công chức nước ta?",o:["Thi hành công vụ chủ yếu dựa vào ý chí của người đứng đầu cơ quan","Tuyển dụng và bố nhiệm chủ yếu theo thâm niên, bảng cấp; quản lý tập trung tuyệt đối, không phân cấp","Cán bộ, công chức hoạt động độc lập, không chịu sự lãnh đạo của Đảng và quản lý của Nhà nước","Bảo đảm sự lãnh đạo của Đảng, sự quản lý của Nhà nước; thi hành công vụ tuân thủ Hiến pháp, pháp luật, công khai, minh bạch; quản lý gắn với vị trí việc làm, tiêu chuẩn chức danh, kết quả công việc; thực hiện bình đẳng giới và ưu tiên người dân tộc thiểu số"],c:3},{id:"vb08-40",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC (Phân 1: Nghĩa vụ và quyền)",cc:"Khoản 1 Điều Ð Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Nghĩa vụ hàng đầu là tuyệt đối trung thành với Đảng Cộng sản Việt Nam, Nhà nước Cộng hòa xã hội chủ nghĩa Việt Nam; bảo vệ danh dự Tổ quốc, lợi ích quốc gia, dân tộc. Các nghĩa vụ ở phương án B, G, D cũng thuộc nhóm này nhưng không phải nội dung được đặt đầu tiên.",mn:"Nghĩa vụ đầu tiên: tuyệt đối trung thành với Đảng, Nhà nước; bảo vệ danh dự Tổ quốc.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, trong nhóm nghĩa vụ đối với Đảng, Nhà nước và Nhân dân, nghĩa vụ được đặt lên hàng đầu của cán bộ, công chức là gì?",o:["Tuyệt đối trung thành với Đảng Cộng sản Việt Nam, Nhà nước Cộng hòa xã hội chủ nghĩa Việt Nam; bảo vệ danh dự Tổ quốc, lợi ích quốc gia, dân tộc","Chấp hành nghiêm chỉnh đường lối, chủ trương, chính sách của Đảng và pháp luật của Nhà nước","Liên hệ chặt chẽ với Nhân dân, lắng nghe ý kiến và chịu sự giám sát của Nhân dân","Tôn trọng và bảo vệ quyền con người, quyền công dân, tận tụy phục vụ Nhân dân"],c:0},{id:"vb08-41",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC (Phân 1: Nghĩa vụ và quyền)",cc:"Điều 6 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Nhóm nghĩa vụ đối với Đảng, Nhà nước và Nhân dân gồm bốn nội dung tại phương án A. Phương án B là nghĩa vụ trong thi hành công vụ (Điều 7); phương án C là đạo đức công vụ (Điều 12); phương án D là nghĩa vụ của người đứng đầu (Điều B).",mn:'Nghĩa vụ với Đảng, NN, Nhân dân: trung thành - phục vụ Nhân dân - chịu giám sát — chấp hành đường lối, pháp luật. -, _— lm Luạt CDCC 2025 "rung 15',t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, các nội dung nào sau đây cùng thuộc nhóm nghĩa vụ của cán bộ, công chức đối với Đảng, Nhà nước và Nhân dân?",o:["Lãnh đạo, chỉ đạo tổ chức thực hiện nhiệm vụ; kiểm tra, đôn đốc việc thi hành công vụ","Thực hiện đúng, đầy đủ nhiệm vụ được giao; bảo vệ bí mật nhà nước; bảo vệ tài sản công","Có đạo đức trong sáng, cần, kiệm, liêm, chính, chí công vô tư","Tuyệt đối trung thành với Đảng, Nhà nước, bảo vệ danh dự Tổ quốc; tôn trọng, bảo vệ quyền con người, quyền công dân, tận tụy phục vụ Nhân dân; liên hệ chặt chẽ với Nhân dân, chịu sự giám sát của Nhân dân; chấp hành nghiêm chỉnh đường lối, chính sách của Đảng và pháp luật của Nhà nước"],c:3},{id:"vb08-42",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC (Phân 1: Nghĩa vụ và quyền)",cc:"Khoản 1 Điều 7 Luật Cán bộ, công chức số 90/2025/QH15.",gt:"Cán bộ, công chức phải thực hiện đúng, đầy đủ và chịu trách nhiệm về kết quả nhiệm vụ; chủ động nâng cao năng lực, trình độ; ứng dụng khoa học, công nghệ và chuyển đổi số trong thực thi nhiệm vụ. Đây là điểm mới gắn với yêu cầu hiện đại hóa nền công vụ.",mn:"Nghĩa vụ mới: ứng dụng KHCN, chuyển đổi số trong thực thi nhiệm vụ.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, trong nghĩa vụ khi thi hành công vụ, yêu cầu mới về ứng dụng công nghệ được quy định như thế nào đối với cán bộ, công chức?",o:["Chỉ cần thực hiện đúng nhiệm vụ được giao, không bắt buộc ứng dụng công nghệ","Phái chủ động nâng cao năng lực, trình độ chuyên môn, nghiệp vụ và ứng dụng khoa học, công nghệ, chuyển đổi số trong thực thi nhiệm vụ","Chỉ áp dụng đối với cán bộ, công chức làm việc trong lĩnh vực công nghệ thông tin","Việc ứng dụng công nghệ do người đứng đầu quyết định, cán bộ, công chức không có nghĩa vụ này"],c:1},{id:"vb08-43",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC (Phân 1: Nghĩa vụ và quyền)",cc:"Khoản 5 Điều 7 Luật Cán bộ, công chức số 80/2025/0H15.",gt:"Khi có căn cứ cho rằng quyết định trái pháp luật, cán bộ, công chức phải báo cáo bằng văn bản với người ra quyết định; nếu người ra quyết định vấn vêu cầu thi hành thì phải chấp hành, đồng thời báo cáo bằng văn bản với cấp trên trực tiếp và không phải chịu trách nhiệm về hậu quả. Người ra quyết định phải chịu trách nhiệm trước pháp luật.",mn:"Quyết định trái luật: báo cáo văn bản ¬ vẫn yêu cầu thì chấp hành!: báo cấp trên ¬ không chịu trách nhiệm hậu quả.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, khi cán bộ, công chức có căn cứ cho rằng quyết định của cấp trên là trái pháp luật thì phải xử lý như thế nào?",o:["Phải chấp hành ngay lập tức và chịu trách nhiệm liên đổi về hậu quả","Được quyền từ chối thi hành và không phải báo cáo với ai","Kịp thời báo cáo bằng văn bản với người ra quyết định; nếu người ra quyết định vẫn quyết định việc thi hành thì phải chấp hành nhưng đồng thời báo cáo bằng văn bản với cấp trên trực tiếp của người ra quyết định và không phải chịu trách nhiệm về hậu quả của việc thi hành","Báo cáo miệng với người ra quyết định, nếu không được chấp thuận thì ngừng thi hành"],c:2},{id:"vb08-44",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC (Phân 1: Nghĩa vụ và quyền)",cc:"Khoản 5 Điều 7 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Trong trường hợp này, người thi hành không phải chịu trách nhiệm về hậu quả; người ra quyết định phải chịu trách nhiệm trước pháp luật về quyết định của mình.",mn:"Đã báo cáo văn bản mà vẫn buộc thi hành: người ra quyết định chịu trách nhiệm.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, trong tình huống cán bộ, công chức đã báo cáo bằng văn bản về một quyết định mà mình cho là trái pháp luật nhưng người ra quyết định vẫn yêu cầu thi hành, ai phải chịu trách nhiệm trước pháp luật về quyết định đó?",o:["Cả người ra quyết định và người thi hành cùng chịu trách nhiệm","Người thi hành quyết định phải chịu trách nhiệm về hậu quả Lưới t BCtC 2095 gi 16","Người ra quyết định phải chịu trách nhiệm trước pháp luật về quyết định của mình","Cấp trên trực tiếp của người ra quyết định phải chịu trách nhiệm"],c:2},{id:"vb08-45",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC (Phân 1: Nghĩa vụ và quyền)",cc:"Điều 7 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Các nội dung tại phương án A thuộc nghĩa vụ trong thi hành công vụ (ý thức kỷ luật, bảo vệ bí mật nhà nước, bảo vệ tài sản công...). Phương án B là nghĩa vụ với Đảng, Nhà nước, Nhân dân; (› là đạo đức công vụ; I) là nghĩa vụ của người đứng đầu.",mn:"Thi hành công vụ: kỷ luật - bảo vệ bí mật NN ~ báo về tài sản công - chấp hành quyết định cấp trên.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, các nội dung nào sau đây cùng thuộc nghĩa vụ của cán bộ, công chức trong thi hành công vụ?",o:["Tuyệt đối trung thành với Đảng và Nhà nước; bảo vệ danh dự Tổ quốc","Có ý thức tổ chức kỷ luật, chấp hành nội quy, quy chế; báo cáo người có thẩm quyền khi phát hiện hành vi vi phạm pháp luật; bảo vệ bí mật nhà nước; bảo vệ, quản lý và sử dụng hiệu quả, tiết kiệm tài sản công","Có đạo đức trong sáng, thực hiện cần, kiệm, liêm, chính","Tổ chức thực hiện các biện pháp phòng, chống tham nhũng trong cơ quan"],c:1},{id:"vb08-46",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC (Phân 1: Nghĩa vụ và quyền)",cc:"Điều 8 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Người đứng đầu phải thực hiện Điều 6, Điều 7 và thêm các nghĩa vụ: lãnh đạo, chỉ đạo và chịu trách nhiệm về kết quả hoạt động của cơ quan; kiểm tra, đôn đốc, hướng dẫn; tổ chức phòng, chống quan liêu, tham nhũng, tiêu cực, lãng phí và chịu trách nhiệm nêu để xảy ra trong phạm vi quản lý.",mn:'Người đứng đầu: lãnh đạo, chịu trách nhiệm kết quả + kiểm tra, đôn đốc + chịu trách nhiệm nêu để xảy ra tham nhũng, lãng phí. Luút CBCC 2025 "rung 17',t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, cán bộ, công chức là người đứng đầu cơ quan, tổ chức, đơn vị, ngoài việc thực hiện các nghĩa vụ chung, còn phải thực hiện những nghĩa vụ riêng nào sau đây?",o:["Lãnh đạo, chỉ đạo tổ chức thực hiện nhiệm vụ và chịu trách nhiệm về kết quả hoạt động của cơ quan; kiểm tra, đôn đốc, hướng dẫn việc thi hành công vụ: tổ chức thực hiện các biện pháp phòng, chống quan liêu, tham nhũng, tiêu cực, lãng phí và chịu trách nhiệm nêu để xảy ra trong phạm vi quản lý","Chỉ cần hoàn thành nhiệm vụ cá nhân được giao như các cán bộ, công chức khác","Chỉ chịu trách nhiệm về hành vi của cá nhân mình, không chịu trách nhiệm về cấp dưới","Tuyệt đối trung thành với Đảng và Nhà nước, bảo vệ danh dự Tổ quốc"],c:0},{id:"vb08-47",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC (Phân 1: Nghĩa vụ và quyền)",cc:"Khoản 5 Điều 8 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Người đứng đầu phải thường xuyên rà soát để cắt giảm tối đa thủ tục hành chính, tạo thuận lợi cho người dân, doanh nghiệp và lãnh đạo, chỉ đạo, chịu trách nhiệm về việc giải quyết thủ tục hành chính thuộc phạm vi quản lý. Đẩy là điểm nhân về cải cách hành chính.",mn:"Người đứng đầu: cắt giảm tối đa thủ tục hành chính, chịu trách nhiệm giải quyết TTHC.",t:"m",q:"Theo Luật Cán bộ, công chức số 90/2025/QH15, người đứng đầu cơ quan, tổ chức, đơn vị có nghĩa vụ nào sau đây liên quan đến thủ tục hành chính?",o:["Chỉ giải quyết thủ tục hành chính khi có khiếu nại của người dân","Chỉ cần ban hành quy chế về thủ tục hành chính và giao cấp dưới thực hiện","Duy trì ổn định các thủ tục hành chính hiện có để bảo đảm tính thống nhất","Thường xuyên rà soát để bảo đảm cắt giảm tối đa thủ tục hành chính, tạo điều kiện thuận lợi cho người dân, doanh nghiệp; lãnh đạo, chỉ đạo và chịu trách nhiệm về việc giải quyết thủ tục hành chính của cơ quan thuộc phạm vi quản lý"],c:3},{id:"vb08-48",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC (Phân 1: Nghĩa vụ và quyền)",cc:"Điều 9 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Nhóm quyền về bảo đảm điều kiện thi hành công vụ gồm: giao quyền tương xứng nhiệm vụ; trang thiết bị, phương tiện: nhà ở công vụ: cung cấp thông tin, dữ liệu; đào tạo, bồi dưỡng: được pháp luật báo về: được xem xét loại trừ, miễn, giảm trách nhiệm. Phương án B, D thuộc quyền về tiền lương: C thuộc quyền nghỉ ngơi.",mn:"Điều kiện thi hành công vụ: quyền tương xứng - trang thiết bị - nhà ở công vụ - thông tin - được bảo vệ.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, quyền nào sau đây của cán bộ, công chức thuộc nhóm quyền về bảo đảm điều kiện thi hành công vụ?",o:["Được hưởng tiền lương, tiền thưởng theo kết quả, sản phẩm của vị trí việc làm","Được giao quyền tương xứng với nhiệm vụ được giao; được bảo đảm trang thiết bị làm việc, phương tiện đi lại; được bố trí hoặc thuê nhà ở công vụ; được cung cấp thông tin, dữ liệu; được pháp luật bảo vệ khi thi hành công vụ","Được nghỉ hằng năm, nghị lỗ, tết, nghỉ việc riêng theo quy định","Được hưởng phụ cấp khi làm việc ở vùng có điều kiện kinh tế - xã hội đặc biệt khó khăn"],c:1},{id:"vb08-49",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC (Phân 1: Nghĩa vụ và quyền)",cc:"Khoản 7 Điều 9 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Cán bộ, công chức được xem xét loại trừ, miễn, giảm trách nhiệm theo quy định của pháp luật và của cấp có thẩm quyền - gắn với cơ chế bảo vệ Lưới t BCtC 2095 gi 18 người dám nghĩ, dám làm, dám chịu trách nhiệm vì lợi ích chung. Đây không phải là miễn trừ trách nhiệm tuyệt đối.",mn:"Quyền: được xem xét loại trừ, miễn, giảm trách nhiệm (không phải miễn trừ tuyệt đối).",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, một trong những quyền mời nhằm bảo vệ cán bộ, công chức dám nghĩ, dám làm là quyền nào sau đây?",o:["Được miễn trừ trách nhiệm trong mọi trường hợp khi thi hành công vụ","Được tự quyết định mới vấn đề thuộc thẩm quyền mà không chịu trách nhiệm","Được xem xét loại trừ, miễn, giảm trách nhiệm theo quy định của pháp luật và của cấp có thẩm quyền","Được quyền từ chối thi hành mới quyết định của cấp trên"],c:2},{id:"vb08-50",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC (Phân 1: Nghĩa vụ và quyền)",cc:"Khoản! Điều 10 Luật Cán bộ, công chức số 90/2025/QH15.",gt:"Cán bộ, công chức được hưởng tiền lương, tiền thưởng và thu nhập khác theo kết quả, sản phẩm của vị trí việc làm đảm nhiệm, phù hợp với điều kiện phát triển kinh tế - xã hội. Đây là điểm mới: trả lương theo vị trí việc làm và kết quả, không thuận theo thâm niên, bằng cấp.",mn:"Lương, thường: theo kết quả, sản phẩm của vị trí việc làm.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, tiền lương, tiền thưởng và các khoản thu nhập khác của cán bộ, công chức được hưởng theo căn cứ nào?",o:["Theo kết quả, sản phẩm của vị trí việc làm đảm nhiệm, phù hợp với điều kiện phát triển kinh tế - xã hội của đất nước, địa phương","Theo thâm niên công tác và bằng cấp chuyên môn","Theo ngạch, bậc lương và hệ số phụ cấp chức vụ","Theo thỏa thuận giữa cán bộ, công chức và cơ quan sử dụng"],c:0},{id:"vb08-51",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC (Phân 1: Nghĩa vụ và quyền)",cc:"Khoản 3 Điều 10 Luật Cán bộ, công chức số 60/2025/QH15.",gt:"Cán bộ, công chức làm việc ở vùng đặc biệt khó khăn hoặc trong nghề, công việc nặng nhọc, độc hại, nguy hiểm được hưởng phụ cấp và chính sách ưu đãi theo quy định.",mn:"Vùng khó khăn'nghề độc hại: hưởng phụ cấp + chính sách ưu đãi.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, cán bộ, công chức làm việc ở vùng có điều kiện kinh tế - xã hội đặc biệt khó khăn hoặc trong các nghề, công việc nặng nhọc, độc hại, nguy hiểm được hưởng chế độ gì?",o:["Được ưu tiên bổ nhiệm vào chức vụ lãnh đạo, quản lý","Được nâng lương trước thời hạn trong mọi trường hợp","Được giảm thời gian làm việc và tăng số ngày nghỉ phép","Được hưởng phụ cấp và chính sách ưu đãi theo quy định"],c:3},{id:"vb08-52",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC (Phân 1: Nghĩa vụ và quyền)",cc:"Khoản 1 Điều 11 Luật Cán bộ, công chức số 80/2025/QH15.",gt:'Trường hợp do yêu cầu nhiệm vụ không nghỉ hoặc nghỉ không hết phép năm, cán bộ, công chức ngoài tiền lương còn được thanh toán thêm một khoản tiền bằng tiền lương cho những ngày không nghỉ. Luôi CBCC 2025 "nang 19 gi 19',mn:"Không nghỉ hết phép nam do nhiệm vụ: được thanh toán thêm tiền cho ngày không nghỉ.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, trường hợp do yêu cầu nhiệm vụ mà cán bộ, công chức không sử dụng hoặc sử dụng không hết số ngày nghỉ hằng năm thì được giải quyết như thế nào?",o:["Không được thanh toán và cung không được cộng dồn","Được cộng dồn số ngày nghỉ chưa sử dụng sang năm sau","Ngoài tiền lương, còn được thanh toán thêm một khoản tiền bằng tiền lương cho những ngày không nghỉ","Được nghỉ bù vào thời gian thích hợp do cơ quan bố trí"],c:2},{id:"vb08-53",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC (Phân 1: Nghĩa vụ và quyền)",cc:"Khoản 2 Điều 11 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Cán bộ, công chức bị thương hoặc hy sinh trong khi thi hành công vụ thì được xem xét hưởng chế độ, chính sách như thương binh hoặc được xem xét để công nhận là liệt sĩ.",mn:"Bị thương/hy sinh khi thi hành công vụ: như thương binh / liệt sĩ.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, trường hợp cán bộ, công chức bị thương hoặc hy sinh trong khi thi hành công vụ thì được xem xét hưởng chế độ, chính sách như thế nào?",o:["Được nâng lương và bổ nhiệm vào chức vụ cao hơn","Được hưởng trợ cấp một lần theo mức do cơ quan quy định","Được hưởng chế độ bảo hiểm tai nạn lao động thông thường","Được xem xét hưởng chế độ, chính sách như thương binh hoặc được xem xét để công nhận là liệt sĩ"],c:3},{id:"vb08-54",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC (Phân 1: Nghĩa vụ và quyền)",cc:"Khoản 2 Điều 11 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Cán bộ, công chức được bảo đảm quyền học tập, nghiên cứu khoa học, tham gia các hoạt động kinh tế, xã hội (trừ các hoạt động bị cấm theo quy định về những việc không được làm); được hưởng chính sách ưu đãi về nhà ở, bảo hiểm xã hội, bảo hiểm y tế và chế độ khác. Quyền tham gia hoạt động kinh tế, xã hội có giới hạn, không phải không hạn chế.",mn:"Quyền khác: học tập, nghiên cứu, hoạt động KT-XH (có giới hạn) + bảo hiểm, ưu đãi nhà ở.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, ngoài quyền nghỉ ngơi, cán bộ, công chức còn được bảo đảm các quyền nào sau đây?",o:["Quyền tự do kinh doanh trong mọi ngành nghề mà pháp luật không cấm","Quyền học tập, nghiên cứu khoa học, tham gia các hoạt động kinh tế, xã hội (trừ các hoạt động bị cấm); hưởng chính sách ưu đãi về nhà ở, chế độ bảo hiểm xã hội, bảo hiểm y tế và chế độ khác theo quy định","Quyền thành lập và quản lý doanh nghiệp trong thời gian công tác","Quyền tham gia mọi hoạt động kinh tế, xã hội không hạn chế"],c:1},{id:"vb08-55",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC (Phân 1: Nghĩa vụ và quyền)",cc:"Điều 9 và Điều 10 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Quyền hưởng tiền lương, tiền thưởng theo kết quả, sản phẩm của vị trí việc làm thuộc nhóm quyền về tiền lương, tiền thưởng (Điều 10), không thuộc Lưới t BCtC 2095 gi 20 nhóm quyền về bảo đảm điều kiện thi hành công vụ (Điều 9). Các phương án A, B, CC đều thuộc Điều 9.",mn:"Tiền lương, thưởng là quyên riêng (Điều 10), không nằm tong nhóm 'điều kiện thi hành công vụ:.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, các quyền nào sau đây cùng thuộc nhóm quyền về bảo đảm điều kiện thi hành công vụ của cán bộ, công chức, NGOẠI TRỪ quyền nào?",o:["Được hưởng tiền lương, tiền thưởng theo kết quả, sản phẩm của vị trí việc làm","Được cung cấp thông tin, dữ liệu liên quan đến nhiệm vụ, quyền hạn được giao","Được pháp luật bảo vệ khi thi hành công vụ","Được giao quyền tương xứng với nhiệm vụ được giao"],c:0},{id:"vb08-56",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC (Phân 1: Nghĩa vụ và quyền)",cc:"Khoản 5 Điều 7 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Ông K phải báo cáo bằng văn bản với người ra quyết định; nếu người đó vẫn quyết định thi hành thì chấp hành và báo cáo bằng văn bản với cấp trên trực tiếp của người ra quyết định. Khi dó ông K không phải chịu trách nhiệm về hậu quả.",mn:"Đúng quy trình: báo cáo văn bản. › vẫn buộc thi hành thì chấp hành + báo cấp trên trực tiếp.",t:"m",q:"Một tình huống: Ông K là công chức, nhận được quyết định bằng văn bản của cấp trên mà ông có căn cứ cho rằng trái pháp luật. Theo Luật Cán bộ, công chức số 80/2025/QH15, hành động đúng dẫn của ông K là gì?",o:["Từ chối thi hành quyết định và tự ý ngừng công việc","Kịp thời báo cáo bằng văn bản với người ra quyết định; nếu người đó vẫn quyết định thi hành thì chấp hành và báo cáo bằng văn bản với cấp trên trực tiếp của người ra quyết định","Thi hành ngày quyết định mà không cần báo cáo","Báo cáo miệng cho đồng nghiệp để cung phán đối quyết định"],c:1},{id:"vb08-57",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC (Phân 1: Nghĩa vụ và quyền)",cc:"Khoản 4 Điều 6 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Nghĩa vụ chấp hành nghiêm chỉnh đường lối, chủ trương, chính sách của Đảng và pháp luật của Nhà nước thuộc nhóm nghĩa vụ đối với Đảng, Nhà nước và Nhân dân (Điều 6).",mn:"Chấp hành đường lối, chính sách, pháp luật = nghĩa vụ với Đảng, Nhà nước, Nhân dân.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, nghĩa vụ 'chấp hành nghiêm chỉnh đường lối, chủ trương, chính sách của Đảng và pháp luật của Nhà nước thuộc nhóm nghĩa vụ nào?",o:["Nghĩa vụ của cán bộ, công chức đối với Đảng, Nhà nước và Nhân dân","Nghĩa vụ của cán bộ, công chức trong thi hành công vụ","Nghĩa vụ của cán bộ, công chức là người đứng đầu","Nghĩa vụ về đạo đức công vụ"],c:0},{id:"vb08-58",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC (Phân 1: Nghĩa vụ và quyền)",cc:"Khoản 4 Điều 8 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Người đứng đầu phải xử lý kịp thời, nghiêm minh cán bộ, công chức thuộc thẩm quyền quản lý có hành vi vi phạm kỷ luật, pháp luật, có thái độ quan liêu, hách dịch, cửa quyền, gây phiền hà cho công dân; đồng thời tổ chức thực hiện dân chủ cơ sở, văn hóa công sở.",mn:"Người đứng đầu: xử lý kịp thời, nghiêm minh cấp dưới vi phạm, hách dịch, gây phiền hà.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, người đứng đầu cơ quan, tổ chức, đơn vị có nghĩa vụ nào sau đây trong việc xử lý cán bộ, công chức vi phạm?",o:["Báo cáo cấp trên để cấp trên xử lý, không trực tiếp xử lý","Chỉ xử lý khi có đơn tố cáo của người dân","Xử lý kịp thời, nghiêm minh cán bộ, công chức thuộc thẩm quyền quản lý có hành vi vi phạm kỷ luật, pháp luật, có thái độ quan liêu, hách dịch, cửa quyền, gây phiền hà cho công dân","Chí nhắc nhớ, không áp dụng hình thức xử lý kỷ luật"],c:2},{id:"vb08-59",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC (Phân 1: Nghĩa vụ và quyền)",cc:"Điều 9 Luật Cán bộ. công chức số 80/2025/QH15.",gt:"Các nội dung tại phương án A thuộc quyền về bảo đảm điều kiện thi hành công vụ (Điều 9). Phương án B thuộc quyền về tiền lương (Điều 10); C, D thuộc quyền về nghỉ ngơi và các quyền khác (Điều 11).",mn:"Điều kiện thi hành công vụ: đào tạo — được bảo vệ — xem xét loại trừ, miễn, giảm trách nhiệm.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, các nội dung nào sau đây cùng thuộc quyền của cán bộ, công chức về bảo đảm điều kiện thi hành công vụ?",o:["Được hưởng chế độ bảo hiểm xã hội, bảo hiểm y tế theo quy định","Được hưởng tiền làm thêm giờ, tiền lương làm việc vào ban đêm, công tác phí","Được nghỉ hằng năm, nghị lỗ, tết, nghỉ việc riêng theo quy định của pháp luật về lao động","Được tham gia đào tạo, bồi dưỡng nâng cao trình độ; được pháp luật bảo vệ khi thi hành công vụ; được xem xét loại trừ, miễn, giảm trách nhiệm"],c:3},{id:"vb08-60",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC (Phân 1: Nghĩa vụ và quyền)",cc:"Khoản 4 Điều 7 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Nghĩa vụ bảo vệ, quản lý và sử dụng hiệu quả, tiết kiệm tài sản công được giao thuộc nhóm nghĩa vụ trong thi hành công vụ (Điều 7).",mn:"Bảo vệ, tiết kiệm tài sản công = nghĩa vụ trong thi hành công vụ.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, nghĩa vụ 'bảo vệ, quản lý và sử dụng hiệu quả, tiết kiệm tài sản công được giao' thuộc nhóm nghĩa vụ nào?",o:["Nghĩa vụ của cán bộ, công chức là người đứng đầu","Nghĩa vụ của cán bộ, công chức đối với Đảng, Nhà nước và Nhân dân","Nghĩa vụ của cán bộ, công chức trong thi hành công vụ","Nghĩa vụ về văn hóa giao tiếp"],c:2},{id:"vb08-61",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC (Phân 1: Nghĩa vụ và quyền)",cc:'Điều 9, Điều 10, Điều 11 và Điều 14 Luật Cán bộ, công chức số 80/2025/QH15. Luôi CBCC 2025 "rang 22',gt:"Cán bộ, công chức không được tự do thành lập, quản lý, điều hành doanh nghiệp trong thời gian công tác (thuộc những việc không được làm theo pháp luật về phòng, chống tham nhũng). Các quyền A, B, C đều đúng.",mn:"CBCC không được thành lập, quản lý doanh nghiệp trong thời gian công tác.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, nhận định nào sau đây về quyền của cán bộ, công chức là KHÔNG đúng?",o:["Được giao quyền tương xứng với nhiệm vụ được giao","Được bố trí hoặc được thuê nhà ở công vụ theo quy định","Được hưởng tiền lương, tiền thưởng theo kết quả, sản phẩm của vị trí việc làm","Được tự do thành lập, tham gia quản lý, điều hành doanh nghiệp trong thời gian công tác"],c:3},{id:"vb08-62",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC (Phân 1: Nghĩa vụ và quyền)",cc:"Khoản 2 Điều 7 Luột Cán bộ, công chức số 80/2025/QH15.",gt:"Nghĩa vụ báo cáo người có thẩm quyền khi phát hiện hành vi vi phạm pháp luật gắn với yêu cầu có ý thức tổ chức kỷ luật, chấp hành nội quy, quy chế và bảo vệ bí mật nhà nước trong thi hành công vụ (Điều 7).",mn:"Phát hiện vi phạm + báo cáo: gắn với ý thức kỷ luật trong thi hành công vụ.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, nghĩa vụ báo cáo người có thẩm quyền khi phát hiện hành vi vi phạm pháp luật trong cơ quan, tổ chức, đơn vị' gắn với yêu cầu nào sau đây?",o:["Có ý thức tổ chức kỷ luật, nghiêm chỉnh chấp hành nội quy, quy chế và bảo vệ bí mật nhà nước","Tuyệt đối trung thành với Đảng và Nhà nước","Có đạo đức trong sáng, cần, kiệm, liêm, chính","Lãnh đạo, chỉ đạo tổ chức thực hiện nhiệm vụ được giao"],c:0},{id:"vb08-63",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC (Phân 1: Nghĩa vụ và quyền)",cc:"Khoản 3 Điều 8 Luật Cán bộ, công chức số 80/2025/00H15.",gt:"Người đứng đầu phải tổ chức thực hiện các biện pháp phòng, chống quan liêu, tham nhũng, tiêu cực, thực hành tiết kiệm, chống lãng phí và chịu trách nhiệm về việc để xảy ra các hiện tượng đó trong phạm vi quản lý — đề cao trách nhiệm của người đứng đầu.",mn:"Người đứng đầu chịu trách nhiệm nêu để xảy ra tham nhũng, lãng phí trong phạm vi quản lý.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, người đứng đầu cơ quan, tổ chức, đơn vị chịu trách nhiệm như thế nào nếu để xảy ra quan liêu, tham nhũng, tiêu cực, lãng phí trong phạm vi quản lý?",o:["Không phải chịu trách nhiệm nếu không trực tiếp thực hiện hành vi","Phái chịu trách nhiệm về việc để xảy ra quan liêu, tham nhũng, tiêu cực, lãng phí trong cơ quan, tổ chức, đơn vị thuộc phạm vi quản lý","Chỉ chịu trách nhiệm khi có kết luận của cơ quan thanh tra","Chỉ chịu trách nhiệm liên đới ở mức nhắc nhở"],c:1},{id:"vb08-64",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC (Phân 1: Nghĩa vụ và quyền)",cc:"Điều 10 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Quyền về tiền lương gồm: tiền lương, tiền thưởng, thu nhập khác theo kết quả, sản phẩm của vị trí việc làm; tiền làm thêm giờ, làm việc ban đêm, công tác phí; phụ cấp, chính sách ưu đãi khi làm việc ở vùng đặc biệt khó khăn hoặc nghề nặng nhọc, độc hại, nguy hiểm.",mn:"Tiền lương: theo kết quả vị trí việc làm + làm thêm/ban đêm + phụ cấp vùng, nghề độc hại.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, quyền của cán bộ, công chức về tiền lương bao gồm các nội dung nào sau đây?",o:["Được hưởng lương cố định theo ngạch, bậc không phù thuộc kết quả công việc","Được hưởng lương theo thâm niên và phụ cấp chức vụ","Được hưởng tiền lương, tiền thưởng và thu nhập khác theo kết quả, sản phẩm của vị trí việc làm; được hưởng tiền làm thêm giờ, tiền lương làm việc vào ban đêm, công tác phí và các chế độ khác; được hưởng phụ cấp, chính sách ưu đãi khi làm việc ở vùng đặc biệt khó khăn hoặc nghề độc hại, nguy hiểm","Được hưởng lương theo thỏa thuận với người đứng đầu cơ quan Lưới t BCtC 2095 gi 23"],c:2},{id:"vb08-65",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC (Phân 1: Nghĩa vụ và quyền)",cc:"Khoản! Điều 1Í Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Cán bộ, công chức được nghỉ hằng năm, nghỉ lễ, tết, nghỉ việc riêng, nghỉ không hưởng lương theo quy định của pháp luật về lao động.",mn:"Các loại nghị: hằng năm - lễ, tết - việc riêng - không hưởng lương.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, cán bộ, công chức được nghỉ những loại nghỉ nào theo quy định của pháp luật về lao động?",o:["Nghỉ hằng năm, nghỉ lễ, tết và nghỉ hưu sớm","Chí nghỉ hằng năm và nghị lỗ, tết","Chỉ nghỉ việc riêng và nghỉ không hưởng lương","Nghỉ hằng năm, nghỉ lễ, tết, nghỉ việc riêng, nghỉ không hưởng lương"],c:3},{id:"vb08-66",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC (Phân 1: Nghĩa vụ và quyền)",cc:"Điều 8 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Cả ba đều thuộc nghĩa vụ của người đứng đầu: lãnh đạo, chỉ đạo và chịu trách nhiệm về kết quả hoạt động: cắt giảm tối đa thủ tục hành chính; giải quyết kịp thời khiếu nại, tố cáo, kiến nghị của cá nhân, tổ chức.",mn:"Người đứng đầu: lãnh đầu, chịu trách nhiệm + cắt giảm TTHC = giải quyết khiếu nại, tố cáo.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, các nội dung sau có cùng thuộc nghĩa vụ của người đứng đầu cơ quan, tổ chức, đơn vị hay không: (i) lãnh đạo, chỉ đạo và chịu trách nhiệm về kết quả hoạt động; (ii) cắt giảm tối đa thủ tục hành chính; (iii) giải quyết kịp thời khiếu nại, tố cáo, kiến nghị?",o:["Chỉ nội dung (I) đúng","Cả ba nội dung đều thuộc nghĩa vụ của người đứng đầu","Chỉ nội dung (i) và (ii) đúng","Không nội dung nào thuộc nghĩa vụ của người đứng đầu"],c:1},{id:"vb08-67",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC (Phân 1: Nghĩa vụ và quyền)",cc:"Cóc diều từ 6 đến!I Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Định hướng: cán bộ, công chức vừa có nghĩa vụ (trung thành, phục vụ Nhân dân, thực hiện nhiệm vụ, ứng dụng công nghệ, chấp hành quyết định cấp trên), vừa được bảo đảm quyền (điều kiện thi hành công vụ, tiền lương theo vị trí việc làm và kết quả, nghỉ ngơi, được bảo vệ). Nghĩa vụ và quyền gắn liên với nhau.",mn:'Nghĩa vụ ‹- quyền sống hành; lương theo vị trí việc làm và kết quả công việc. Luật CBCC 2025 "raại 725 (Phân 2: Đạo đức, văn hóa giao tiếp và những việc không được làm) Phạm vi phân 2: Điều 12 đến Điều 14 — đạo đức công vụ; văn hóa giao tiếp ở công sở và với Nhân dân; những việc cần bộ, công chức không được làm.',t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, phương án nào sau đây phản ánh ĐÚNG và ĐẦY ĐỦ nhất định hướng về nghĩa vụ và quyền của cán bộ, công chức?",o:["Cán bộ, công chức có nghĩa vụ trung thành với Đảng, Nhà nước, tận tụy phục vụ Nhân dân, thực hiện đúng nhiệm vụ, ứng dụng công nghệ, chấp hành quyết định cấp trên; đồng thời được bảo đảm điều kiện thi hành công vụ, hưởng tiền lương theo vị trí việc làm và kết quả công việc, được nghỉ ngơi và bảo vệ khi thi hành công vụ","Cán bộ, công chức chỉ có nghĩa vụ chấp hành mệnh lệnh, không có quyền lợi gì gắn với kết quả công việc",'Cán bộ, công chức được hướng mới quyền lợi mà không gắn với nghĩa vụ và trách nhiệm Luôi CBCC 2025 "nÉgg 24',"Nghĩa vụ và quyền của cán bộ, công chức do người đứng đầu cơ quan tự quy định"],c:0},{id:"vb08-68",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 1 Điều 12 Luật Còn bộ, công chức số 80/2025/QH15.",gt:"Cán bộ, công chức phải có đạo đức trong sáng, mẫu mực, thực hiện cần, kiệm, liêm, chính, chí công vô tư trong thực thi công vụ. Đây là cụm từ chuẩn về đạo đức công vụ, cần thuộc chính xác.",mn:"Đạo đức công vụ: căn - kiểm - liêm ~- chính - chí công vô tư.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, về đạo đức công vụ, cán bộ, công chức phải có đạo đức trong sáng, mẫu mực, thực hiện [......... | trong thực thi công vụ.",o:["cần, kiệm, liêm, chính, chí công vô tư","dân chủ, công khai, minh bạch","đoàn kết, kỷ luật, kỷ cương","trung thực, khách quan, công bằng"],c:0},{id:"vb08-69",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 2 ‡)ieu 12 Luật C an bộ, công chức số 80/2025/QH15.",gt:"Vêu cầu đạo đức công vụ gồm: yêu nước, trung thành với Tổ quốc, tận tụy phục vụ Nhân dân; có bản lĩnh, tinh thần đổi mới, sáng tạo, hội nhập quốc tế; đoàn kết, kỷ luật, kỷ cương; gương mẫu, không ngừng tu dưỡng, học tập suốt đời. Phương án D là văn hóa giao tiếp; C là nghĩa vụ thi hành công vụ; D là nghĩa vụ với Nhân dân.",mn:"Đạu đức: yêu nước, trung thành - đổi mới, sáng tạo — đoàn kết, kỷ cương — học tập suốt đời.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, các phẩm chất nào sau đây cùng thuộc yêu cầu về đạo đức công vụ của cán bộ, công chức?",o:["Liên hệ chặt chẽ với Nhân dân, chịu sự giám sát của Nhân dân","Có tác phong lịch sự, đeo thể công chức, ngôn ngữ giao tiếp chuẩn mực","Thực hiện đúng nhiệm vụ được giao, bảo vệ bí mật nhà nước, bảo vệ tài sản công","Yêu nước, trung thành với Tổ quốc, tôn trọng và tận tụy phục vụ Nhân dân; có bản lĩnh, tinh thần đổi mới, sáng tạo, hội nhập quốc tế; đoàn kết, kỷ luật, kỷ cương; gương mẫu, không ngừng tu dưỡng, học tập suốt đời"],c:3},{id:"vb08-70",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:'Khoản 1 Điều 13 Luật Còn bộ, công chức số 00/2025/QH15. Luôi CBCC 2025 "rang 20',gt:"Văn hóa giao tiếp ở công sở: thái độ lịch sự, tôn trọng đồng nghiệp; lắng nghe ý kiến của đồng nghiệp; công bằng, vô tư, khách quan khi nhận xét, đánh giá đồng nghiệp. Các phương án B, C, D thuộc văn hóa giao tiếp với Nhân dân.",mn:"Ở công sở: lịch sự, tôn trụng + lắng nghe + công bằng, vô tư, khách quan với đồng nghiệp.",t:"m",q:"Theo ILuật Cán bộ, công chức số 80/2025/QH15, trong văn hóa giao tiếp ở công sở, cán bộ, công chức phải tuân thủ yêu cầu nào sau đây?",o:["Tôn trọng, lắng nghe và gần gũi với Nhân dân, ngôn ngữ giao tiếp chuẩn mực","Đeo huy hiệu, phù hiệu, cấp hiệu hoặc thẻ công chức khi làm việc","Có thái độ lịch sự, tôn trọng đồng nghiệp; lắng nghe ý kiến của đồng nghiệp; công bằng, vô tư, khách quan khi nhận xét, đánh giá đồng nghiệp","Không hách dịch, cửa quyền, gây phiền hà cho người dân, doanh nghiệp"],c:2},{id:"vb08-71",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điểm aq khoản 2 Điều 13 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Khi thi hành công vụ, cán bộ, công chức phải đeo huy hiệu, phù hiệu, cấp hiệu hoặc thẻ công chức; có tác phong lịch sự; giữ gìn uy tín, danh dự của cơ quan và đồng nghiệp.",mn:"Khi thi hành công vụ: đeo huy hiệu/phủ hiệu/cấp hiệu/thể công chức.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, khi thi hành công vụ, cán bộ, công chức phải đeo [........ ]; có tác phong lịch sự; giữ gìn uy tín, danh dự của cơ quan, tổ chức, đơn vị và đồng nghiệp.",o:["biến tên và logo cơ quan","huy hiệu, phù hiệu, cấp hiệu hoặc thẻ công chức","thể ngành và giấy giới thiệu công tác","phù hiện và giấy chứng nhận chức vụ"],c:1},{id:"vb08-72",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điểm b khoản 2 Điều 13 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Khi giao tiếp với Nhân dân, cán bộ, công chức phải tôn trọng, lắng nghe, gần gũi; nghiêm túc, khiêm tốn; ngôn ngữ giao tiếp phải chuẩn mực, rõ ràng, mạch lạc.",mn:"Ngôn ngữ với Nhân dân: chuẩn mực — rõ ràng — mạch lạc.",t:"m",q:"Theo Luật Cán bộ, công chức số 90/2025/QH15, trong văn hóa giao tiếp với Nhân dân, ngôn ngữ giao tiếp của cán bộ, công chức phải bảo đảm yêu cầu nào sau đây?",o:["Lịch sự, trang nghiêm, đúng mức","Trang trọng, hành chính, dung thể thức","Ngăn gọn, sức tích, đầy đủ","Chuẩn mực, rõ ràng, mạch lạc"],c:3},{id:"vb08-73",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điểm c khoản 2 Điều 13 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Hiện định nghiêm cấm hành vi hách dịch, cửa quyền, thiếu trách nhiệm, gây khó khăn, phiền hà cho người dân, doanh nghiệp khi thi hành công vụ. Các hành vi B, C, D là chuẩn mực ứng xử dụng.",mn:"Cấm: hách dịch - cửa quyền — gây phiền hà cho dân, doanh nghiệp. Lưới t BCtC 2095 gi 27",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, trong giao tiếp với Nhân dân khi thi hành công vụ, hành vi nào sau đây bị NGHIÊM CẤM?",o:["Tôn trọng, lắng nghe ý kiến của người dân","Hách dịch, cửa quyền, thiếu trách nhiệm, gây khó khăn, phiền hà cho người dân, doanh nghiệp","Giải thích, hướng dẫn người dân thực hiện thủ tục","Giữ gìn uy tín, danh dự của cơ quan, đơn vị"],c:1},{id:"vb08-74",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 1 })ieu 14 Luật Cán bộ, công chức số 80/2025/(0H15.",gt:"Những việc không được làm gồm: trốn tránh, thoái thác, né tránh, đùn đẩy nhiệm vụ; gây bè phái, mất đoàn kết; tự ý nghỉ việc, bỏ việc; tham gia đình công; đăng tải, phát tán, phát ngôn thông tin sai lệch làm ảnh hưởng hình ảnh, uy tín. Các phương án B, Ở, D là nghĩa vụ phải làm.",mn:"Không được: trốn tránh, đùn đẩy — gây bè phái - tự ý bỏ việc — đình công — phát tán tin sai lệch.",t:"m",q:"Theo Luật Cán bộ, công chức số 90/2025/QH15, hành vi nào sau đây thuộc những việc cán bộ, công chức KHÔNG được làm?",o:["Trốn tránh, thoái thác, né tránh, đùn đẩy trong việc thực hiện chức trách, nhiệm vụ được giao; øây bè phái, mất đoàn kết; tự ý nghỉ việc, bỏ việc; tham gia đình công","Chủ động, sáng tạo trong thực hiện nhiệm vụ; phối hợp chặt chẽ với đồng nghiệp","Báo cáo người có thẩm quyền khi phát hiện hành vi vi phạm pháp luật","Bảo vệ, quản lý và sử dụng hiệu quả, tiết kiệm tài sản công"],c:0},{id:"vb08-75",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 5 Điều 14 Luật Cán bộ, công chức số 60/2025/QH15.",gt:"Cán bộ, công chức không được phân biệt đối xử dân tộc, giới tính, độ tuổi, khuyết tật, tôn giáo, tín ngưỡng, thành phần xã hội dưới mọi hình thức trong thi hành công vụ. Các phương án B, C, D là ứng xử dụng.",mn:"Cấm phân biệt: dân tộc - giới tính - độ tuổi — khuyết tật - tôn giáo, tín ngưỡng - thành phần xã hội.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, cán bộ, công chức KHÔNG được thực hiện hành vi nào sau đây liên quan đến phân biệt đối xử trong thi hành công vụ?",o:["Ưu tiên giải quyết thủ tục cho người khuyết tật theo quy định","Đối xử bình đẳng với mọi người dân khi giải quyết công việc","Phân biệt đối xử dân tộc, giới tính, độ tuổi, khuyết tật, tôn giáo, tín ngưỡng, thành phần xã hội dưới mọi hình thức","Tôn trọng quyền tự do tín ngưỡng, tôn giáo của người dân"],c:2},{id:"vb08-76",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 6 Điều 14 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Những việc không được làm liên quan đến sản xuất, kinh doanh, công tác nhân sự theo pháp luật về phòng, chống tham nhũng, thực hành tiết kiệm, chống lãng phí, bảo vệ bí mật nhà nước... được áp dụng trong thời gian công tác và sau khi thôi việc, nghỉ hưu. Đây là điểm quan trọng: ràng buộc kéo dài cả sau khi rời công vụ.",mn:'Việc không được làm về SXKD, nhân sự: cả trong công tác lần sau khi thôi việc, nghỉ hưu. Luôi CBCC 2025 "nÉgg 28',t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, những việc không được làm liên quan đến sản xuất, kinh doanh, công tác nhân sự được áp dụng trong khoảng thời gian nào?",o:["Chí sau khi thôi việc, nghỉ hưu","Chỉ trong thời gian công tác","Trong thời gian công tác và sau khi thôi việc, nghỉ hưu","Chỉ trong thời gian giữ chức vụ lãnh đạo, quản lý"],c:2},{id:"vb08-77",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 2 Điều 13 và khoản 1 Điều 8 Luật Còn bộ, công chức số 80/2025/QH15.",gt:"lành vi của bà T vi phạm văn hóa giao tiếp với Nhân dân (phải tôn trọng, lắng nghe, gần gũi, ngôn ngữ chuẩn mực) và thuộc hành vi hách dịch, cửa quyền, gây phiền hà bị nghiêm cấm khi thi hành công vụ.",mn:"Khó chịu, nội trống không. kéo dài thủ tục = hách dịch, cửa quyền, gây phiền hà ¬ bị cấm.",t:"m",q:"Một tình huống: Bà T là công chức tiếp nhận hồ sơ tại bộ phận một cửa. Khi một người dân lớn tuổi hỏi lại thủ tục, bà T tỏ thái độ khó chịu, nội trống không và cơ tình kéo dài thời gian giải quyết. Theo Luật Cán bộ, công chức số 80/2025/QH15, hành vi của bà T vi phạm quy định nào?",o:["Chỉ vi phạm nếu người dân có đơn khiếu nại","Không vi phạm, vì đây là quyền của công chức trong xử lý công việc","Chỉ vi phạm nội quy cơ quan, không liên quan đến văn hóa giao tiếp","Vi phạm văn hóa giao tiếp với Nhân dân và thuộc hành vi hách dịch, cửa quyền, gây phiền hà bị nghiêm cấm"],c:3},{id:"vb08-78",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 6 Điều 14 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Việc công chức thành lập, trực tiếp điều hành doanh nghiệp trong thời gian công tác, nhất là trong lĩnh vực mình quản lý, vi phạm những việc không được làm liên quan đến sản xuất, kinh doanh theo pháp luật về phòng, chống tham nhũng.",mn:"Công chức lập, điều hành doanh nghiệp trong thời gian công tác = vi phạm.",t:"m",q:"Một tình huống: Ông M là công chức, trong thời gian công tác đã đúng tên thành lập và trực tiếp điều hành một doanh nghiệp tư nhân hoạt động trong lĩnh vực mình quản lý. Theo Luật Cán bộ, công chức số 80/2025/QH15, việc làm của ông M được đánh giá như thế nào?",o:["Không vi phạm, vị công chức được tự do kinh doanh như mọi công dân","Vi phạm những việc không được làm liên quan đến sản xuất, kinh doanh theo quy định của pháp luật về phòng, chống tham nhũng","Chỉ vi phạm nếu doanh nghiệp do thua lỗ","Được phép nếu ông M không sử dụng giờ hành chính để điều hành"],c:1},{id:"vb08-79",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điều 7 và Điều 14 Luật Cán bộ, công chức số 80/2025/QH15. Lưới t BCtC 2095 gi 29",gt:"Ứng dụng khoa học, công nghệ và chuyển đổi số là nghĩa vụ phải làm trong thi hành công vụ (Điều 7), không phải việc bị cấm. Các phương án A, B, C đều là những việc không được làm (Điều 14).",mn:"Ứng dụng KHCN, chuyển đổi số là việc PHẢI làm, không phải việc bị cấm.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, các hành vi nào sau đây cùng thuộc những việc cán bộ, công chức không được làm, NGOẠI TRƯ hành vi nào?",o:["Ứng dụng khoa học, công nghệ và chuyển đổi số trong thực thi nhiệm vụ","Sử dụng tài sản công của Nhà nước và tài sản của Nhân dân trái pháp luật","Lợi dụng, lạm dụng nhiệm vụ, quyền hạn, sử dụng thông tin liên quan đến công vụ để trục lợi","Tham ô, tham nhũng, tiêu cực, lãng phí, trục lợi, nhũng nhiễu"],c:0},{id:"vb08-80",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 1 Điều 14 Luật Cán bộ, công chức số 60/2025/QH15.",gt:"Hành vi đăng tải, phát tán, phát ngôn thông tin sai lệch làm ảnh hưởng đến hình ảnh, uy tín của đất nước, địa phương, cơ quan, đơn vị nơi công tác là một trong những việc cần bộ, công chức không được làm.",mn:"Phát tán thông tin sai lệch ảnh hưởng uy tín = việc không được làm.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, hành vi 'đăng tải, phát tán, phát ngôn thông tin sai lệch làm ảnh hưởng đến hình ảnh, uy tín của đất nước, địa phương, cơ quan, tổ chức, đơn vị nơi công tác' được xác định là gì?",o:["Hành vi thuộc phạm vi điều chỉnh của pháp luật về báo chí, không liên quan đến công vụ","Quyền tự do ngôn luận của cán bộ, công chức","Hành vi chỉ bị xử lý khi gây hậu quả nghiêm trọng","Một trong những việc cán bộ, công chức không được làm"],c:3},{id:"vb08-81",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điểm b khoản 1 Điều 13 Luật Cán bộ, công chức số 80/2025/0QH 15.",gt:"Khi nhận xét, đánh giá đồng nghiệp, cán bộ, công chức phải công bằng, vô tư, khách quan; đồng thời lắng nghe ý kiến của đồng nghiệp.",mn:"Đánh giá đồng nghiệp: công bằng — vô tư — khách quan.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, trong văn hóa giao tiếp ở công sở, khi nhận xét, đánh giá đồng nghiệp, cán bộ, công chức phải bảo đảm yêu cầu [.......].",o:["công bằng, vô tư, khách quan","tháng thần, nghiêm khác, đúng nguyên tắc","thận trọng, kín đạo, tế nhị","linh hoạt, mềm dẻo, phù hợp"],c:0},{id:"vb08-82",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:'Điều 12 và Điều 14 Luật Cán bộ, công chức số 60/2025/QH15. Luôi CBCC 2025 "nÉng 30',gt:"Đạo đức công vụ đặt ra các chuẩn mực tích cực phải thực hiện (cần, kiệm, liêm, chính, chí công vô tư, yêu nước, gương mẫu...); những việc không được làm xác định các hành vi bị cấm (tham nhũng, trục lợi, gây phiền hà, phân biệt đối xử...). Hai nội dung bổ sung cho nhau để xây dựng nên công vụ liêm chính, đều có tính bắt buộc và áp dụng cho mọi cán bộ, công chức.",mn:"Đạo đức = điều PHẢI làm; Việc không được làm = điều CẨM; cả hai bổ sung nhau.",t:"m",q:"Phân tích mối liên hệ giữa đạo đức công vụ và những việc không được làm, theo Luật Cán bộ, công chức số 80/2025/QH15, nhận định nào sau đây là DÙNG nhất?",o:["Đạo đức công vụ chi mang tính khuyến khích, không bắt buộc, còn những việc không được làm mới bắt buộc","Đạo đức công vụ và những việc không được làm là hai nội dung trùng lặp hoàn toàn","Đạo đức công vụ đặt ra các chuẩn mực tích cực mà cán bộ, công chức phải thực hiện (cần, kiệm, liêm, chính, chí công vô tư...), còn những việc không được làm xác định các hành vi bị cấm (tham nhũng, trục lợi, gây phiền hà...); hai nội dung này bổ sung cho nhau nhằm xây dựng nền công vụ liêm chính","Những việc không được làm chỉ áp dụng cho cán bộ, công chức lãnh đạo, quản lý"],c:2},{id:"vb08-83",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 4 Điều 14 Luật Cán bộ, công chức số 60/2025/QH15.",gt:"Hành vi lợi dụng, lạm dụng nhiệm vụ, quyền hạn, sử dụng thông tin liên quan đến công vụ để trục lợi là một trong những việc cán bộ, công chức không được làm.",mn:"Lợi dụng quyền hạn, thông tin công vụ để trục lợi = việc không được làm.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, hành vi 'lợi dụng, lạm dụng nhiệm vụ, quyền hạn, sử dụng thông tin liên quan đến công vụ để trục lợi' được xác định là gì?",o:["Hành vi được phép nếu không gây thiệt hại","Một trong những việc cán bộ, công chức không được làm","Quyền của cán bộ, công chức trong sử dụng thông tin công vụ","Hành vi chỉ bị xử lý kỷ luật khi lặp lại nhiều lần"],c:1},{id:"vb08-84",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 2 Điều 13 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Văn hóa giao tiếp với Nhân dân gồm: đeo huy hiệu, phù hiệu, cấp hiệu hoặc thẻ công chức; tác phong lịch sự; tôn trọng, lắng nghe, gần gũi Nhân dân; nghiêm túc, khiêm tốn; ngôn ngữ chuẩn mực, rõ ràng, mạch lạc. Phương án B là giao tiếp ở công sở; G là đạo đức; D là nghĩa vụ với Đảng, Nhà nước.",mn:"Với Nhân dân: đeo phù hiệu/thẻ - lịch sự — gần gũi, lắng nghe - ngôn ngữ chuẩn mực.",t:"m",q:"Theo Luật Cán bộ, công chức số 90/2025/QH15, các yêu cầu nào sau đây cùng thuộc văn hóa giao tiếp với Nhân dân của cán bộ, công chức?",o:["Tuyệt đối trung thành với Đảng và Nhà nước, bảo vệ danh dự Tổ quốc","Lắng nghe ý kiến của đồng nghiệp; công bằng, vô tư, khách quan khi đánh giá đồng nghiệp","Có đạo đức trong sáng, thực hiện cần, kiệm, liêm, chính, chí công vô tư","Đeo huy hiệu, phù hiệu, cấp hiệu hoặc thẻ công chức; có tác phong lịch sự; tôn trọng, lắng nghe và gần gũi với Nhân dân; nghiêm túc, khiêm tốn; ngôn ngữ chuẩn mực, rõ ràng, mạch lạc"],c:3},{id:"vb08-85",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 1 Điều 14 Luật Còn bộ, công chức số 80/2025/QH15.",gt:"Hành vi né tránh, đùn đẩy nhiệm vụ và gây bè phái, mất đoàn kết thuộc những việc cán bộ, công chức không được làm.",mn:"Né tránh, đùn đẩy + gây bè phái, mất đoàn kết = việc không được làm.",t:"m",q:"Một tình huống: Trong cơ quan, ông N là công chức thường xuyên né tránh, đùn đẩy nhiệm vụ khó cho đồng nghiệp và lôi kéo một số người tạo thành nhóm gây mất đoàn kết nội bộ. Theo Luật Cán bộ, công chức số 80/2025/QH15, hành vi của ồng Ñ thuộc nhóm nào?",o:["Vi phạm văn hóa giao tiếp ở công sở nhưng không bị cấm",'Những việc cán bộ, công chức không được làm (né tránh, đùn đẩy nhiệm vụ; gây bè phái, mất đoàn kết) Luôi CBCC 2025 "nÉng 31',"Hành vi bình thường trong quan hệ công tác","Chỉ vi phạm nếu gây hậu quả nghiêm trọng"],c:1},{id:"vb08-86",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Các khoản 2, 3, 5 Điều 14 Luật Cán bộ, công chức số 60/2025/Q1115.",gt:"Cả ba đều thuộc những việc không được làm: tham ô, tham nhũng, tiêu cực, lãng phí; sử dụng tài sản công, tài sản của Nhân dân trái pháp luật: phân biệt đối xử dân tộc, giới tính, tôn giáo... trong thi hành công vụ.",mn:"Cấm: tham nhũng - dụng tài sản công trái phép - phân biệt đối xử.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, các nội dung sau có cùng thuộc những việc cán bộ, công chức không được làm hay không: (i) tham ô, tham nhũng, tiêu cực, lãng phí; (ii) sử dụng tài sản công và tài sản của Nhân dân trái pháp luật; (iii) phân biệt đối xử dân tộc, giới tính, tôn giáo trong thi hành công vụ?",o:["Chỉ nội dung (i) đúng","Chỉ nội dung (i) và (ii) đúng","Cả ba nội dung đều thuộc những việc không được làm","Không nội dung nào thuộc những việc không được làm"],c:2},{id:"vb08-87",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 2 Điều 12 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Cán bộ, công chức phải có bản lĩnh, tinh thần đổi mới, sáng tạo, hội nhập quốc tế; đoàn kết, kỷ luật, kỷ cương trong công vụ; gương mẫu, không ngừng tu dưỡng, học tập suốt đời.",mn:"Trong công vụ: đoàn kết - kỷ luật - kỷ cương: học tập suốt đời.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, cán bộ, công chức phải << ] trong công vụ; gương mẫu, không ngừng tu dưỡng, học tập suốt đời.",o:["đoàn kết, kỷ luật, kỷ cương","dân chủ, công khai, minh bạch","trung thực, tháng thần, cầu thì","chủ động, sáng tạo, linh hoạt"],c:0},{id:"vb08-88",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 1 Điều 14 Luật Cán bộ, công chức số 80/2025/QH15. Lưới t BCtC 2095 gi 32",gt:"Tự ý nghỉ việc, bỏ việc; tham gia đình công là những việc cán bộ, công chức không được làm - khác với người lao động thông thường theo pháp luật về lao động.",mn:"CBCC: cấm tự ý bỏ việc và tham gia đình công.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, hành vi 'tự ý nghỉ việc, bỏ việc; tham gia đình công' được xác định như thế nào đối với cán bộ, công chức?",o:["Là quyền của cán bộ, công chức theo pháp luật về lao động","Là những việc cán bộ, công chức không được làm","Được phép nếu có lý do chính đáng và báo trước","Chỉ bị cấm đối với cán bộ, công chức lãnh đạo, quản lý"],c:1},{id:"vb08-89",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điều 13 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Với Nhân dân, cán bộ, công chức phải tôn trọng, lắng nghe, gần gũi; nghiêm túc, khiêm tốn; ngôn ngữ chuẩn mực, rõ ràng, mạch lạc và nghiêm cấm hách dịch, cửa quyền. Vì vậy 'sử dụng ngôn ngữ mệnh lệnh, áp đặt là sai. A,B, C đều đúng.",mn:"Không được dụng ngôn ngữ mệnh lệnh, áp đặt với dân.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, nhận định nào sau đây về văn hóa giao tiếp của cán bộ, công chức là KHÔNG đúng?",o:["Được quyền sử dụng ngôn ngữ mệnh lệnh, áp đặt đối với người dân để bảo đảm hiệu quả công việc","Với Nhân dân phải tôn trọng, lắng nghe, gần gũi, ngôn ngữ chuẩn mực","Khi thi hành công vụ phải đeo huy hiệu, phù hiệu, cấp hiệu hoặc thẻ công chức","Ở công sở phải có thái độ lịch sự, tôn trọng đồng nghiệp"],c:0},{id:"vb08-90",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",gt:"Quy định áp dụng cả sau khi thôi việc, nghỉ hưu nhằm phòng ngừa việc lợi dụng quan hệ, thông tin, ảnh hưởng có được trong thời gian công tác để trục lợi sau khi rời công vụ, bảo đảm liêm chính và phòng, chống tham nhũng. Quy định chỉ giới hạn ở các lĩnh vực, việc cụ thể theo luật, không cấm mọi hoạt động.",mn:"Ràng bước sau nghỉ hưu: chống lợi dụng quan hệ, thông tin cứ để trục lợi.",t:"m",q:"Theo Luật Cán bộ, công chức số 90/2025/QH15, việc quy định 'những việc không được làm' áp dụng cả sau khi thôi việc, nghỉ hưu có ý nghĩa chủ yếu nào sau đây?",o:["Ngăn cản người đã thôi việc tham gia các hoạt động xã hội","Hạn chế quyền tự do kinh doanh của người đã nghỉ hưu trong mọi lĩnh vực","Buộc người đã nghỉ hưu tiếp tục thực hiện nghĩa vụ công vụ","Phòng ngừa việc lợi dụng quan hệ, thông tin, ảnh hưởng có được trong thời gian công tác để trục lợi sau khi rời công vụ, bảo đảm liêm chính và phòng, chống tham nhũng"],c:3},{id:"vb08-91",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"(ác điều 12, 13, 14 Luật ( an bộ, công chức số 80/20)25/QH15.",gt:"Chuẩn mực gồm: đạo đức trong sáng, cần, kiệm, liêm, chính, chí công vô tư; văn hóa giao tiếp lịch sự, tôn trọng đồng nghiệp và Nhân dân; không thực hiện những việc bị cấm (tham nhũng, trục lợi, gây phiền hà, phân biệt đối xử...), trong đó một số việc còn ràng buộc cả sau khi thôi việc, nghỉ hưu.",mn:"Bộ ba: đạo đức (cần, kiệm, liêm, chính)! văn hóa giao tiếp! những việc không được làm. Luôi CBCC 2025 Mi 34 CHƯƠNG IV - CÔNG CHỨC (Mục 1: Tuyển dụng công chức)",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, phương án nào sau đây phản ánh ĐÚNG và ĐẦY ĐỦ nhất các chuẩn mực về đạo đức, văn hóa giao tiếp và kỷ luật công vụ của cán bộ, công chức?",o:["Được tự do ứng xử theo cách riêng miễn là không vi phạm pháp luật hình sự","Chỉ cần hoàn thành nhiệm vụ chuyên môn, không cần chuẩn mực về đạo đức và giao tiếp","Có đạo đức trong sáng, cần, kiệm, liêm, chính, chí công vô tư; văn hóa giao tiếp lịch sự, tôn trọng đồng nghiệp và Nhân dân; không thực hiện những việc bị cấm như tham nhũng, trục lợi, gây phiền hà, phân biệt đối xử, kể cả sau khi thôi việc, nghỉ hưu đối với một số việc theo quy định Lưới t BCtC 2095 gi 33","Chuẩn mực đạo đức và giao tiếp chỉ áp dụng đối với công chức tiếp xúc trực tiếp với người dân"],c:2},{id:"vb08-92",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điều 18 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Bốn nguyên tắc tuyển dụng công chức: công khai, minh bạch, khách quan, đúng pháp luật; cạnh tranh, bình đẳng: đáp ứng ngay yêu cầu của vị trí việc làm cần tuyển; tu tiền người có tài năng, người có công với nước, người dân tộc thiểu số. Điểm mới đáng chú ý: 'đáp ứng ngay yêu cầu của vị trí việc làm'.",mn:"Tuyển dụng: công khai, minh bạch - cạnh tranh, bình đẳng - đáp ứng NGAY vị trí việc làm — ưu tiên người tài, có công, dân tộc thiểu số.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, các nguyên tắc tuyển dụng công chức bao gồm những nội dung nào sau đây?",o:["Bảo đảm sự lãnh đạo của Đảng; kết hợp tiêu chuẩn chức danh với chỉ tiêu biên chế; thực hiện bình đẳng giới","Bảo đảm công khai, minh bạch, khách quan và đúng pháp luật; bảo đảm cạnh tranh, bình đẳng; người được tuyển dụng phải đáp ứng ngay yêu cầu của vị trí việc làm cần tuyển; ưu tiên tuyển dụng người có tài năng, người có công với nước, người dân tộc thiểu số","Tuân thủ Hiến pháp và pháp luật; công khai, minh bạch; bảo đảm thứ bậc hành chính","Bảo đảm công khai; ưu tiên người có thẩm niền công tác; tuyển dụng theo nhu cầu của cơ quan"],c:1},{id:"vb08-93",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 3 Điều 18 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Người được tuyển dụng phải đáp ứng ngay yêu cầu của vị trí việc làm cần tuyển - thể hiện rõ định hướng tuyển dụng theo vị trí việc làm, gắn với năng lực thực tế.",mn:"Người trúng tuyển phải đáp ứng ngay yêu cầu vị trí việc làm.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, một trong những nguyên tắc tuyển dụng công chức là người được tuyển dụng phải [........].",o:["có thời gian tập sự theo quy định","có bằng cấp cao hơn yêu cầu của vị trí việc làm","đáp ứng ngay yêu cầu của vị trí việc làm cần tuyển","cam kết công tác lâu dài tại cơ quan tuyển dụng"],c:2},{id:"vb08-94",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 4 Điều 18 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Tuyển dụng công chức ưu tiên người có tài năng, người có công với nước, người dân tộc thiểu số.",mn:"Ưu tiên tuyển dụng: người tài năng — có công - dân tộc thiểu số.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, đối tượng nào sau đây được ưu tiên trong tuyển dụng công chức?",o:["Người cư trú tại địa phương nơi có vị trí việc làm cần tuyển","Người có thâm niên công tác trong khu vực nhà nước","Người có bằng cấp chuyên môn cao nhất trong số dự tuyển","Người có tài năng, người có công với nước, người dân tộc thiểu số"],c:3},{id:"vb08-95",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điểm a khoản 1 Điều 19 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Điều kiện về quốc tịch: có 01 quốc tịch là quốc tịch Việt Nam theo quy định của Luật Quốc tịch. Đây là điểm cần lưu ý: chỉ một quốc tịch Việt Nam.",mn:"Dự tuyển: chỉ có 01 quốc tịch Việt Nam.",t:"m",q:"Theo Iuật Cán bộ, công chức số 80/2025/QH15, về quốc tịch, điều kiện đăng ký dự tuyển công chức được quy định như thế nào?",o:["Có 01 quốc tịch là quốc tịch Việt Nam theo quy định của Luật Quốc tịch","Có quốc tịch Việt Nam, không hạn chế việc có thêm quốc tịch nước ngoài","Có quốc tịch Việt Nam hoặc quốc tịch nước ngoài nếu cư trú tại Việt Nam","Là công dân Việt Nam, không phân biệt số lượng quốc tịch"],c:0},{id:"vb08-96",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điểm c khoản 1 Điều 19 Luật Cán bộ, công chức số 80/2025/QH16.",gt:"Người đăng ký dự tuyển công chức phải đủ 18 tuổi trở lên.",mn:"Tuổi dự tuyển: đủ 18 tuổi trở lên.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, về độ tuổi, người đăng ký dự tuyển công chức phải [......... l.",o:["đủ 18 tuổi trở lên","đủ 21 tuổi trở lên","từ đủ 18 tuổi đến 35 tuổi","đủ 20 tuổi trở lên"],c:0},{id:"vb08-97",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 1 Điều J9 Luật Cán bộ, công chức số 60/2025/0Q0H15.",gt:"Điều kiện dự tuyển gồm: 01 quốc tịch Việt Nam; cư trú tại Việt Nam; đủ 18 tuổi; phẩm chất chính trị, đạo đức tốt, lý lịch rõ ràng; đủ sức khỏe; đáp ứng yêu cầu của vị trí việc làm dự tuyển.",mn:'Điều kiện: 1 quốc tịch VN - cư trú VN — đủ 18 tuổi — phẩm chất, lý lịch rÕ - sức khỏe - đáp ứng vị trí việc làm. Luôi CBCC 2025 "rang 36',t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, các điều kiện nào sau đây cùng thuộc điều kiện đăng ký dự tuyển công chức?",o:["Là đảng viên; có thâm niên công tác; có chứng chỉ ngoại ngữ, tin học","Có quốc tịch Việt Nam; có hộ khẩu thường trú tại nơi tuyển dụng: đủ 21 tuổi; có bằng đại học trở lên","Có 01 quốc tịch là quốc tịch Việt Nam; đang cư trú tại Việt Nam; đủ 18 tuổi trở lên; có phẩm chất chính trị, đạo đức tốt, lý lịch rõ ràng; đủ sức khỏe; đáp ứng các điều kiện theo yêu cầu của vị trí việc làm dự tuyển","Có quốc tịch Việt Nam; cư trú tại Việt Nam; đủ 18 tuổi; cam kết phục vụ lâu dài"],c:2},{id:"vb08-98",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 2 Điều 19 Luật Còn bộ, công chức số 80/2025/QH15.",gt:"Người dự tuyển vào vị trí việc làm lãnh đạo, quản lý còn phải đáp ứng tiêu chuẩn, điều kiện bổ nhiệm theo quy định, trừ trường hợp thực hiện theo quyết định của cấp có thẩm quyền.",mn:"Dự tuyển vị trí lãnh đạo, quản lý: thêm tiêu chuẩn, điều kiện bũ nhiệm.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, người đăng ký dự tuyển vào vị trí việc làm lãnh đạo, quản lý, ngoài các điều kiện chung, còn phải đáp ứng yêu cầu nào?",o:["Phải có bằng thạc sĩ trở lên","Phái có thời gian công tác tối thiểu 05 năm trong khu vực nhà nước","Phải là đảng viên Đảng Cộng sản Việt Nam","Phải đáp ứng tiêu chuẩn, điều kiện bổ nhiệm theo quy định, trừ trường hợp thực hiện theo quyết định của cấp có thẩm quyền"],c:3},{id:"vb08-99",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 3 Điều 19 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Không được đăng ký dự tuyển: người mất hoặc bị hạn chế năng lực hành vi dân sự, người có khó khăn trong nhận thức, làm chủ hành vi; người đang bị truy cứu trách nhiệm hình sự: đang chấp hành hoặc đã chấp hành xong bản án mà chưa được xóa án tích; đang chấp hành biện pháp xử lý hành chính tại cơ sở cai nghiện bắt buộc, cơ sở giáo dục bắt buộc.",mn:"Không được dự tuyển: mất/hạn chế NLHVDS - đang bị truy cứu TNHS;chưa xóa án tích — đang ở cơ sở cai nghiện, giáo dục bắt buộc.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, trường hợp nào sau đây KHÔNG được đăng ký dự tuyển công chức?",o:["Người đủ 18 tuổi, có phẩm chất chính trị, đạo đức tốt","Người mất hoặc bị hạn chế năng lực hành vi dân sự; người có khó khăn trong nhận thức, làm chủ hành vi; người đang bị truy cứu trách nhiệm hình sự hoặc chưa được xóa án tích","Người có 01 quốc tịch Việt Nam, đang cư trú tại Việt Nam","Người đáp ứng các điều kiện theo yêu cầu của vị trí việc làm dự tuyển"],c:1},{id:"vb08-100",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 1 Điều 20 Luật Còn bộ, công chức số 80/2025/QH15.",gt:"Tuyển dụng công chức vào vị trí việc làm thực hiện qua thi tuyển và xét tuyển đối với một số nhóm đối tượng theo quy định của Chính phủ.",mn:"Phương thức tuyển dụng: thi tuyển + xét tuyển (một số nhóm). Lưới t BCtC 2095 gi 37",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, việc tuyển dụng công chức vào vị trí việc làm được thực hiện thông qua các phương thức nào?",o:["Thi tuyển, xét tuyển và phỏng vấn trực tiếp đối với mới đối tượng","Chỉ thông qua thi tuyển","Chỉ thông qua xét tuyển","Thi tuyển; xét tuyển đối với một số nhóm đối tượng theo quy định của Chính phủ"],c:3},{id:"vb08-101",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 2 Điều 20 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Cơ quan quản lý công chức có thể tiếp nhận vào làm công chức (không qua thi tuyển, xét tuyển) đối với: chuyên gia, nhà khoa học, luật gia, luật sư giỏi, doanh nhân tiêu biểu, xuất sắc được thu hút; người có kinh nghiệm, đáp ứng ngay yêu cầu vị trí việc làm, đang là viên chức, người hưởng lương trong Quân đội, Công an, tổ chức cơ yếu mà không phải là cũng chức và một số trường hợp khác trung hệ thống chính trị.",mn:"Tiếp nhận (không thi): chuyên gia, nhà khoa học... + người có kinh nghiệm (viên chức, ()Ð, CÁ, cơ yếu).",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, ngoài thi tuyển hoặc xét tuyển, cơ quan quản lý công chức còn có thể quyết định tiếp nhận vào làm công chức đối với đối tượng nào sau đây?",o:["Chuyên gia, nhà khoa học, luật gia, luật sư giỏi, doanh nhân tiêu biểu, xuất sắc được thu hút; người có kinh nghiệm, đáp ứng ngay yêu cầu của vị trí việc làm, đảng là viên chức, người hưởng lương trong Quân đội nhân dân, Công an nhân dân, tổ chức cơ yếu mà không phải là công chức","Mọi sinh viên tốt nghiệp đại học loại giỏi","Người lao động đang làm việc tại các doanh nghiệp tư nhân","Người có nguyện vọng làm việc trong cơ quan nhà nước và đủ 18 tuổi"],c:0},{id:"vb08-102",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 4 Điều 20 Luật Cán bộ, công chức số 60/2025/QH15.",gt:"Người được tuyển dụng được bố trí vào vị trí việc làm và xếp ngạch công chức tương ứng - nhất quán với nguyên tắc quản lý theo vị trí việc làm.",mn:"Trúng tuyổn: bố trí vào vị trí việc làm + xếp ngạch tương ứng.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, sau khi được tuyển dụng, công chức được bố trí và xếp ngạch như thế nào?",o:["Được xếp vào ngạch thấp nhất rồi nâng dân theo thâm niên","Được bố trí vào ngạch chuyên viên và tập sự 12 tháng","Được bố trí vào vị trí việc làm và xếp ngạch công chức tương ứng","Được bố trí theo nguyện vọng cá nhân và xếp ngạch theo bảng cấp"],c:2},{id:"vb08-103",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 3 ‡iÖu 20 Luật C an bộ, công chức số 80/2025/00H15.",gt:"Cơ quan quản lý công chức thực hiện tuyển dụng hoặc phân cấp, ủy quyền thẩm quyền tuyển dụng cho cơ quan sử dụng công chức thực hiện.",mn:'Tuyển dụng: cơ quan quản lý làm hoặc phân cấp, ủy quyền cho cơ quan sử dụng. Luôi CBCC 2025 "nÉng 38',t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, thẩm quyền tuyển dụng công chức được quy định như thế nào?",o:["Chỉ Bộ Nội vụ có thẩm quyền tuyển dụng công chức trong cả nước","Cơ quan quản lý công chức thực hiện tuyển dụng hoặc phân cấp, ủy quyền thẩm quyền tuyển dụng cho cơ quan sử dụng công chức thực hiện","Cơ quan sử dụng công chức tự quyết định tuyển dụng mà không cần phân cấp","Chính phủ trực tiếp tổ chức tuyển dụng cho mọi cơ quan"],c:1},{id:"vb08-104",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"‡)iem q khoản 1 Điều 21 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Cơ quan quản lý công chức có thế ký hợp đồng với chuyên gia, nhà khoa học, luật gia, luật sư giỏi, doanh nhân tiêu biểu, xuất sắc để thực hiện một hoặc một số nhiệm vụ của vị trí việc làm công chức lãnh đạo, quản lý. Đẩy là cơ chế mới, linh hoạt để thu hút nhân tài.",mn:"Hợp đồng cho vị tí lãnh đạo, quản lý: chuyên gia, nhà khoa học, luật sư giỏi, doanh nhân tiêu biểu.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, cơ quan quản lý công chức có thế ký hợp đồng thực hiện nhiệm vụ với đối tượng nào để thực hiện một hoặc một số nhiệm vụ của vị trí việc làm công chức lãnh đạo, quản lý?",o:["Sinh viên mọi tốt nghiệp đại học","Mọi công chức đang công tác tại cơ quan","Chuyên gia, nhà khoa học, luật gia, luật sư giỏi, doanh nhân tiêu biểu, xuất sắc","Người lao động được tuyển dụng theo hợp đồng lao động thông thường"],c:2},{id:"vb08-105",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 2 Điều 21 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Ngân sách nhà nước bảo đảm cho việc ký kết hợp đồng thực hiện nhiệm vụ, ngoài quỹ lương và ngoài kinh phí khoán chi hành chính - tách bạch nguồn kinh phí này đề không ảnh hưởng quỹ lương thường xuyên.",mn:"Kinh phí hợp đồng: NSNN, ngoài quỹ lương và ngoài khoản chi hành chính.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, kinh phí để ký kết hợp đồng thực hiện nhiệm vụ của công chức được bảo đảm từ nguồn nào?",o:["Từ quỹ lương của cơ quan, tổ chức, đơn vị","Ngân sách nhà nước bảo đảm, ngoài quỹ lương và ngoài kinh phí khoán chi hành chính","Từ kinh phí khoán chi hành chính của cơ quan","Từ nguồn thu sự nghiệp của cơ quan, tổ chức, đơn vị"],c:1},{id:"vb08-106",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Øiều 22 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Việc tuyển chọn, bổ nhiệm Thẩm phán, Kiểm sát viên được thực hiện theo pháp luật về tổ chức Tòa án nhân dân và pháp luật về tổ chức Viện kiểm sát nhân dân - có tính đặc thù riêng so với tuyển dụng công chức thông thường.",mn:'Thẩm phán, Kiểm sát viên: theo luật tổ chức TAND và VKSND (đặc thù riêng). Luôi CBCC 2025 "nÉng 59',t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, việc tuyển chọn, bổ nhiệm Thẩm phán Tòa án nhân dân, Kiểm sát viên Viện kiểm sát nhân dân được thực hiện theo quy định của pháp luật nào?",o:["Theo quyết định của Chánh án Tòa án nhân dân tối cao và Viện trưởng Viện kiểm sát nhân dân tối cao","Theo quy định chung về tuyển dụng công chức của Luật này","Theo quy định của Chính phủ về tuyển dụng công chức","Theo quy định của pháp luật về tổ chức Tòa án nhân dân và pháp luật về tổ chức Viện kiểm sát nhân dân"],c:3},{id:"vb08-107",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điểm a khoản 1 Điều 19 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Điều kiện về quốc tịch yêu cầu có 01 quốc tịch là quốc tịch Việt Nam. Bà X có hại quốc tịch nên không đủ điều kiện về quốc tịch để dự tuyển công chức.",mn:"Hai quốc tịch ¬ không đủ điều kiện (phái chi 01 quốc tịch Việt Nam).",t:"m",q:"Một tình huống: Bà X có hại quốc tịch (Việt Nam và quốc tịch nước ngoài), đủ 25 tuổi, có phẩm chất chính trị, đạo đức tốt và muốn đăng ký dự tuyển công chức. Theo Luật Cán bộ, công chức số 80/2025/QH15, bà X có đủ điều kiện về quốc tịch để dự tuyển không?",o:["Không đủ điều kiện, vi điều kiện dự tuyển yêu cầu có 01 quốc tịch là quốc tịch Việt Nam","Đủ điều kiện, vì bà X có quốc tịch Việt Nam","Đủ điều kiện, vì pháp luật không hạn chế số lượng quốc tịch","Đủ điều kiện nếu bà X cư trú tại Việt Nam"],c:0},{id:"vb08-108",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điểm b khoản 3 Điều 19 Luật Cán bộ, công chức số 80/2025/QH15,",gt:"Người đã chấp hành xong bản án, quyết định về hình sự mà chưa được xóa án tích thuộc trường hợp không được đăng ký dự tuyển công chức. Ông Y chưa được xóa án tích nên không đủ điều kiện.",mn:"Chưa được xóa án tích — không được dự tuyển.",t:"m",q:"Một tình huống: Ông Y đã chấp hành xong bản án về một tội hình sự nhưng chưa được xóa án tích. Ông Ý muốn đăng ký dự tuyển công chức. Theo Luật Cán bộ, công chức số 80/2025/QH15, trường hợp của ông Y được xác định như thế nào?",o:["Được đăng ký dự tuyển bình thường, vì đã chấp hành xong bản án","Không được đăng ký dự tuyển công chức, vị thuộc trường hợp đã chấp hành xong bản án mà chưa được xóa án tích","Được đăng ký dự tuyển nếu có xác nhận cải tạo tốt","Được đăng ký dự tuyển nếu tối đa phạm là tội ít nghiêm trọng"],c:1},{id:"vb08-109",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điểm b khoản 1 Điều 20 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Xét tuyển được áp dụng đối với một số nhóm đối tượng theo quy định của Chính phủ, bền cạnh hình thức thi tuyển áp dụng chung.",mn:"Xét tuyển: chỉ với một số nhóm đối tượng do Chính phủ quy định.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, hình thức 'xét tuyển' trong tuyển dụng công chức được áp dụng đối với đối tượng nào?",o:["Đối với một số nhóm đối tượng theo quy định của Chính phủ","Đối với mới đối tượng đăng ký dự tuyển","Đối với người có bằng cấp cao nhất","Đối với người dự tuyển vào vị trí lãnh đạo, quản lý"],c:0},{id:"vb08-110",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"J)iểm c khoản 1 Điều 21 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Cơ quan quản lý công chức có thể ký hợp đồng dịch vụ để thực hiện công việc của cơ quan, tổ chức, đơn vị do chưa đáp ứng đủ nguồn nhân lực.",mn:"Hợp đồng dịch vụ: khi chưa đủ nguồn nhân lực thực hiện công việc.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, cơ quan quản lý công chức có thế ký hợp đồng dịch vụ trong trường hợp nào?",o:["Để thực hiện các nhiệm vụ của vị trí việc làm lãnh đạo, quản lý","Để thay thế hoàn toàn việc tuyển dụng công chức Lưới t BCtC 2095 gi 40","Để thực hiện công việc của cơ quan, tổ chức, đơn vị do chưa đáp ứng đủ nguồn nhân lực","Để giảm biên chế công chức trong cơ quan"],c:2},{id:"vb08-111",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điều 20 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Cả ba đều là phương thức/hình thức để trở thành công chức: thi tuyển, xét tuyển (imột số nhóm) và tiếp nhận đối với chuyên gia, nhà khoa học được thu hút và một số trường hợp khác.",mn:"Trở thành công chức: thi tuyển — xét tuyển ~ tiếp nhận.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, các nội dung sau có cùng thuộc các phương thức/hình thức để một người trở thành công chức hay không: (i) thi tuyển; (ii) xét tuyển; (iii) tiếp nhận đối với chuyên gia, nhà khoa học được thu hút?",o:["Chỉ nội dung (i) đúng","Chỉ nội dung (1) và (ii) đúng","Không nội dung nào đúng","Cả ba nội dung đều là phương thức/hình thức để trở thành công chức"],c:3},{id:"vb08-112",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 1 Điều 19 Luật Cán bộ, công chức số 60/2025/QH15.",gt:"Điều kiện dự tuyển không yêu cầu phải là đảng viên hay nhất thiết có báng đại học (bằng cấp tùy theo yêu cầu của vị trí việc làm). Các điều kiện A, B, C đều đúng.",mn:"Không bắt buộc là đảng viên hay có bằng đại học để dự tuyển (tùy vị trí việc làm).",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, nhận định nào sau đây về điều kiện dự tuyển công chức là KHÔNG đúng?",o:["Phải có 01 quốc tịch là quốc tịch Việt Nam","Phải đủ 18 tuổi trở lên","Phải đăng cư trú tại Việt Nam và có phẩm chất chính trị, đạo đức tốt, lý lịch rõ ràng","Phải là đảng viên Đảng Cộng sản Việt Nam và có bằng đại học trở lên"],c:3},{id:"vb08-113",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điều 18, Điều 19, Điều 20 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Tuyển dụng gắn với vị trí việc làm: người dự tuyển phải đáp ứng yêu cầu của vị trí việc làm dự tuyển và đáp ứng ngay yêu cầu của vị trí việc làm cần tuyển: sau khi trúng tuyển được bố trí vào vị trí việc làm và xếp ngạch tương ứng.",mn:"Tuyển theo vị trí việc làm: đáp ứng yêu cầu vị trí ¬ bố trí đúng vị trí + xếp ngạch tương ứng.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, việc tuyển dụng công chức gắn với 'vị trí việc làm' thể hiện ở điểm nào sau đây?",o:["Việc tuyển dụng không cần xác định trước vị trí việc làm","Người dự tuyển chỉ cần đáp ứng tiêu chuẩn về bằng cấp và thâm niên","Người dự tuyển phải đáp ứng các điều kiện theo yêu cầu của vị trí việc làm dự tuyển và phải đáp ứng ngay yêu cầu của vị trí việc làm cần tuyển; sau khi trúng tuyển được bố trí vào vị trí việc làm và xếp ngạch tương ứng","Sau khi trúng tuyển, công chức được tự chọn vị trí việc làm phù hợp Luật CBCC 2025 'rurg 41"],c:2},{id:"vb08-114",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điểm b khoản 2 Điều 20 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Người có kinh nghiệm, đáp ứng ngay yêu cầu của vị trí việc làm, đang là viên chức (hoặc người hưởng lương trong Quân đội, Công an, cơ yếu mà không phải là công chức) có thể được cơ quan quản lý công chức quyết định tiếp nhận vào làm công chức - không nhất thiết qua thi tuyển.",mn:"Viên chức có kinh nghiệm: được tiếp nhận thành công chức (không bắt buộc thi).",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, người có kinh nghiệm, đáp ứng ngay yêu cầu của vị trí việc làm, đang là viên chức có thể trở thành công chức thông qua hình thức nào?",o:["Được cơ quan quản lý công chức quyết định tiếp nhận vào làm công chức","Bắt buộc phải thi tuyển như người dự tuyển thông thường","Phải qua thời gian tập sự rồi mới được bổ nhiệm","Không thể trở thành công chức nếu đang là viên chức"],c:0},{id:"vb08-115",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Các điều từ 18 đến 21 Luật Còn bộ, công chức số 60/2025/QH15.",gt:"Định hướng mới về tuyển dụng: công khai, minh bạch, cạnh tranh, bình đẳng: đáp ứng ngay yêu cầu vị trí việc làm; qua thi tuyển, xét tuyển và tiếp nhận; ưu tiên người tài, người có công, người dân tộc thiểu số: có cơ chế hợp đồng thực hiện nhiệm vụ để thu hút nhân lực chất lượng cao.",mn:"Tuyển dụng mới: cạnh tranh - đáp ứng ngay vị trí việc làm - thi/xét/tiếp nhận - ưu tiên người tài - hợp đồng nhân tài. Lưới t BCtC 2095 gi 42 CHƯƠNG IV - CÔNG CHỨC (Mục 2: Vị trí việc làm và ngạch công chức) Phạm vi: Điều 23 đến Điều 24 — căn cứ xác định, nội dung và phân loại vị trí việc làm công chức; hệ thống ngạch công chức và việc xếp ngạch.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, phương án nào sau đây phản ánh ĐÚNG và ĐẦY ĐỦ nhất về tuyển dụng công chức theo định hướng mới?",o:["Tuyển dụng chủ yếu theo bảng cấp và thâm niên, không cạnh tranh","Tuyển dụng bảo đảm công khai, minh bạch, cạnh tranh, bình đẳng; người trúng tuyển phải đáp ứng ngay yêu cầu vị trí việc làm; thực hiện qua thi tuyển, xét tuyển và tiếp nhận; ưu tiên người tài, người có công, người dân tộc thiểu số; có cơ chế hợp đồng thực hiện nhiệm vụ để thu hút nhân lực chất lượng cao","Tuyển dụng chỉ qua thi tuyển, không có hình thức nào khác","Tuyển dụng do cơ quan sử dụng công chức tự quyết định không theo nguyên tắc chung"],c:1},{id:"vb08-116",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 1 Điều 23 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Căn cứ xác định vị trí việc làm gồm: chức năng, nhiệm vụ, cơ cấu tổ chức của cơ quan; mức độ phức tạp, tính chất, đặc điểm của ngành, lĩnh vực, phạm vi, đối tượng phục vụ, quy trình quản lý chuyên môn, nghiệp vụ; mức độ hiện đại hóa công sở, ứng dụng khoa học, công nghệ, chuyển đổi số.",mn:"Căn cứ VTVL: chức năng, nhiệm vụ, cơ cấu - tính chất ngành, lĩnh vực — mức độ hiện đại hóa, chuyển đổi số.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, vị trí việc làm của công chức được xác định dựa trên những căn cứ nào sau đây?",o:["Nguyện vọng của công chức và đề xuất của người đứng đầu cơ quan","Số lượng biên chế được giao và quy tiền lương của cơ quan, tổ chức, đơn vị","Thâm niên công tác và bằng cấp chuyên môn của công chức hiện có","Chức năng, nhiệm vụ và cơ cấu tổ chức của cơ quan; mức độ phức tạp, tính chất, đặc điểm của từng ngành, lĩnh vực, phạm vi, đối tượng phục vụ, quy trình quản lý chuyên môn, nghiệp vụ; mức độ hiện đại hóa công sở, ứng dụng khoa học, công nghệ, chuyển đổi số"],c:3},{id:"vb08-117",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 2 Điều 23 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Nội dung chính của vị trí việc làm: tên gọi vị trí việc làm; chức vụ, chức danh hoặc ngạch công chức tương ứng; bản mô tả công việc và khung năng lực của vị trí việc làm.",mn:"VTVL gồm: tên gọi - chức vụ/chức danh;ngạch - bản mô tả công việc + khung năng lực.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, vị trí việc làm của công chức bao gồm các nội dung chính nào sau đây?",o:["Tên gọi vị trí việc làm; hệ số lương: phụ cấp chức vụ","Tên gọi vị trí việc làm; chức vụ, chức danh hoặc ngạch công chức tương ứng; bản mô tả công việc và khung năng lực của vị trí việc làm","Tên cơ quan; số lượng biên chế; quỹ tiền lương","Chức danh nghề nghiệp; tiêu chuẩn đạo đức; thời gian công tác"],c:1},{id:"vb08-118",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 3 Điều 23 Luật Cán bộ, công chức số 60/2025/QH15. Luật CBCC 2025 'rig 43",gt:"Vị trí việc làm được phân thành ba nhóm: lãnh đạo, quản lý: chuyên môn, nghiệp vụ; hỗ trợ, phục vụ.",mn:"3 loại VTVL,: lãnh đạo, quản lý — chuyên môn, nghiệp vụ - hỗ trợ, phục vụ.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, vị trí việc làm của công chức được phân loại thành các nhóm nào?",o:["Vị trí việc làm lãnh đạo, quản lý; vị trí việc làm chuyên môn, nghiệp vụ; vị trí việc làm hỗ trợ, phục vụ","Vị trí việc làm thường xuyên và vị trí việc làm không thường xuyên","Vị trí việc làm cấp cao và vị trí việc làm cấp thấp","Vị trí việc làm trong biên chế và vị trí việc làm hợp đồng"],c:0},{id:"vb08-119",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điểm c khoản 2 Điều 23 Luật Cán bộ, công chức số 80/2025/Q1115.",gt:"Một nội dung chính của vị trí việc làm là bản mô tả công việc và khung năng lực của vị trí việc làm — cơ sở để tuyển dụng, sử dụng, đánh giá công chức.",mn:"VTVI, có bản mô tả công việc + khung năng lực.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, một nội dung chính của vị trí việc làm là [......... }, thể hiện rõ công việc phải làm và năng lực cần có để đảm nhiệm.",o:["hệ số lương và phụ cấp tương ứng","số lượng biên chế của vị trí việc làm","bản mô tả công việc và khung năng lực của vị trí việc làm","tiêu chuẩn về thâm niên và bằng cấp"],c:2},{id:"vb08-120",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 1 Điều 24 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Hệ thống ngạch công chức gồm sáu ngạch: chuyên gia cao cấp; chuyên viên cao cấp và tương đương; chuyên viên chính và tương đương: chuyên viên và tương đương; cán sự và tương đương; nhân viên.",mn:"6 ngạch: chuyên gia cao cấp - chuyên viên cao cấp - chuyên viên chính — chuyên viên -- cán sự - nhân viên.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, hệ thống ngạch công chức xếp theo thứ bậc về chuyên môn, nghiệp vụ gồm những ngạch nào?",o:["Chuyên gia cao cấp; chuyên viên cao cấp; chuyên viên chính; chuyên viên","Chuyên viên cao cấp; chuyên viên chính; chuyên viên; cán sự; nhân viên","Chuyên gia cao cấp; chuyên viên cao cấp và tương đương; chuyên viên chính và tương đương: chuyên viên và tương đương: cán sự và tương đương; nhân viên","Chuyên viên cao cấp; chuyên viên chính; chuyên viên; nhân viên; cộng tác viên"],c:2},{id:"vb08-121",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 1 Điều 24 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Ngạch cao nhất là chuyên gia cao cấp, tiếp đến là chuyên viên cao cấp, chuyên viên chính, chuyên viên, cán sự và thấp nhất là nhân viên.",mn:"Ngạch cao nhất: chuyên gia cao cấp; thấp nhất: nhân viên. Lưới t BCtC 2095 ni 1 744",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, ngạch cao nhất trong hệ thống ngạch công chức là ngạch nào?",o:["Chuyên gia cao cấp","Chuyên viên cao cấp","Chuyên viên chính","Chuyên viên"],c:0},{id:"vb08-122",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 2 Điều 24 Luật Cán bộ, công chức số 60/2025/QH15.",gt:"Việc xếp ngạch tương ứng với vị trí việc làm thực hiện khi: người được tuyển dụng vào vị trí việc làm; công chức được bố nhiệm chức vụ lãnh đạo, quản lý hoặc được bố trí vào vị trí việc làm mà vị trí đó được xếp ngạch tương ứng khác với ngạch đang giữ.",mn:"Xếp ngạch khi: được tuyển dụng vào VTVL hoặc được bố trí sang VTVL có ngạch khác.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, việc xếp ngạch công chức tương ứng với vị trí việc làm được thực hiện trong trường hợp nào sau đây?",o:["Chỉ khi công chức được cử đi đào tạo, bồi dưỡng","Chỉ khi công chức được nâng lương thường xuyên","Chỉ khi công chức có đủ thâm niên theo quy định","Người được tuyển dụng vào vị trí việc làm; công chức được bổ nhiệm chức vụ lãnh đạo, quản lý hoặc được bố trí vào vị trí việc làm mà vị trí đó được xếp ngạch tương ứng khác với ngạch đang giữ"],c:3},{id:"vb08-123",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 3 Điều 24 Luật Cán bộ, công chức số 60/2025/QH15.",gt:"Việc xếp ngạch công chức phải bảo đảm phù hợp với tỷ lệ công chức cần bố trí theo từng vị trí việc làm trong cơ quan sử dụng công chức theo quy định của Chính phủ.",mn:"Xếp ngạch phải phù hợp tỷ lệ công chức theo từng vị trí việc làm.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, việc xếp ngạch công chức phải bảo đảm yêu cầu nào sau đây?",o:["Phù hợp với nguyện vọng của công chức và đề xuất của người đứng đầu","Phù hợp với tỷ lệ công chức cần bố trí theo từng vị trí việc làm trong cơ quan sử dụng công chức theo quy định của Chính phủ","Phù hợp với thâm niên công tác của công chức","Phù hợp với số lượng biên chế được giao cho từng phòng, ban"],c:1},{id:"vb08-124",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 3 Điều 23 Luật Cán bộ, công chức số 80/2025/QHIS.",gt:"Cá ba nhóm lãnh đạo, quản lý; chuyên môn, nghiệp vụ; hỗ trợ, phục vụ đều thuộc phân loại vị trí việc làm công chức.",mn:"3 loại VTVL: lãnh đạo, quản lý - chuyên môn, nghiệp vụ - hỗ trợ, phục vụ.::_— Lm Luật CBCC 2025 trg 45",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, các nhóm vị trí việc làm sau có cùng thuộc phân loại vị trí việc làm công chức hay không: (i) lãnh đạo, quản lý; (ii) chuyên môn, nghiệp vụ; (ii) hỗ trợ, phục vụ?",o:["Chỉ nhóm (i) đúng","Chỉ nhóm (1) và (ii) đúng","Cá ba nhóm đều thuộc phân loại vị trí việc làm công chức","Không nhóm nào đúng"],c:2},{id:"vb08-125",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 4 liệu 23 Luật ( án bộ, công chức sơ 80)/20)25/(MH15.",gt:"Chính phủ quy định nguyên tắc, trình tự, thủ tục xây dựng, thẩm quyền phê duyệt vị trí việc làm phù hợp với phân cấp quản lý cán bộ, công chức và quy định chi tiết Điều này.",mn:"Nguyên tắc, thủ tục, thẩm quyền phê duyệt VTVL: do Chính phủ quy định.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, chủ thể nào quy định nguyên tắc, trình tự, thủ tục xây dựng, thẩm quyền phê duyệt vị trí việc làm?",o:["Hội đồng nhân dân cấp tỉnh","Bộ Nội vụ","Người đứng đầu cơ quan sử dụng công chức","Chính phủ"],c:3},{id:"vb08-126",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điểm b khoản 2 Điều 24 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Khi công chức được bố trí vào vị trí việc làm mà vị trí đó được xếp ngạch tương ứng khác với ngạch đang giữ thì thực hiện xếp ngạch tương ứng với vị trí việc làm mới. Việc này gắn với vị trí việc làm, không phù thuộc thuận vào thâm niên hay kỳ thị nâng ngạch.",mn:"Bố trí sang VTVL có ngạch khác ¬ thực hiện xếp ngạch tương ứng.",t:"m",q:"Một tình huống: Ông H đang giữ ngạch chuyên viên, được bố trí sang một vị trí việc làm mới mà vị trí đó được xếp ngạch chuyên viên chính. Theo Luật Cán bộ, công chức số 80/2025/QH15, trường hợp này có thực hiện xếp ngạch không?",o:["Không, vì việc xếp ngạch chỉ thực hiện khi tuyển dụng lần đầu","Có, vị công chức được bố trí vào vị trí việc làm mà vị trí đó được xếp ngạch tương ứng khác với ngạch đang giữ thì thực hiện xếp ngạch","Không, vì ông H phải đủ thâm niên mới được xếp ngạch mới","Có, nhưng phải cho kỳ thi nâng ngạch tiếp theo"],c:1},{id:"vb08-127",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Ø)iều 23 và Điều 24 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Việc xếp ngạch công chức gắn với vị trí việc làm (xếp ngạch tương ứng với vị trí việc làm), không phải 'chỉ căn cứ vào thâm niên công tác'. Các nhận định A, B, G đều đúng.",mn:"Xếp ngạch gắn với vị trí việc làm, không thuận theo thâm niên. Luật CHBHCC 2025 12g46",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, nhận định nào sau đây về vị trí việc làm và ngạch công chức là KHÔNG đúng?",o:["Việc xếp ngạch công chức chỉ căn cứ vào thâm niên công tác, không liên quan đến vị trí việc làm","Vị trí việc làm được phân thành ba loại: lãnh đạo, quản lý; chuyên môn, nghiệp vụ; hỗ trợ, phục vụ","Hệ thống ngạch công chức gồm sáu ngạch từ chuyên gia cao cấp đến nhân viên","Vị trí việc làm gồm tên gọi, chức vụ/chức danh/ngạch tương ứng, bản mô tả công việc và khung năng lực"],c:0},{id:"vb08-128",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điều 23 và Điều 24 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Vị trí việc làm gắn với chức vụ, chức danh, ngạch công chức tương ứng; người được tuyển dụng hoặc bố trí vào vị trí việc làm được xếp ngạch công chức tương ứng với vị trí đó. Đây là mối quan hệ then chốt trong quản lý công chức theo vị trí việc làm.",mn:"VTVL gắn với ngạch tương ứng ¬ bố trí vào VTVL thì xếp ngạch tương ứng.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, mối quan hệ giữa vị trí việc làm và ngạch công chức được thể hiện như thế nào?",o:["Ngạch công chức quyết định vị trí việc làm mà công chức được bố trí","Vị trí việc làm và ngạch công chức là hai nội dung hoàn toàn độc lập, không liên quan","Vị trí việc làm gắn với chức vụ, chức danh, ngạch công chức tương ứng; người được tuyển dụng hoặc bố trí vào vị trí việc làm được xếp ngạch công chức tương ứng với vị trí đó","Vị trí việc làm chỉ áp dụng cho công chức lãnh đạo, ngạch chỉ áp dụng cho công chức chuyên môn"],c:2},{id:"vb08-129",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điều 23 vò Điều 24 Luột Cán bộ, công chức số 80/2025/QH15.",gt:"Quản lý theo vị trí việc làm và ngạch: vị trí việc làm xác định trên cơ sở chức năng, nhiệm vụ, đặc điểm ngành, lĩnh vực, mức độ hiện đại hóa; gồm tên gọi, chức vụ/chức danh/ngạch, bản mô tả công việc, khung năng lực; phân thành ba loại; ngạch gồm sáu bậc và việc xếp ngạch gắn với vị trí việc làm.",mn:"VTVL (3 loại) + ngạch (6 bậc), xếp ngạch gắn với vị trí việc làm. Lưới t BCtC 2095 gi 47 CHƯƠNG IV - CÔNG CHỨC (Mục 3: Đánh giá công chức)",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, phương án nào sau đây phản ánh ĐÚNG và ĐẦY ĐỦ nhất về quản lý công chức theo vị trí việc làm và ngạch?",o:["Công chức được quản lý chủ yếu theo ngạch, bậc lương và thâm niên, không gắn với vị trí việc làm","Vị trí việc làm được xác định trên cơ sở chức năng, nhiệm vụ, đặc điểm ngành, lĩnh vực và mức độ hiện đại hóa; gồm tôn gọi, chức vụ/chức danh/ngạch tương ứng, bản mô tả công việc và khung năng lực; được phân thành ba loại; ngạch công chức gồm sáu bậc và việc xếp ngạch gắn với vị trí việc làm","Vị trí việc làm do công chức từ đăng ký và lựa chọn theo nguyện vọng","Ngạch công chức gồm bốn bậc và không liên quan đến vị trí việc làm"],c:1},{id:"vb08-130",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 1 Điều 25 Luật Cán bộ, công chức số 60/2025/QH15.",gt:"Nguyên tắc đánh giá: dân chủ, công khai, công bằng, minh bạch, khách quan, xuyên suốt, liên tục, đa chiều; định lượng tối đa về tiến độ, chất lượng, hiệu quả gắn với vị trí việc làm; ứng dụng khoa học, công nghệ, chuyển đổi số. Điểm mới nổi bật: đa chiều, định lượng và ứng dụng công nghệ.",mn:"Đánh giá: dân chủ, khách quan, đa chiều - định lượng gắn VTVL - ứng dụng công nghệ.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, việc đánh giá công chức phải bảo đảm các nguyên tắc nào sau đây?",o:["Công khai, minh bạch; ưu tiên người có thâm niên; đánh giá một chiều từ trên xuống","Bảo đảm sự lãnh đạo của Đảng; kết hợp tiêu chuẩn chức danh với chỉ tiêu biên chế","Tuân thủ Hiến pháp và pháp luật; bảo đảm thứ bậc hành chính","Dân chủ, công khai, công bằng, minh bạch, khách quan, xuyên suốt, liên tục, đa chiều; nội dung đánh giá được định lượng tối đa về tiến độ, chất lượng, hiệu quả gắn với vị trí việc làm; ứng dụng khoa học, công nghệ, chuyển đổi số trong theo dõi, đánh giá, xếp loại"],c:3},{id:"vb08-131",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điểm b khoản 1 Điều 25 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Nội dung đánh giá phải được định lượng tối đa về tiến độ, chất lượng, hiệu quả gắn với vị trí việc làm - chuyển từ đánh giá định tình sang định lượng theo kết quả, sản phẩm.",mn:"Đánh giá: định lượng tối đa (tiến độ, chất lượng, hiệu quả) theo vị uí việc làm.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, một nguyên tắc mới trong đánh giá công chức là nội dung đánh giá phải được |........] gắn với vị trí việc làm.",o:["định lượng tối đa về tiến độ, chất lượng, hiệu quả","nhận xét định tình","bình xét tập thể","tự đánh giá và kiểm điểm"],c:0},{id:"vb08-132",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 2 Điều 25 Luật C an bộ, công chức số 80/2025/(QH15.",gt:"Người đứng đầu cơ quan sử dụng công chức đánh giá công chức thuộc quyền; việc đánh giá người đứng đầu do người đứng đầu cơ quan, tổ chức cấp trên quản lý trực tiếp thực hiện.",mn:"Đánh giá: người đứng đầu đánh giá cấp dưới; đánh giá người đứng đầu do cấp trên trực tUIẾp.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, thẩm quyền đánh giá công chức được quy định như thế nào?",o:["Công chức từ đánh giá và báo cáo cấp trên xác nhận","Tập thể cơ quan bỏ phiếu đánh giá tất cả công chức kể cả người đứng đầu","Cơ quan quản lý công chức tục tiếp đánh giá toàn bộ công chức trong ngành","Người đứng đầu cơ quan, tổ chức, đơn vị sử dụng công chức đánh giá công chức thuộc quyền; việc đánh giá người đứng đầu do người đứng đầu cơ quan, tổ chức cấp trên quản lý trực tiếp thực hiện"],c:3},{id:"vb08-133",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 3 Điều 25 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Phương thức đánh giá gồm: theo dõi, đánh giá thường xuyên, liên tục, đa chiều, định lượng bằng tiêu chí cụ thể gắn với kết quả, sản phẩm theo vị trí việc làm; và đánh giá, xếp loại chất lượng hằng năm. Đây là điểm mới: kết hợp theo dõi thường xuyên với xếp loại hằng năm.",mn:"Phương thức: theo dõi thường xuyên, liên tục + xếp loại hàng năm.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, phương thức đánh giá công chức bao gồm những hình thức nào?",o:["Chí đánh giá, xếp loại một lần vào cuối năm","Theo dõi, đánh giá thường xuyên, liên tục, đa chiều, định lượng bằng các tiêu chí cụ thể gắn với tiến độ, chất lượng kết quả, sản phẩm theo từng vị trí việc làm; và đánh giá, xếp loại chất lượng hằng năm","Chí đánh giá khi công chức được đề bạt, bổ nhiệm","Đánh giá theo nhiệm kỳ 05 năm một lần"],c:1},{id:"vb08-134",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 4 Điều 25 Luật ( án bộ, công chức số 80/2025/QH15.",gt:"Nội dung đánh giá gồm: phẩm chất chính trị, đạo đức, văn hóa công vụ, ý thức kỷ luật; năng lực chuyên môn, nghiệp vụ, thái độ phục vụ người dân, doanh nghiệp, khả năng phối hợp; năng lực đối mới, sáng tạo, dám nghĩ, dám làm, dám chịu trách nhiệm; kết quả thực hiện nhiệm vụ quá số lượng, chất lượng, tiến độ sản phẩm theo vị trí việc làm; và nội dung khác theo yêu cầu vị trí việc làm.",mn:"Đánh giá: phẩm chất - năng lực, thái độ phục vụ - đổi mới, dám làm - kết quả quả sản phẩm.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, các nội dung nào sau đây thuộc nội dung đánh giá công chức?",o:["Số ngày làm việc trong năm và số giờ làm thêm","Thâm niên công tác, bằng cấp và chứng chỉ chuyên môn","Phẩm chất chính trị, đạo đức, văn hóa công vụ, ý thức kỷ luật; năng lực chuyên môn, nghiệp vụ, thái độ phục vụ người dân, doanh nghiệp; năng lực đối mới, sáng tạo, dám nghĩ, dám làm; kết quả thực hiện nhiệm vụ quá số lượng, chất lượng, tiến độ sản phẩm theo vị trí việc làm","Mức độ chấp hành quy chế chi tiêu nội bộ của cơ quan"],c:2},{id:"vb08-135",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 4 Điều 25 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Công chức lãnh đạo, quản lý còn được đánh giá theo kết quả hoạt động của cơ quan, đơn vị, lĩnh vực được giao phụ trách; khả năng tổ chức triển khai thực hiện nhiệm vụ; năng lực tập hợp, đoàn kết cán bộ, công chức, viên chức, người lao động thuộc quyền.",mn:"Lãnh đạo, quản lý: thêm kết quả của đơn vị + tổ chức triển khai + tập hợp, đoàn kết.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, ngoài các nội dung đánh giá chung, công chức lãnh đạo, quản lý còn được đánh giá thêm theo tiêu chí nào?",o:["Kết quả hoạt động của cơ quan, tổ chức, đơn vị hoặc lĩnh vực được giao lãnh đạo, quản lý, phụ trách; khả năng tổ chức triển khai thực hiện nhiệm vụ; năng lực tập hợp, đoàn kết","Số nắm giữ chức vụ lãnh đạo, quản lý","Số lượng cán bộ, công chức thuộc quyền quản lý","Mức độ hoàn thành chỉ tiêu thu, chỉ ngân sách của cơ quan"],c:0},{id:"vb08-136",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản † Điều 20 Luật Cán bộ, công chức số 60/2025/QH15.",gt:"Công chức được xếp loại chất lượng hằng năm theo bốn mức: hoàn thành xuất sắc nhiệm vụ; hoàn thành tốt nhiệm vụ; hoàn thành nhiệm vụ; không hoàn thành nhiệm vụ.",mn:"4 mức: hoàn thành xuất sắc - tốt - hoàn thành - không hoàn thành nhiệm vụ.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, công chức được xếp loại chất lượng hằng năm theo các mức nào?",o:["Xuất sắc; giới; khả; trung bình; yêu","Hoàn thành xuất sắc nhiệm vụ; hoàn thành tốt nhiệm vụ; hoàn thành nhiệm vụ; không hoàn thành nhiệm vụ","Hoàn thành xuất sắc nhiệm vụ; hoàn thành nhiệm vụ; không hoàn thành nhiệm vụ","Hoàn thành tốt nhiệm vụ; hoàn thành nhiệm vụ nhưng còn hạn chế; không hoàn thành nhiệm vụ"],c:1},{id:"vb08-137",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 2 Điều 26 Luật Cán bộ, công chức số 60/2025/QH15.",gt:"Kết quả xếp loại chất lượng phải được thông báo đến cá nhân công chức, công khai trong cơ quan, tổ chức, đơn vị và lưu vào hồ sơ công chức - bảo đảm dân chủ, công khai, minh bạch.",mn:"Kết quả xếp loại: thông báo cá nhân + công khai + lưu hồ sơ. Lướit BÓC 2025 xr ng 50",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, kết quả xếp loại chất lượng công chức được xử lý như thế nào?",o:["Được thông báo đến cá nhân công chức, công khai trong cơ quan, tổ chức, đơn vị và được lưu vào hồ sơ công chức","Chỉ được lưu vào hồ sơ công chức, không thông báo cho cá nhân","Chỉ thông báo cho cá nhân, không công khai trong cơ quan","Được báo cáo lên cơ quan quản lý cấp trên, không lưu hồ sơ"],c:0},{id:"vb08-138",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 1 Điều 27 Luật Cán bộ, công chức số 60/2025/QH15.",gt:"Kết quả đánh giá, xếp loại được dùng để đào tạo, bồi dưỡng, quy hoạch, điều động, bổ nhiệm, bố trí vào vị trí cao hơn; thực hiện tiền lương, khen thưởng, thu nhập tăng thêm; hoặc bố trí vào vị trí thấp hơn, cho thôi việc với trường hợp không hoàn thành nhiệm vụ. Đẩy là điểm mối quan trọng: gắn kết quả đánh giá với bố trí, sử dụng và cả việc cho thôi việc.",mn:"Kết quả đánh giá ¬› thưởng/đề bạt (tốt) hoặc bố trí thấp hơn/cho thôi việc (không hoàn thành).",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, kết quả theo dõi, đánh giá, xếp loại chất lượng công chức được sử dụng để làm gì?",o:["Chí để bình xét thi đua, khen thưởng cuối năm","Chí để thực hiện việc nâng lương thường xuyên","Để xem xét đào tạo, bồi dưỡng, quy hoạch, điều động, bổ nhiệm, bố trí vào vị trí việc làm cao hơn; thực hiện chế độ tiền lương, khen thưởng; hoặc bố trí vào vị trí việc làm thấp hơn, cho thôi việc đối với trường hợp không hoàn thành nhiệm vụ","Chí để lưu hồ sơ, không sử dụng vào việc bố trí, sử dụng công chức"],c:2},{id:"vb08-139",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điểm c khoản 1 Điều 27 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Đối với công chức không hoàn thành nhiệm vụ hoặc không đáp ứng yêu cầu nhiệm vụ, cơ quan có thẩm quyền có thể bố trí vào vị trí việc làm thấp hơn hoặc cho thôi việc.",mn:"Không hoàn thành nhiệm vụ: có thể bố trí thấp hơn hoặc cho thôi việc.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, đối với công chức không hoàn thành nhiệm vụ hoặc không đáp ứng yêu cầu nhiệm vụ, cơ quan có thẩm quyền có thể xem xét, quyết định điều gì?",o:["Chuyển sang làm viên chức tại đơn vị sự nghiệp","Chỉ nhắc nhở, phê bình và giữ nguyên vị trí","Tự động hạ ngạch sau hai năm liên tiếp","Bố trí vào vị trí việc làm thấp hơn hoặc cho thôi việc"],c:3},{id:"vb08-140",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điểm a và điểm b khoản 1 Điều 27 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Kết quả xếp loại tốt có thể được sử dụng để đào tạo, bồi dưỡng, quy hoạch, bổ nhiệm hoặc bố trí vào vị trí cao hơn; khen thưởng, thực hiện chế độ thu mm _— lạ lỄ Ici{ ( Úc ( —0.-) l [ ii lại 51 nhập tăng thêm, tiền thưởng. Đây là cơ chế khuyến khích, không phải bắt buộc bổ nhiệm ngay hay tự động nâng lương.",mn:"Xếp loại tốt: xem xét đào tạo, quy hoạch, bổ nhiệm, khen thưởng, thu nhập tăng thêm.",t:"m",q:"Một tình huống: Công chức P liên tục được theo dõi, đánh giá trong năm và cuối năm được xếp loại 'hoàn thành xuất sắc nhiệm vụ'. Theo Luật Cán bộ, công chức số 80/2025/QH15, kết quả này có thể được cơ quan sử dụng để làm gì?",o:["Xem xét đào tạo, bồi dưỡng, quy hoạch, bổ nhiệm hoặc bố trí vào vị trí việc làm cao hơn; khen thưởng, thực hiện chế độ thu nhập tăng thêm, tiền thưởng theo quy định","Chí để ghi nhận thành tích, không sử dụng vào việc bố trí, sử dụng","Bắt buộc phải bổ nhiệm ngay vào chức vụ lãnh đạo","Tự động nâng hai bậc lương"],c:0},{id:"vb08-141",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản Ì Điều 25 Luật Còn bộ, công chức số 80/2025/Ql115.",gt:"Cả ba đều là nguyên tắc đánh giá công chức: khách quan, đa chiều; định lượng tối đa gán vị trí việc làm; ứng dụng khoa học, công nghệ, chuyển đổi số.",mn:"Đánh giá: đa chiều + định lượng + ứng dụng công nghệ.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, các nguyên tắc sau có cùng thuộc nguyên tắc đánh giá công chức hay không: (i) khách quan, đa chiều; (ii) định lượng tối đa gắn vị trí việc làm; Gii) ứng dụng khoa học, công nghệ, chuyển đổi số?",o:["Chỉ nguyên tắc (1) đúng","Chỉ nguyên tắc (1) và (ii) đúng","Không nguyên tắc nào đúng","Cá ba nguyên tắc đều thuộc nguyên tắc đánh giá công chức"],c:3},{id:"vb08-142",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điều 25, Điều 26, Điều 27 Luật Cán bộ, công chức số 80/2025/QH13.",gt:"Kết quả đánh giá, xếp loại được sử dụng để đào tạo, quy hoạch, bổ nhiệm, bố trí cao hơn, khen thưởng và cả bố trí vào vị trí thấp hơn hoặc cho thôi việc với trường hợp không hoàn thành nhiệm vụ — không chí để bình xét thi đua. Vì vậy phương án D sai.",mn:"Kết quả đánh giá gắn với bố trí, sử dụng và cả cho thôi việc, không chỉ thi đua.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, nhận định nào sau đây về đánh giá, xếp loại công chức là KHÔNG đúng?",o:["Việc đánh giá bảo đảm dân chủ, công khai, khách quan, đa chiều","Kết quả đánh giá chỉ dùng để bình xét thi đua, không liên quan đến việc bố trí, cho thôi việc","Kết quả xếp loại được thông báo đến cá nhân, công khai và lưu hồ sơ","Công chức được xếp loại theo bốn mức từ hoàn thành xuất sắc đến không hoàn thành nhiệm vụ"],c:1},{id:"vb08-143",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 2 Điều 44 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Mặc dù Luật có hiệu lực từ 01/7/2025, quy định về đánh giá công chức tại Mục 3 Chương IV được thực hiện từ ngày 01/01/2026. Đẩy là điểm dễ nhầm về thời điểm áp dụng. Lướit BÓC 2025 xr ng 52",mn:"Đánh giá công chức (Mục 3 Ch.IV): áp dụng từ 01/01/2026.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, quy định về đánh giá công chức tại Mục 3 Chương IV được thực hiện kể từ thời điểm nào?",o:["Từ ngày Luật được thông qua","Từ ngày 01 tháng 7 năm 2025","Từ ngày 01 tháng 01 năm 2026","Từ ngày 01 tháng 7 năm 2027"],c:2},{id:"vb08-144",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điểm a khoản 1 và khoản 3 Điều 25 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"'Đa chiều' nghĩa là đánh giá từ nhiều phía, nhiều nguồn thông tin (cấp trên, đồng nghiệp, kết quả công việc, thái độ phục vụ người dân, doanh nghiệp...) thay vi chỉ một chiều từ trên xuống, bảo đảm khách quan, toàn diện.",mn:"'Đa chiều' = đánh giá từ nhiều phía, không chỉ một chiều từ trên xuống.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, việc đánh giá theo hướng 'đa chiều' được hiểu là gì?",o:["Đánh giá nhiều lần trong một năm","Đánh giá từ nhiều phía, nhiều nguồn thông tin (cấp trên, đồng nghiệp, kết quả công việc, phản hồi của người dân, doanh nghiệp đối với vị trí tiếp xúc trực tiếp) thay vi chí đánh giá một chiều từ trên xuống","Đánh giá nhiều công chức cùng lúc","Đánh giá theo nhiêu mức xếp loại khác nhau"],c:1},{id:"vb08-145",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điểm d khoản 4 Điều 25 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Kết quả thực hiện nhiệm vụ được đánh giá qua số lượng, chất lượng và tiến độ của sản phẩm theo vị trí việc làm - đo lường bằng kết quả, sản phẩm cụ thể.",mn:"Kết quả nhiệm vụ do bằng: số lượng — chất lượng ~ tiến độ của sản phẩm theo V1TVL.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, kết quả thực hiện nhiệm vụ của công chức được đánh giá thông qua yếu tố nào sau đây?",o:["Thâm niên và kinh nghiệm công tác","Số giờ làm việc và mức độ chuyên cần","Số lượng văn bản đã ban hành trong năm","Số lượng, chất lượng và tiến độ của sản phẩm theo vị trí việc làm"],c:3},{id:"vb08-146",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điều 25, Điều 26, Điều 27 Luật Cán bộ, công chức số 80/2025/QH13.",gt:"Đổi mới trong đánh giá: khách quan, đa chiều, xuyên suốt, liên tục; định lượng theo kết quả, sản phẩm gắn vị trí việc làm; ứng dụng công nghệ: xếp loại bốn mức và sử dụng kết quả để bố trí, sử dụng, khen thưởng hoặc cho thôi việc.",mn:'Đánh giá mới: đa chiều — định lượng theo sản phẩm - công nghệ - gắn với sử dụng, cho thôi việc. ˆ › — 53 Luật CDCC 2025 "rung 3',t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, phương án nào sau đây phản ánh ĐÚNG và ĐẦY ĐỦ nhất về đối mới trong đánh giá công chức?",o:["Đánh giá theo thâm niên và bằng cấp, không gắn với kết quả công việc","Đánh giá một chiều từ trên xuống, chủ yếu dựa vào nhận xét định tình cuối năm","Đánh giá khách quan, đa chiều, xuyên suốt, liên tục; định lượng tối đa theo kết quả, sản phẩm gắn với vị trí việc làm; ứng dụng công nghệ; xếp loại theo bổn mức và sử dụng kết quả để bố trí, sử dụng, khen thưởng hoặc cho thôi việc","Đánh giá chí để bình xét thi đua, không ảnh hưởng đến việc sử dụng công chức"],c:2},{id:"vb08-147",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điểm c khoản 4 Điều 25 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Một nội dung đánh giá được nhận mạnh là năng lực đối mới, sáng tạo, dám nghĩ, dám làm, dám chịu trách nhiệm vì lợi ích chung - gắn với chủ trương khuyến khích, bảo vệ cán bộ năng động, sáng tạo.",mn:"Đánh giá thêm: đổi mới, sáng tạo, dám nghĩ, dám làm, dám chịu trách nhiệm.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, năng lực nào sau đây được bổ sung làm một nội dung đánh giá công chức nhằm khuyến khích tinh thần dám đổi mới?",o:["Năng lực đối mới, sáng tạo, dám nghĩ, dám làm, dám chịu trách nhiệm vì lợi ích chung trong thực thi công vụ","Năng lực ngoại ngữ và tin học","Năng lực quản lý tài chính, ngân sách","Năng lực xây dựng văn bản quy phạm pháp luật"],c:0},{id:"vb08-148",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điểm b khoản 4 Điều 25 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Đối với các vị trí việc làm tiếp xúc trực tiếp với người dân, doanh nghiệp, nội dung đánh giá đặc biệt chú trọng thái độ phục vụ người dân, doanh nghiệp.",mn:"Vị trí tiếp dân: chú trọng thái độ phục vụ người dân, doanh nghiệp.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, đối với vị trí việc làm tiếp xúc trực tiếp với người dân, doanh nghiệp, nội dung đánh giá đặc biệt chú trọng yếu tố nào?",o:["Thời gian có mặt tại nơi làm việc","Số lượng hồ sơ tiếp nhận trong ngày","Thái độ phục vụ người dân, doanh nghiệp","Số lượng văn bản tham mưu đã trình"],c:2},{id:"vb08-149",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điều 27 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Việc gắn kết quả đánh giá với khả năng bố trí vào vị trí thấp hơn hoặc cho thôi việc nhằm tạo cơ chế sàng lọc, nâng cao chất lượng đội ngũ, khắc phục tình trạng đánh giá hình thức và tạm lý 'có vào không có ra. Đây không thay thế cơ chế xử lý kỷ luật (vốn áp dụng cho hành vi vi phạm).",mn:"Gắn đánh giá với cho thôi việc = cơ chế sàng lọc, không còn 'có vào không có ra'. Lướit BÓC 2025 xr ng 54 CHƯƠNG IV - CÔNG CHỨC (Mục 4, 5, 6: Đào tạo, bồi dưỡng; điều động, bổ nhiệm, luân chuyển, biệt phái, từ chức, miễn nhiệm; thôi việc, nghỉ hưu) Phạm vi: Điều 28 đến Điều 32 ~— trách nhiệm và quyền lợi trong đào tạo, bồi dưỡng; điều động, luân chuyển, biệt phái công chức; bổ nhiệm, từ chức, miễn nhiệm, cho thôi giữ chức vụ; thôi việc, nghỉ hưu đối với công chức.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, việc gắn kết quả đánh giá với khả năng bị bố trí vào vị trí thấp hơn hoặc cho thôi việc có ý nghĩa chủ yếu nào sau đây?",o:["Tạo cơ chế sàng lọc, nâng cao chất lượng đội ngũ công chức, khắc phục tình trạng đánh giá hình thức, 'có vào không có ra'","Tạo áp lực hành chính để tăng số giờ làm việc","Giảm số lượng biên chế một cách cơ học","Thay thế hoàn toàn cơ chế xử lý kỷ luật công chức"],c:0},{id:"vb08-150",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 1 Điều 28 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Cơ quan quản lý công chức căn cứ yêu cầu của vị trí việc làm, nhu cầu phát triển nguồn nhân lực để xây dựng kế hoạch và cử công chức tham gia đào tạo, bồi dưỡng.",mn:"Cơ quan quản lý: xây dựng kế hoạch + cử công chức đi đào tạo theo yêu cầu VTVL,",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, trong đào tạo, bồi dưỡng công chức, cơ quan quản lý công chức có trách nhiệm gì?",o:["Trực tiếp tổ chức các lớp đào tạo, bồi dưỡng cho công chức","Căn cứ yêu cầu của vị trí việc làm, nhu cầu phát triển nguồn nhân lực, xây dựng kế hoạch và cử công chức tham gia đào tạo, bồi dưỡng","Cấp kinh phí đào tạo cho cá nhân công chức từ lựa chọn khoa học","Quyết định nội dung chương trình đào tạo của các cơ sở đào tạo"],c:1},{id:"vb08-151",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 3 Điều 28 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Kinh phí đào tạo, bồi dưỡng công chức do ngân sách nhà nước cấp và các nguồn kinh phí khác theo quy định của pháp luật.",mn:"Kinh phí đào tạo: ngân sách nhà nước + nguồn khác theo quy định.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, kinh phí đào tạo, bồi dưỡng công chức được bảo đảm từ nguồn nào?",o:["Do doanh nghiệp tài trợ theo thỏa thuận","Hoàn toàn do công chức từ chi trả","Do các cơ sở đào tạo tự cần đối","Do ngân sách nhà nước cấp và các nguồn kinh phí khác theo quy định của pháp luật"],c:3},{id:"vb08-152",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 4 Điều 29 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Công chức được đào tạo nếu tự ý bỏ việc, thôi việc thì phải đền bù chi phí đào tạo theo quy định của pháp luật.",mn:'Được đào tạo mà tự ý bỏ việc, thôi việc. đền bù chi phí đào tạo. mm — loại Luạt CDCC 2025 "ri 22',t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, công chức được đào tạo nếu tự ý bỏ việc, thôi việc thì phải thực hiện nghĩa vụ nào?",o:["Không phải đền bù nếu đã hoàn thành khóa đào tạo","Phải đền bù chi phí đào tạo theo quy định của pháp luật","Chỉ phải đền bù một phần chi phí đi lại","Phải tiếp tục công tác thêm thời gian gấp đổi thời gian đào tạo"],c:1},{id:"vb08-153",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 1 Ðieu 3U Luật C an bộ, công chức số 80/2025/QH15.",gt:"Việc điều động, luân chuyển, biệt phái phải căn cứ vào phẩm chất chính trị, đạo đức, năng lực, trình độ chuyên môn, nghiệp vụ của công chức và nhu cầu của cơ quan, tổ chức, đơn vị.",mn:"Điều động/luân chuyển/biệt phái: căn cứ phẩm chất, năng lực + nhu cầu cơ quan.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, việc điều động, luân chuyển, biệt phái công chức phải căn cứ vào những yếu tố nào?",o:["Số lượng biên chế còn trong của cơ quan nhận","Nguyện vọng cá nhân của công chức và tham niền công tác","Phẩm chất chính trị, đạo đức, năng lực, trình độ chuyên môn, nghiệp vụ của công chức và nhu cầu của cơ quan, tổ chức, đơn vị","Quan hệ công tác và đề xuất của người đứng đầu"],c:2},{id:"vb08-154",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 2 Điều 30 Luật Cán bộ, công chức số 90/2025/QH15.",gt:"Công chức được điều động thuộc biên chế của cơ quan NHÂN điều động (chuyến hắn): công chức biệt phái vẫn thuộc biên chế của cơ quan CỬ biệt phái (di có thời hạn rồi quay về). Đây là điểm phân biệt then chốt.",mn:"Điều động ~ biên chế cơ quan nhận; Biệt phái ¬ vẫn biên chế cơ quan cử.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, công chức được điều động và công chức biệt phái thuộc biên chế của cơ quan nào?",o:["Công chức được điều động thuộc biên chế của cơ quan nhận điều động; công chức biệt phái vẫn thuộc biên chố của cơ quan cử biệt phái","Cả hai đều thuộc biên chế của cơ quan nhận","Cả hai đều thuộc biên chế của cơ quan cử đi","Công chức được điều động thuộc biên chế cơ quan cử; công chức biệt phái thuộc biên chế cơ quan nhận"],c:0},{id:"vb08-155",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 2 Điều 30 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Việc luân chuyển chỉ thực hiện đối với công chức lãnh đạo, quản lý theo yêu cầu nhiệm vụ, căn cứ vào quy hoạch cán bộ đã được phê duyệt. Đây là điểm phân biệt luân chuyển với điều động, biệt phái (vốn áp dụng rộng hơn).",mn:'Luân chuyển: chỉ với công chức lãnh đạo, quản lý theo quy hoạch. Luật CDCC 2025 "rung 3',t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, việc luân chuyển được thực hiện đối với đối tượng nào?",o:["Công chức mới được tuyển dụng để rèn luyện","Mọi công chức không phân biệt chức vụ","Công chức chuyên môn, nghiệp vụ có thẩm niền cao","Công chức lãnh đạo, quản lý theo yêu cầu nhiệm vụ căn cứ vào quy hoạch cán bộ đã được cơ quan, tổ chức có thẩm quyền phê duyệt"],c:3},{id:"vb08-156",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 2 Điều 31 Luật Cán bộ, công chức số 80/2025/0H15.",gt:"Thời hạn bổ nhiệm công chức giữ chức vụ lãnh đạo, quản lý là 05 năm; thời hạn dưới 05 năm áp dụng đối với một số chức danh đặc thù theo quy định của pháp luật có liên quan hoặc của cấp có thẩm quyền.",mn:"Thời hạn bổ nhiệm lãnh đạo, quản lý: 05 năm.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, thời hạn bổ nhiệm công chức giữ chức vụ lãnh đạo, quản lý là [......... I, trừ một số chức danh đặc thù có thời hạn dưới mức này.",o:["05 năm","03năm","07 năm","10 năm"],c:0},{id:"vb08-157",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 1 Điều 31 Luật Cán bộ, công chức số 60/2025/QH15.",gt:"Khi được bổ nhiệm chức vụ lãnh đạo, quản lý mới thì công chức đương nhiên thôi giữ chức vụ lãnh đạo, quản lý đang đảm nhiệm, trừ trường hợp kiêm nhiệm.",mn:"Bổ nhiệm chức vụ mới ¬ đương nhiên thôi chức cử (trừ kiêm nhiệm).",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, khi công chức được bố nhiệm giữ chức vụ lãnh đạo, quản lý mới thì việc giữ chức vụ đang đảm nhiệm được xử lý như thế nào?",o:["Tạm thời giữ cả hai chức vụ cho đến hết nhiệm kỳ","Vẫn giữ song song cả hai chức vụ trong mọi trường hợp","Phải có quyết định miễn nhiệm chức vụ cụ trước khi bổ nhiệm chức vụ mới","Đương nhiên thôi giữ chức vụ lãnh đạo, quản lý đang đảm nhiệm, trừ trường hợp kiêm nhiệm"],c:3},{id:"vb08-158",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"khoản 2 Điều 31 Luật Cúón bộ, công chức số 80/2025/QH15.",gt:"Khi hết thời hạn bổ nhiệm, cấp có thẩm quyền phải xem xét bổ nhiệm lại hoặc không bố nhiệm lại, trừ trường hợp chưa được xem xét, bổ nhiệm lại theo quy định.",mn:"Hết thời hạn bổ nhiệm: phải xem xét bổ nhiệm lại hoặc không bổ nhiệm lại. Lướit BÓC 2025 xr ng 57",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, khi hết thời hạn bổ nhiệm, cấp có thẩm quyền phải thực hiện việc gì đối với công chức lãnh đạo, quản lý?",o:["Đương nhiên gia hạn thời hạn bổ nhiệm thêm 05 năm","Phải xem xét bổ nhiệm lại hoặc không bố nhiệm lại, trừ trường hợp chưa được xem xét, bổ nhiệm lại theo quy định","Đương nhiên cho thôi giữ chức vụ","Chuyển sang vị trí việc làm chuyên môn, nghiệp vụ"],c:1},{id:"vb08-159",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"!)iếm a khoản 1 Điều 32 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Công chức thôi việc theo nguyện vọng cá nhân và phải được cơ quan, tổ chức có thẩm quyền đồng ý - không phải cụ có đơn là đương nhiên được thôi việc.",mn:"Thôi việc theo nguyện vọng: cần được cơ quan có thẩm quyền đồng ý.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, công chức được giải quyết thôi việc theo nguyện vọng cá nhân khi nào?",o:["Khi công chức đã công tác đủ thời gian tối thiểu theo quy định","Bất cứ khi nào công chức có đơn xin thôi việc","Theo nguyện vọng cá nhân và được cơ quan, tổ chức có thẩm quyền đồng ý","Khi công chức tìm được công việc mới phù hợp hơn"],c:2},{id:"vb08-160",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điểm a khoản 1 Điều 32 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Không giải quyết thôi việc đối với công chức đang trong thời gian xem xét xử lý kỷ luật hoặc bị truy cứu trách nhiệm hình sự hoặc các trường hợp khác theo quy định.",mn:"Không cho thôi việc khi đang xem xét kỷ luật / truy cứu TNHS.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, trường hợp nào sau đây KHÔNG được giải quyết thôi việc đối với công chức?",o:["Công chức đang trong thời gian xem xét xử lý kỷ luật hoặc bị truy cứu trách nhiệm hình sự","Công chức có nguyện vọng thôi việc và được cơ quan đồng ý","Công chức không hoàn thành nhiệm vụ đến mức phải cho thôi việc","Công chức đủ điều kiện nghỉ hưu theo quy định"],c:0},{id:"vb08-161",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 2 Điều 32 Luật Cán bộ, công chức số 60/2025/QH15.",gt:"Công chức được nghỉ hưu theo quy định của Bộ luật Lao động, trừ trường hợp theo quy định của cấp có thẩm quyền.",mn:"Nghỉ hưu: theo Bộ luật Lao động (trừ trường hợp đặc thù).",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, công chức được nghỉ hưu theo quy định của pháp luật nào?",o:["Theo quy định riêng của Luật Cán bộ, công chức","Theo quy định của Bộ luật Lao động, trừ trường hợp theo quy định của cấp có thẩm quyền","Theo quy định của Luật Bảo hiểm xã hội về tuổi nghỉ hưu của công chức","Theo quyết định của người đứng đầu cơ quan sử dụng công chức"],c:1},{id:"vb08-162",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"J)iếm q khoản! Điều 32 Luật Cán bộ, công chức số 80/2025/QH IS.",gt:"Vì ông () đang trong thời gian xem xét xử lý kỷ luật nền không được giải quyết thôi việc theo nguyện vọng. Quy định này nhằm tránh việc thôi việc để né tránh trách nhiệm.",mn:"Đang bị xem xét kỷ luật ¬ không cho thôi việc.",t:"m",q:"Một tình huống: Ông Q là công chức đang trong thời gian bị xem xét xử lý kỷ luật thì nộp đơn xin thôi việc theo nguyện vọng. Theo Luật Cán bộ, công chức số 80/2025/QH15, đơn xin thôi việc của ông Q được giải quyết như thế nào?",o:["Được giải quyết sau khi ông Q nộp đủ chi phí đào tạo","Được giải quyết thôi việc ngay theo nguyện vọng","Được giải quyết nêu ông Q cam kết không khiếu nại Luạt CDCC 2025 Sư)","Không được giải quyết thôi việc, vì ông Q đang trong thời gian xem xét xử lý kỷ luật"],c:3},{id:"vb08-163",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 4 Điều 29 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Công chức được đào tạo mà tự ý bỏ việc, thôi việc thì phải đền bù chi phí đào tạo theo quy định của pháp luật. Bà R thuộc trường hợp này nên phải đền bù chi phí đào tạo.",mn:"Được đào tạo rôi tự ý bỏ việc ¬ đền bù chi phí đào tạo.",t:"m",q:"Một tình huống: Bà R (công chức) được cử đi đào tạo theo kế hoạch bằng kinh phí ngân sách, nhưng sau khi học xong đã tự ý bỏ việc để chuyển sang khu vực tư nhân. Theo Luật Cán bộ, công chức số 80/2025/QH15, bà R cú nghĩa vụ gì?",o:["Chỉ phải hoàn trả học phí, không phải chi phí khác","Không phải đền bù vi đã hoàn thành khóa đào tạo","Phải đền bù chi phí đào tạo theo quy định của pháp luật","Phải quay lại làm việc đủ thời gian cam kết mới được thôi việc"],c:2},{id:"vb08-164",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 1 Điều 31 Luật Cán bộ, công chức số 60/2025/QH15.",gt:"Khi được bố nhiệm chức vụ lãnh đạo, quản lý mới (Phó Giám đốc Sở), ông S đương nhiên thôi giữ chức vụ đang đảm nhiệm (Trường phòng), trừ trường hợp kiêm nhiệm.",mn:"Bổ nhiệm chức mới ¬ đương nhiên thôi chức cử (trừ kiêm nhiệm).",t:"m",q:"Một tình huống: Ông S là Trưởng phòng (công chức lãnh đạo) được bố nhiệm giữ chức vụ Phó Giám đốc Sở. Theo Luật Cán bộ, công chức số 80/2025/QH15, việc giữ chức Trưởng phong của ông S được xử lý như thế nào?",o:["Phải có đơn xin từ chức Trưởng phòng trước","Vẫn giữ đồng thời cả hai chức vụ","Phải cho hết thời hạn bổ nhiệm chức Trưởng phòng","Đương nhiên thôi giữ chức Trưởng phòng, trừ trường hợp kiêm nhiệm"],c:3},{id:"vb08-165",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điều 30 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Điều động: chuyến hạn, thuộc biên chế nơi nhận; biệt phái: cử đi có thời hạn, vẫn thuộc biên chế nơi cử; luân chuyển: chỉ áp dụng với công chức lãnh đạo, quản lý theo quy hoạch.",mn:"Điều động (chuyến hắn) - biệt phái (có thời hạn) - luân chuyển (lãnh đạo, theo quy hoạch).",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, phân biệt điều động, biệt phái và luân chuyển công chức, nội dung nào sau đây là DÙNG?",o:["Điều động là chuyên hăn (thuộc biên chế nơi nhận); biệt phái là cử đi có thời hạn (vẫn thuộc biên chế nơi cử); luân chuyển chỉ áp dụng với công chức lãnh đạo, quản lý theo quy hoạch","Cả ba đều là chuyên hạn công chức sang cơ quan khác","Cả ba đều áp dụng cho mọi công chức không phân biệt chức vụ","Điều động và biệt phái đều giữ nguyên biên chế ở cơ quan cử"],c:0},{id:"vb08-166",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 1 và khoản 2 Điều 29 Luật Còn bộ, công chức số 80/2025/QH15.",gt:"C'ông chức có trách nhiệm tự nghiên cứu, học tập để nâng cao trình độ và tham gia các lớp đào tạo, bồi dưỡng theo kế hoạch; chấp hành quy định về đào tạo, bồi dưỡng của cơ sở đào tạo và của cơ quan cử đi.",mn:"CBCC: tự học + tham gia đào tạo theo kế hoạch + chấp hành quy định đào tạo.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, trách nhiệm của công chức trong đào tạo, bồi dưỡng bao gồm những nội dung nào sau đây?",o:["Tự lựa chọn khoa học và cơ sở đào tạo theo nguyện vọng","Tự nghiên cứu, học tập để nâng cao trình độ và tham gia các lớp đòo tạo, bồi dưỡng theo kế hoạch; chấp hành quy định về đào tạo, bồi dưỡng của cơ sở đào tạo và của cơ quan cử đi","Chỉ tham gia đào tạo khi được hưởng nguyên lương và phụ cấp","Được miễn mọi nghĩa vụ công tác trong thời gian đào tạo"],c:1},{id:"vb08-167",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Khoản 3 Điều 31 Luật Cán bộ, công chức số 80/2025/QMH15.",gt:"Việc từ chức, miễn nhiệm, cho thôi giữ chức vụ và các nội dung liên quan đối với công chức lãnh đạo, quản lý được thực hiện theo quy định của cấp có thẩm quyền và của Chính phủ.",mn:"Từ chức, miễn nhiệm, thôi giữ chức vụ: theo quy định cấp có thẩm quyền + Chính phủ.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, việc từ chức, miễn nhiệm, cho thôi giữ chức vụ đối với công chức lãnh đạo, quản lý được thực hiện theo quy định của ai?",o:["Theo nguyện vọng của công chức là chính","Theo quyết định của người đứng đầu cơ quan sử dụng công chức","Theo quy định của cấp có thẩm quyền và của Chính phủ","Theo quy định của Hội đồng nhân dân cấp tỉnh"],c:2},{id:"vb08-168",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điều 30 Luật Cán bộ, công chức số 80/2025/0J1115. Lưới t BCtC 2095 gi 60",gt:"Công chức biệt phái vẫn thuộc biên chế của cơ quan CỬ biệt phái (đi có thời hạn rồi quay vê), không chuyên hẳn biên chế sang cơ quan nhận. Vì vậy phương án D sai. Các nhận định A, B, C đều đúng.",mn:"Biệt phái: không chuyên biên chế (vẫn thuộc cơ quan cử).",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, nhận định nào sau đây về điều động, biệt phái công chức là KHÔNG đúng?",o:["Công chức được điều động thuộc biên chế của cơ quan nhận điều động","Công chức biệt phái vẫn thuộc biên chế của cơ quan cử biệt phái","Việc điều động, biệt phái căn cứ vào phẩm chất, năng lực của công chức và nhu cầu của cơ quan","Công chức biệt phái được chuyển hắn biên chế sang cơ quan nhận biệt phái"],c:3},{id:"vb08-169",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điểm b khoản 1 Điều 32 và điểm c khoản 1 Điều 27 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Công chức bị cho thôi việc khi không hoàn thành nhiệm vụ hoặc không đáp ứng yêu cầu nhiệm vụ (theo kết quả theo dõi, đánh giá, xếp loại) đến mức phải cho thôi việc. Đây là cơ chế gắn đánh giá với sàng lọc đội ngũ.",mn:"Thõôi việc do không hoàn thành/không đáp ứng yêu cầu nhiệm vụ (theo đánh giá).",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, công chức bị thôi việc do không hoàn thành nhiệm vụ được xác định trên cơ sở nào?",o:["Chỉ cần một năm bị xếp loại không hoàn thành nhiệm vụ","Không hoàn thành nhiệm vụ hoặc không đáp ứng yêu cầu nhiệm vụ theo kết quả theo dõi, đánh giá, xếp loại đến mức phải cho thôi việc","Theo đề nghị của tập thể cơ quan, đơn vị","Theo nguyện vọng của chính công chức đó"],c:1},{id:"vb08-170",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Điều 3! Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Cả ba đều đúng: bổ nhiệm thực hiện bằng quyết định của cấp có thẩm quyền; thời hạn bổ nhiệm là 05 năm (trừ chức danh đặc thù); khi hết thời hạn phải xem xét bổ nhiệm lại hoặc không bố nhiệm lại.",mn:"Dổ nhiệm: quyết định cấp có thẩm quyền - thời hạn 05 năm - hết hạn xem xét lại.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, các nội dung sau có cùng đúng về bố nhiệm công chức lãnh đạo, quản lý hay không: (i) thực hiện bằng quyết định của cấp có thẩm quyền; (ii) thời hạn bổ nhiệm là 05 năm; (iii) khi hết thời hạn phải xem xét bổ nhiệm lại hoặc không bố nhiệm lại?",o:["Chỉ nội dung (i) đúng","Chí nội dung (i) và (1i) đúng","Cả ba nội dung đều đúng","Không nội dung nào đúng"],c:2},{id:"vb08-171",s:"CHƯƠNG II - NGHĨA VỤ, QUYỀN CỦA CÁN BỘ, CÔNG CHỨC",cc:"Các điều từ 28 đến 32 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Quản lý, sử dụng công chức sau tuyển dụng: đào tạo, bồi dưỡng theo vị trí việc làm; điều động, luân chuyển (lãnh đạo, quản lý theo quy hoạch), biệt phái; bổ nhiệm theo thời hạn 05 năm; từ chức, miễn nhiệm, thôi việc, nghỉ hưu theo quy định, gắn với kết quả đánh giá.",mn:"Sau tuyển dụng: đào tạo - điều động/luân chuyển/hiệt phái — bổ nhiệm 5 năm ~ thôi việc/nghỉ hưu, gắn đánh giá. Lưới t BCtC 2095 gi 62 thưởng; loại trừ, miễn, giảm trách nhiệm; hình thức kỷ luật) Phạm vi phân I1: Điều 33 đến Diện 36 — khen thưởng cán bộ, công chức; loại trừ, miễn, giảm trách nhiệm; hình thức kỷ luật đối với cán bộ và đối với công chức.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, phương án nào sau đây phản ánh ĐÚNG và ĐẦY ĐỦ nhất các nội dung quản lý, sử dụng công chức sau tuyển dụng?",o:["Việc điều động, bổ nhiệm chỉ dựa vào nguyện vọng cá nhân của công chức","Công chức sau khi tuyển dụng được giữ nguyên vị trí suốt quá trình công tác","Công chức được đào tạo, bồi dưỡng theo vị trí việc làm; được điều động, luân chuyển (với lãnh đạo, quản lý theo quy hoạch), biệt phái; được bố nhiệm theo thời hạn 05 năm; thực hiện từ chức, miễn nhiệm, thôi việc, nghỉ hưu theo quy định, gắn với kết quả đánh giá","Công chức không phải đền bù chi phí đào tạo trong mọi trường hợp"],c:2},{id:"vb08-172",s:"CHƯƠNG V - KHEN THƯỞỚNG, XỬ LÝ KỶ LUẬT (Phần 1: Khen",cc:"Khoản 1 Điều 33 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Cán bộ, công chức có thành tích trong công vụ được khen thưởng theo quy định của pháp luật về thi đua, khen thưởng.",mn:"Khen thưởng CBCC: theo pháp luật về thi đua, khen thưởng.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, cán bộ, công chức có thành tích trong công vụ thì được khen thưởng theo quy định của pháp luật nào?",o:["Theo quy định của pháp luật về thi đua, khen thưởng","Theo quy định riêng của Luật Cán bộ, công chức","Theo quyết định của người đứng đầu cơ quan sử dụng","Theo quy chế nội bộ của từng cơ quan, tổ chức, đơn vị"],c:0},{id:"vb08-173",s:"CHƯƠNG V - KHEN THƯỞỚNG, XỬ LÝ KỶ LUẬT (Phần 1: Khen",cc:"Khoản 2 Điều 33 Luật (ân bộ, công chức số 80/2025/00H 1S.",gt:"Cán bộ, công chức có thành tích xuất sắc hoặc công trạng được nâng lương trước thời hạn, hưởng tiền thưởng từ quỹ tiền thưởng của cơ quan, được ưu tiên khi xem xét bổ nhiệm chức vụ cao hơn nếu cơ quan có nhu cầu. Đây là 'ưu tiên xem xét, không phải tự động bổ nhiệm.",mn:"Thành tích xuất sắc: nâng lương trước hạn + tiền thưởng 1 ưu tiên xem xét bổ nhiệm.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, cán bộ, công chức được khen thưởng do có thành tích xuất sắc hoặc công trạng thì được hưởng quyền lợi nào sau đây?",o:["Được tự động bố nhiệm vào chức vụ lãnh đạo, quản lý","Được nâng lương trước thời hạn, hưởng tiền thưởng từ quỹ tiền thưởng của cơ quan, được ưu tiên khi xem xét bổ nhiệm chức vụ cao hơn nếu cơ quan có nhu cầu","Được nâng hai bậc lương và chuyển ngạch ngay","Được miễn đánh giá, xếp loại trong năm tiếp theo"],c:1},{id:"vb08-174",s:"CHƯƠNG V - KHEN THƯỞỚNG, XỬ LÝ KỶ LUẬT (Phần 1: Khen",cc:'Khoản 1 Điều 34 Luật Cán bộ, công chức số 80/2025/QH15. Luôi CBCC 2025 "rang 63',gt:"Các trường hợp được xem xét loại trừ, miễn, giảm trách nhiệm: chấp hành quyết định trái pháp luật của cấp trên nhưng đã báo cáo; thực hiện đúng thẩm quyền, trình tự, thủ tục, không vụ lợi nhưng thiệt hại vì lý do khách quan; thực hiện đề xuất đổi mới, sáng tạo được cho phép, động cơ trong sáng, vì lợi ích chung; do bất khả kháng; và các trường hợp khác theo quy định.",mn:"Loại trừ trách nhiệm: đã báo cáo quyết định trái luật ~ lạm dụng nhưng thiệt hại khách quan - đổi mới sáng tạo trong sáng - bất khả kháng.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, cán bộ, công chức được xem xét loại trừ, miễn, giảm trách nhiệm trong trường hợp nào sau đây?",o:["Phải chấp hành quyết định trái pháp luật của cấp trên nhưng đã báo cáo theo quy định; đã thực hiện đúng thẩm quyền, trình tự, thủ tục, không vụ lợi nhưng vẫn gây thiệt hại vì lý do khách quan; thực hiện đề xuất đổi mới, sáng tạo được cho phép, có động cơ trong sáng, vì lợi ích chung; do bất khả kháng","Khi cán bộ, công chức có thâm niên công tác lâu năm","Khi cán bộ, công chức là người đứng đầu cơ quan","Khi cán bộ, công chức tự nhận khuyết điểm và xin lỗi"],c:0},{id:"vb08-175",s:"CHƯƠNG V - KHEN THƯỞỚNG, XỬ LÝ KỶ LUẬT (Phần 1: Khen",cc:"Điểm c khoản 1 Điều 34 Luật Cán bộ, công chức số 60/2025/QH15,",gt:"Cán bộ, công chức thực hiện đề xuất đổi mới, sáng tạo được xem xét loại trừ, miễn, giảm trách nhiệm khi được cơ quan có thẩm quyền cho phép và được xác định đã thực hiện đúng chủ trương, có động cơ trong sáng, vì lợi ích chung. Đây không phải miễn trách nhiệm vô điều kiện.",mn:"Bảo vệ đổi mới, sáng tạo: được cho phép + đúng chủ trương + động cơ trong sáng, vì lợi ích chung.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, việc bảo vệ cán bộ, công chức thực hiện đề xuất đổi mới, sáng tạo gắn với điều kiện nào sau đây?",o:["Phải mang lại hiệu quả kinh tế cụ thể mới được xem xét","Chỉ cần có ý tướng đổi mới là được miễn trách nhiệm","Được miễn trách nhiệm trong mọi trường hợp đối mới, sáng tạo","Được cơ quan, tổ chức có thẩm quyền cho phép và được xác định đã thực hiện đúng chủ trương, có động cơ trong sáng, Vì lợi ích chung"],c:3},{id:"vb08-176",s:"CHƯƠNG V - KHEN THƯỞỚNG, XỬ LÝ KỶ LUẬT (Phần 1: Khen",cc:"Khoản 1 Điều 35 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Hình thức kỷ luật đối với cán bộ: khiển trách; cảnh cáo; cách chức (áp dụng với cán bộ được phê chuẩn, bổ nhiệm hoặc chỉ định) và bãi nhiệm. Lưu ý: cán bộ có hình thức bãi nhiệm (không có 'buộc thôi việc).",mn:"Kỷ luật CÁN BỘ: khiển trách - cảnh cáo - cách chức - bãi nhiệm.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, các hình thức kỷ luật đối với CÁN BỘ gồm những hình thức nào?",o:["Khiển trách; cảnh cáo; cách chức; buộc thôi việc","Khiển trách; cảnh cáo; hạ bậc lương: buộc thôi việc","Khiển trách; cảnh cáo; cách chức (áp dụng đối với cán bộ được phê chuẩn, bổ nhiệm hoặc chỉ định giữ chức vụ, chức danh); bãi nhiệm","Khiển trách; cảnh cáo; giảng chức; cách chức; bãi nhiệm"],c:2},{id:"vb08-177",s:"CHƯƠNG V - KHEN THƯỞỚNG, XỬ LÝ KỶ LUẬT (Phần 1: Khen",cc:'Khoản 1 Điều 36 Luật Cán bộ, công chức số 80/2025/QH15. Luôi CBCC 2025 "ràng D4',gt:"Hình thức kỷ luật đối với công chức: khiển trách; cảnh cáo; cách chức (áp dụng với công chức lãnh đạo, quản lý) và buộc thôi việc. Lưu ý: công chức có hình thức buộc thôi việc (không có 'bãi nhiệm).",mn:"Kỷ luật CÔNG CHỨC: khiển trách - cảnh cáo - cách chức - buộc thôi việc.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, các hình thức kỷ luật đối với CÔNG CHỨC gồm những hình thức nào?",o:["Khiển trách; cảnh cáo; cách chức (áp dụng đối với công chức lãnh đạo, quản lý); buộc thôi việc","Khiển trách; cảnh cáo; cách chức; bãi nhiệm","Khiển trách; cảnh cáo; hạ bậc lương: giáng chức; buộc thôi việc","Khiển trách; cảnh cáo; giảng chức; cách chức; buộc thôi việc"],c:0},{id:"vb08-178",s:"CHƯƠNG V - KHEN THƯỞỚNG, XỬ LÝ KỶ LUẬT (Phần 1: Khen",cc:"Điều 35 và Điều 30 Luật Cán bộ, công chức số 00/2025/QHHD.",gt:"Điểm phân biệt then chốt: cán bộ có hình thức bãi nhiệm, còn công chức có hình thức buộc thôi việc. Cả hai đều có khiển trách, cảnh cầu, cách chức.",mn:"(án bộ ¬ bãi nhiệm; (ông chức ¬ buộc thôi việc.",t:"m",q:"Phân biệt hình thức kỷ luật giữa cán bộ và công chức theo Luật Cán bộ, công chức số 80/2025/QH15, nội dung nào sau đây là DÙNG?",o:["Cả cán bộ và công chức đều có hình thức buộc thôi việc","Cán bộ có hình thức kỷ luật cao nhất là bãi nhiệm; công chức có hình thức kỷ luật cao nhất là buộc thôi việc","Cả cán bộ và công chức đều có hình thức bãi nhiệm","Cán bộ có hình thức buộc thôi việc; công chức có hình thức bãi nhiệm"],c:1},{id:"vb08-179",s:"CHƯƠNG V - KHEN THƯỞỚNG, XỬ LÝ KỶ LUẬT (Phần 1: Khen",cc:"Điểm c khoản 1 Điều 36 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Hình thức kỷ luật cách chức đối với công chức chỉ áp dụng đối với công chức lãnh đạo, quản lý (người đang giữ chức vụ). Công chức không giữ chức vụ lãnh đạo, quản lý thì không bị 'cách chức.",mn:"Cách chức công chức: chỉ với công chức lãnh đạo, quản lý.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, hình thức kỷ luật 'cách chức' đối với công chức được áp dụng đối với đối tượng nào?",o:["Công chức mới được tuyển dụng","Mọi công chức không phân biệt chức vụ","Công chức chuyên môn, nghiệp vụ","Công chức lãnh đạo, quản lý"],c:3},{id:"vb08-180",s:"CHƯƠNG V - KHEN THƯỞỚNG, XỬ LÝ KỶ LUẬT (Phần 1: Khen",cc:"Khoản 2 Điều 36 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Công chức bị Tòa án kết án phạt tù mà không được hưởng án treo hoặc bị kết án về tội phạm tham nhũng thì đương nhiên bị buộc thôi việc kể từ ngày bản án, quyết định có hiệu lực pháp luật.",mn:"Công chức bị từ (không treo) hoặc tội tham nhũng ¬ đương nhiên buộc thôi việc. tLưôitt BÓC 2072 xr ng 65",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, công chức bị Tòa án kết án phạt tù mà không được hưởng án treo hoặc bị kết án về tội phạm tham nhũng thì bị xử lý như thế nào?",o:["Bị tạm đình chỉ công tác cho đến khi chấp hành xong bản án","Bị xem xét xử lý kỷ luật theo trình tự thông thường","Đương nhiên bị buộc thôi việc kể từ ngày bản án, quyết định có hiệu lực pháp luật","Bị hạ ngạch và chuyển sang vị trí việc làm thấp hơn"],c:2},{id:"vb08-181",s:"CHƯƠNG V - KHEN THƯỞỚNG, XỬ LÝ KỶ LUẬT (Phần 1: Khen",cc:"Khoản 2 †)leu 35 Luật Cán bộ, công chức số 80/2025/0(0H 15.",gt:"Cán bộ bị Tòa án kết án phạt tù mà không được hưởng án treo hoặc bị kết án về tội phạm tham nhũng thì đương nhiên bị bãi nhiệm kể từ ngày bản án có hiệu lực. (So với công chức là 'đương nhiên buộc thôi việc'.)",mn:"Cán bộ bị từ (không treo) hoặc tội tham nhũng ¬ đương nhiên bãi nhiệm.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, cán bộ bị Tòa án kết án phạt tù mà không được hưởng án treo hoặc bị kết án về tội phạm tham nhũng thì bị xử lý như thế nào?",o:["Đương nhiên bị bãi nhiệm kể từ ngày bản án, quyết định có hiệu lực pháp luật","Đương nhiên bị buộc thôi việc","Bị xem xét cách chức theo trình tự thông thường","Bị tạm đình chỉ chức vụ cho đến khi có kết luận cuối cùng"],c:0},{id:"vb08-182",s:"CHƯƠNG V - KHEN THƯỞỚNG, XỬ LÝ KỶ LUẬT (Phần 1: Khen",cc:"Khoản 2 Điều 36 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Công chức giữ chức vụ lãnh đạo, quản lý phạm tội bị Tòa án kết án và bản án đã có hiệu lực pháp luật thì đương nhiên thôi giữ chức vụ do bổ nhiệm.",mn:"(ông chức lãnh đạo bị kết án (bản án có hiệu lực) ¬ đương nhiên thôi giữ chức vụ.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, công chức giữ chức vụ lãnh đạo, quản lý phạm tội bị Tòa án kết án và bản án đã có hiệu lực pháp luật thì việc giữ chức vụ do bổ nhiệm được xử lý như thế nào?",o:["Chuyển sang giữ chức vụ thấp hơn tương ứng","Vẫn giữ chức vụ cho đến khi có quyết định cách chức","Được bảo lưu chức vụ trong thời gian kháng cáo","Đương nhiên thôi giữ chức vụ do bổ nhiệm"],c:3},{id:"vb08-183",s:"CHƯƠNG V - KHEN THƯỞỚNG, XỬ LÝ KỶ LUẬT (Phần 1: Khen",cc:"Điểm c khoản 1 Điều 35 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Hình thức cách chức đối với cán bộ áp dụng với cán bộ được phê chuẩn, bổ nhiệm hoặc chỉ định giữ chức vụ, chức danh. Đối với cán bộ do bầu cử thì hình thức tương ứng là bãi nhiệm.",mn:"Cách chức cán bộ: với người được phê chuẩn, bổ nhiệm, chỉ định (bầu cử, bãi nhiệm).",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, hình thức kỷ luật 'cách chức' đối với cán bộ được áp dụng đối với đối tượng nào?",o:["Cán bộ được bầu cử giữ chức vụ theo nhiệm kỳ","Cán bộ được phê chuẩn, bổ nhiệm hoặc chỉ định giữ chức vụ, chức danh","Mọi cán bộ không phân biệt cách thức hình thành chức vụ","Cán bộ là đại biểu dân cử"],c:1},{id:"vb08-184",s:"CHƯƠNG V - KHEN THƯỞỚNG, XỬ LÝ KỶ LUẬT (Phần 1: Khen",cc:"Khoản 2 Điều 36 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Công chức bị kết án về tội phạm tham nhũng thì đương nhiên bị buộc thôi việc kể từ ngày bản án có hiệu lực pháp luật, đồng thời đương nhiên thôi giữ chức vụ do bổ nhiệm.",mn:"Công chức tội tham nhũng ¬ đương nhiên buộc thôi việc.",t:"m",q:"Một tình huống: Ông T là công chức lãnh đạo, bị Tòa án kết án về tội phạm tham nhũng, bản án đã có hiệu lực pháp luật. Theo Luật Cán bộ, công chức số 80/2025/QH15, ông T bị xử lý như thế nào?",o:['Bị tạm đình chỉ công tác cho xử lý Luôi CBCC 2025 "nÉgng 66',"Bị xem xét kỷ luật cách chức theo trình tự thông thường","Đương nhiên bị buộc thôi việc kể từ ngày bản án có hiệu lực pháp luật","Bị hạ ngạch và chuyển công tác"],c:2},{id:"vb08-185",s:"CHƯƠNG V - KHEN THƯỞỚNG, XỬ LÝ KỶ LUẬT (Phần 1: Khen",cc:"Điểm b khoản 1 Điều 34 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Công chức đã thực hiện đúng thẩm quyền, trình tự, thủ tục, không vụ lợi nhưng vẫn gây thiệt hại vì lý do khách quan thì được xem xét loại trừ, miễn, giảm trách nhiệm. Đây là cơ chế hảo về cán bộ, công chức làm dụng.",mn:"Lạm dụng quy trình, không vụ lợi, thiệt hại khách quan. được loại trừ, miễn, giảm trách nhiệm.",t:"m",q:"Một tình huống: Bà H là công chức, đã thực hiện đúng thẩm quyền, trình tự, thủ tục, không vụ lợi nhưng do nguyên nhân khách quan vẫn gây ra một số thiệt hại. Theo Luật Cán bộ, công chức số 80/2025/QH15, trường hợp của bà H được xem xét như thế nào?",o:["Phải chịu trách nhiệm kỷ luật như mọi trường hợp gây thiệt hại","Được xem xét loại trừ, miễn, giảm trách nhiệm","Bị buộc thôi việc do gây thiệt hại","Phải bồi thường toàn bộ thiệt hại đã gây ra"],c:1},{id:"vb08-186",s:"CHƯƠNG V - KHEN THƯỞỚNG, XỬ LÝ KỶ LUẬT (Phần 1: Khen",cc:"Điểm d khoản 1 Điều 35 Luật Cán bộ, công chức số 80/2025/QH15,",gt:"Đối với cán bộ (đặc biệt là cán bộ do bầu cử), hình thức kỷ luật cao nhất là bãi nhiệm. Công chức mới có hình thức 'buộc thôi việc.",mn:"Cán bộ: hình thức cao nhất là bãi nhiệm.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, hình thức kỷ luật áp dụng với cán bộ được bầu cử giữ chức vụ theo nhiệm kỳ khi vi phạm đến mức cao nhất là [........ L",o:["buộc thôi việc","giáng chức","cách chức","bãi nhiệm"],c:3},{id:"vb08-187",s:"CHƯƠNG V - KHEN THƯỞỚNG, XỬ LÝ KỶ LUẬT (Phần 1: Khen",cc:"Điều 35 và Điều 36 Luật Cán bộ, công chức số 80/2025/QH15. Lưới t BCtC 2095 gi 67",gt:"Bá hình thức khiển trách, cảnh cáo, cách chức áp dụng cho cá cán bộ và công chức. Riêng cán bộ có thêm bãi nhiệm, công chức có thêm buộc thôi việc.",mn:"Chung cả hai: khiển trách — cảnh cáo - cách chức. Riêng: bãi nhiệm (cán bộ) / buộc thôi việc (công chức).",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, các hình thức kỷ luật nào sau đây cùng áp dụng cho cá cán bộ và công chức?",o:["Khiển trách, cảnh cáo, buộc thôi việc","Khiển trách, cảnh cáo, bãi nhiệm","Khiển trách, cảnh cáo, cách chức","Cảnh cáo, bãi nhiệm, buộc thôi việc"],c:2},{id:"vb08-188",s:"CHƯƠNG V - KHEN THƯỞỚNG, XỬ LÝ KỶ LUẬT (Phần 1: Khen",cc:"Điều 35 và Điều 36 Luật Cán bộ, công chức số 90/2025/QH15.",gt:"Hình thức cách chức chỉ áp dụng với người đang giữ chức vụ (công chức lãnh đạo, quản lý). Công chức không giữ chức vụ lãnh đạo, quản lý thì không thể bị cách chức. Vì vậy phương án D sai.",mn:"Không giữ chức vụ thì không thể bị cách chức.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, nhận định nào sau đây về hình thức kỷ luật cán bộ, công chức là KHÔNG đúng?",o:["Công chức không giữ chức vụ lãnh đạo, quản lý văn có thể bị cách chức","Công chức có thể bị khiển trách, cảnh cáo, cách chức, buộc thôi việc","Cách chức đối với công chức chỉ áp dụng với công chức lãnh đạo, quản lý","Cán bộ có thể bị khiển trách, cảnh cáo, cách chức, bãi nhiệm"],c:0},{id:"vb08-189",s:"CHƯƠNG V - KHEN THƯỞỚNG, XỬ LÝ KỶ LUẬT (Phần 1: Khen",cc:"Điều 33 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Khen thưởng nhằm ghỉi nhận công trạng, tạo động lực phấn đấu thông qua nâng lương trước thời hạn, tiền thưởng và ưu tiên xem xét bổ nhiệm chức vụ cao hơn (nếu cơ quan có nhu cầu). Khen thưởng gắn với thành tích, không thay thổ đánh giá hằng năm.",mn:"Khen thưởng: ghi nhận công trạng + tạo động lực (nâng lương trước hạn, thưởng, ưu tiên bổ nhiệm).",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, việc khen thưởng cán bộ, công chức có thành tích xuất sắc nhằm mục đích chủ yếu nào sau đây?",o:["Thay thế cho việc đánh giá, xếp loại chất lượng hằng năm","Ghi nhận công trạng, tạo động lực phấn đấu thông qua nâng lương trước thời hạn, tiền thưởng và ưu tiên xem xét bổ nhiệm","Bảo đảm mọi cán bộ, công chức đều được khen thưởng định kỳ","Tăng thu nhập cho cán bộ, công chức không gắn với thành tích"],c:1},{id:"vb08-190",s:"CHƯƠNG V - KHEN THƯỞỚNG, XỬ LÝ KỶ LUẬT (Phần 1: Khen",cc:"Khoản 1 Điều 34 Luật Cán bộ, công chức số 80/2025/QH15.",gt:'Cả ba đều thuộc trường hợp được xem xét loại trừ, miễn, giảm trách nhiệm: chấp hành quyết định trái pháp luật nhưng đã báo cáo; do bất khả kháng: Luôi CBCC 2025 "nÉgng 68 thực hiện đề xuất đổi mới, sáng tạo được cho phép, động cơ trong sáng, vì lợi ích chung.',mn:"Loại trừ trách nhiệm: đã báo cáo - bất khả kháng - đổi mới được cho phép.",t:"m",q:"Theo Luật Cán bộ, công chức số 90/2025/QH15, các trường hợp sau có cùng thuộc trường hợp được xem xét loại trừ, miễn, giảm trách nhiệm hay không: (i) chấp hành quyết định trái pháp luật của cấp trên nhưng đã báo cáo; (ii) do bất khả kháng; (1ii) thực hiện đề xuất đổi mới, sáng tạo được cho phép, vì lợi ích chung?",o:["Cả ba trường hợp đều được xem xét loại trừ, miễn, giảm trách nhiệm","Chỉ trường hợp (i) và (ii) đúng","Chỉ trường hợp (i) đúng","Không trường hợp nào đúng"],c:0},{id:"vb08-191",s:"CHƯƠNG V - KHEN THƯỞỚNG, XỬ LÝ KỶ LUẬT (Phần 1: Khen",cc:"Khoản 3 Điều 35 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Việc áp dụng hình thức kỷ luật, thẩm quyền, trình tự, thủ tục xử lý kỷ luật cán bộ thực hiện theo pháp luật, điều lệ của Đảng, Mặt trận Tổ quốc Việt Nam, tổ chức chính trị - xã hội và văn bản của cơ quan, tổ chức có thẩm quyền.",mn:"Kỷ luật cán bộ: theo pháp luật + điều lệ Đảng, MTTQ, tổ chức CT-XH - văn bản cơ quan có thẩm quyền.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, việc áp dụng các hình thức kỷ luật, thẩm quyền, trình tự, thủ tục xử lý kỷ luật cán bộ được thực hiện theo quy định nào?",o:["Theo quy chế nội bộ của từng cơ quan, tổ chức","Chỉ theo quy định của Chính phủ","Chỉ theo quyết định của người đứng đầu cơ quan","Theo quy định của pháp luật, điều lệ của Đảng Cộng sản Việt Nam, Mặt trận Tổ quốc Việt Nam, tổ chức chính trị - xã hội và văn bản của cơ quan, tổ chức có thẩm quyền"],c:3},{id:"vb08-192",s:"CHƯƠNG V - KHEN THƯỞỚNG, XỬ LÝ KỶ LUẬT (Phần 1: Khen",cc:"Các điều 33, 34, 35, 36 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Tổng hợp: cán bộ, công chức có thành tích được khen thưởng; được xem xét loại trừ, miễn, giảm trách nhiệm khi lạm dụng quy trình, đổi mới sáng tạo vì lợi ích chung; khi vi phạm bị kỷ luật theo hình thức tương ứng (cán bộ có bãi nhiệm, công chức có buộc thôi việc).",mn:"Khen thưởng - bảo vệ (loại trừ trách nhiệm) — kỷ luật (cán bộ: bãi nhiệm; công chức: buộc thôi việc). Lưới t BCtC 2095 gi 69 hiệu, thời hạn; các quy định khác; tạm đình chỉ công tác) Phạm vi phân 2: Điều 37 đến Điều 39 — thời hiệu, thời hạn xử lý kỷ luật và các trường hợp không áp dụng thời hiệu: các quy định khác liên quan đến xử lý kỷ luật; tạm đình chỉ công tác đối với cán bộ, công chiưc.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, phương án nào sau đây phản ánh DỤNG và ĐẦY ĐỦ nhất về khen thưởng và xử lý kỷ luật cán bộ, công chức?",o:["Mọi vi phạm đều bị áp dụng hình thức kỷ luật cao nhất","Cán bộ, công chức chỉ bị xử lý kỷ luật, không có cơ chế khen thưởng hay bảo vệ","Cán bộ, công chức có thành tích được khen thưởng (nâng lương trước hạn, thưởng, ưu tiên bổ nhiệm): được xem xét loại trừ, miễn, giảm trách nhiệm khi lạm dụng quy trình, đổi mới sáng tạo vì lợi ích chung; khi vi phạm thì bị kỷ luật theo các hình thức tương ứng (cán bộ có bãi nhiệm, công chức có buộc thôi việc)","Cán bộ và công chức có hình thức kỷ luật hoàn toàn giống nhau"],c:2},{id:"vb08-193",s:"CHƯƠNG V - KHEN THƯỞNG, XỬ LÝ KỶ LUẬT (Phần 2: Thời",cc:"Khoản 1 Điều 37 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Thời hiệu xử lý kỷ luật là thời hạn mà khi hết thời hạn đó thì người vi phạm không bị xử lý kỷ luật; được tính từ thời điểm có hành vi vi phạm. Cần phân biệt với thời hạn xử lý kỷ luật' (từ khi phát hiện đến khi có quyết định).",mn:"Thời hiệu: hết thì không bị xử lý; tính từ thời điểm có hành vi vi phạm.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, 'thời hiệu xử lý kỷ luật được hiểu là gì và được tính từ thời điểm nào?",o:["Là thời gian tạm đình chỉ công tác để xác minh vi phạm","Là khoảng thời gian từ khi phát hiện vi phạm đến khi có quyết định kỷ luật","Là thời hạn cán bộ, công chức phải chấp hành quyết định kỷ luật","Là thời hạn mà khi hết thời hạn đó thì cán bộ, công chức có hành vi vi phạm không bị xử lý kỷ luật; được tính từ thời điểm có hành vi vi phạm"],c:3},{id:"vb08-194",s:"CHƯƠNG V - KHEN THƯỞNG, XỬ LÝ KỶ LUẬT (Phần 2: Thời",cc:"#)iem a khoản 1 Điều 37 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Thời hiệu xử lý kỷ luật là 05 năm đối với hành vi vi phạm đến mức phải kỷ luật bằng hình thức khiển trách.",mn:"Thời hiệu khiển trách: 05 năm.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, thời hiệu xử lý kỷ luật đối với hành vi vi phạm đến mức phải kỷ luật bằng hình thức khiển trách là [......... l.",o:["02 năm","05 năm","10 năm","12 tháng"],c:1},{id:"vb08-195",s:"CHƯƠNG V - KHEN THƯỞNG, XỬ LÝ KỶ LUẬT (Phần 2: Thời",cc:"Điểm b khoản 1 Điều 37 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Thời hiệu xử lý kỷ luật là 10 năm đối với hành vi vi phạm không thuộc trường hợp phải kỷ luật bằng hình thức khiển trách (tức các vi phạm nặng hơn).",mn:"Thời hiệu: 05 năm (khiển trách) / 10 năm (các trường hợp còn lại). — ',: „Z0. ¡hạn 70 Luút C BC",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, thời hiệu xử lý kỷ luật đối với hành vi vi phạm không thuộc trường hợp phải kỷ luật bằng hình thức khiển trách là bao nhiêu?",o:["07 năm","05 năm","10năm","15năm"],c:2},{id:"vb08-196",s:"CHƯƠNG V - KHEN THƯỞNG, XỬ LÝ KỶ LUẬT (Phần 2: Thời",cc:"Khoản 2 Điều 37 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Các hành vi không áp dụng thời hiệu xử lý kỷ luật: đảng viên vi phạm đến mức phải khai trừ; vi phạm về công tác bảo vệ chính trị nội bộ; xâm hại lợi ích quốc gia về quốc phòng, an ninh, đối ngoại; sử dụng văn bằng, chứng chỉ, giấy chứng nhận, xác nhận giả hoặc không hợp pháp.",mn:"Không thời hiệu: khai trừ đảng — bảo vệ chính trị nội bộ - xâm hại QP, AN, đối ngoại - văn bằng giả.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, hành vi vi phạm nào sau đây KHÔNG áp dụng thời hiệu xử lý kỷ luật?",o:["Cán bộ, công chức là đảng viên có hành vi vi phạm đến mức phải kỷ luật bằng hình thức khai trừ; vi phạm về công tác bảo vệ chính trị nội bộ: xâm hại lợi ích quốc gia trong lĩnh vực quốc phòng, an ninh, đối ngoại; sử dụng văn bằng, chứng chỉ, giấy chứng nhận, xác nhận giả hoặc không hợp pháp","Hành vi vi phạm đến mức phải kỷ luật bằng hình thức khiển trách","Hành vi vi phạm lần đầu, chưa gây hậu quả nghiêm trọng","Hành vi vi phạm về chế độ làm việc, giờ giấc"],c:0},{id:"vb08-197",s:"CHƯƠNG V - KHEN THƯỞNG, XỬ LÝ KỶ LUẬT (Phần 2: Thời",cc:"Khoản 3 Điều 37 Luật Cán bộ, công chức số 80/2025/QH15.",gt:`Thời hạn xử lý kỷ luật là khoảng thời gian từ khi phát hiện hành vi vi phạm đến khi có quyết định xử lý kỷ luật. Khác với "thời hiệu' (tính từ thời điểm có hành vi vi nhạm, hết thì không xử lý).`,mn:"Thời hạn: từ khi phát hiện đến khi có quyết định xử lý.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, 'thời hạn xử lý kỷ luật' đối với cán bộ, công chức được hiểu là gì?",o:["Là thời gian được tính từ thời điểm có hành vi vi phạm","Là thời hạn mà khi hết thì người vi phạm không bị xử lý kỷ luật","Là thời gian cán bộ, công chức phải chấp hành quyết định kỷ luật","Là khoảng thời gian từ khi phát hiện hành vi vi phạm kỷ luật đến khi có quyết định xử lý kỷ luật của cơ quan, tổ chức có thẩm quyền"],c:3},{id:"vb08-198",s:"CHƯƠNG V - KHEN THƯỞNG, XỬ LÝ KỶ LUẬT (Phần 2: Thời",cc:"Khoản 3 Điều 37 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Thời hạn xử lý kỷ luật không quá 90 ngày; trường hợp có tình tiết phức tạp cần thanh tra, kiểm tra để xác minh làm rõ thêm thì có thể kéo dài nhưng không quá 150 ngày.",mn:"Thời hạn kỷ luật: 90 ngày; phức tạp tối đa 150 ngày. Lưới t BCtC 2095 gi 71",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, thời hạn xử lý kỷ luật cán bộ, công chức là bao nhiêu, và có thể kéo dài đến mức nào đối với vụ việc phức tạp?",o:["Không quá 60 ngày; phức tạp không quá 90 ngày","Không quá 90 ngày; trường hợp có tình tiết phức tạp cần thanh tra, kiểm tra để xác minh thì có thể kéo dài nhưng không quá 150 ngày","Không quá 30 ngày; phức tạp không quá 60 ngày","Không quá 120 ngày; phức tạp không quá 180 ngày"],c:1},{id:"vb08-199",s:"CHƯƠNG V - KHEN THƯỞNG, XỬ LÝ KỶ LUẬT (Phần 2: Thời",cc:"Khoản 4 Điều 37 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Trường hợp đã bị khởi tố, truy tố, xét xử nhưng sau đó đình chỉ điều tra/đình chỉ vụ án mà hành vi có dấu hiệu vi phạm kỷ luật thì bị xem xét xử lý kỷ luật; thời gian điều tra, truy tố, xét xử không tính vào thời hiệu xử lý kỷ luật.",mn:"Đình chỉ vụ án nhưng có dấu hiệu vi phạm ¬ vẫn xem xét kỷ luật; thời gian tố tụng không tính vào thời hiệu.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, đối với trường hợp cá nhân đã bị khởi tố, truy tố hoặc đã có quyết định đưa ra xét xử nhưng sau đó có quyết định đình chỉ điều tra hoặc đình chỉ vụ án mà hành vi có dấu hiệu vi phạm kỷ luật thì được xử lý như thế nào?",o:["Bị xem xét xử lý kỷ luật; thời gian điều tra, truy tố, xét xử theo thủ tục tố tụng hình sự không tính vào thời hiệu xử lý kỷ luật","Không bị xem xét kỷ luật vị đã được đình chỉ","Đương nhiên bị buộc thôi việc","Chỉ bị nhắc nhở, rút kinh nghiệm"],c:0},{id:"vb08-200",s:"CHƯƠNG V - KHEN THƯỞNG, XỬ LÝ KỶ LUẬT (Phần 2: Thời",cc:"Khoản 2 Điều 38 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Cán bộ, công chức đang trong thời hạn xử lý kỷ luật, đang bị điều tra, truy tố, xét xử thì không được ứng cử, đề cử, bổ nhiệm, điều động, luân chuyển, biệt phái, đào tạo, bồi dưỡng theo quy định.",mn:"Đang xử lý kỷ luậvđiều tra: không ứng cử, bổ nhiệm, điều động, luân chuyển, biệt phái, đào tạo.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, cán bộ, công chức đang trong thời hạn xử lý kỷ luật, đang bị điều tra, truy tố, xét xử thì KHÔNG được thực hiện những việc nào sau đây?",o:["Không được nghỉ phép hằng năm","Không được hưởng lương và các chế độ, chính sách","Không được ứng cử, đề cử, bổ nhiệm, điều động, luân chuyển, biệt phái, đào tạo, bồi dưỡng theo quy định","Không được tham gia các hoạt động của cơ quan"],c:2},{id:"vb08-201",s:"CHƯƠNG V - KHEN THƯỞNG, XỬ LÝ KỶ LUẬT (Phần 2: Thời",cc:"Khoản 3 Điều 38 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Cán bộ, công chức bị kỷ luật cách chức do tham nhũng thì không được bổ nhiệm vào vị trí lãnh đạo, quản lý - chế tài nghiêm khác nhằm phòng, chống tham nhũng.",mn:'Cách chức do tham nhũng ¬ không được bố nhiệm lãnh đạo, quản lý. Luôi CBCC 2025 "nÉgg 72',t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, cán bộ, công chức bị kỷ luật cách chức do tham nhũng thì bị hạn chế quyền nào sau đây?",o:["Không được hưởng lương trong thời gian còn lại","Không được bố nhiệm vào vị trí lãnh đạo, quản lý","Không được tham gia thì nâng ngạch","Không được nghỉ hưu đúng tuổi"],c:1},{id:"vb08-202",s:"CHƯƠNG V - KHEN THƯỞNG, XỬ LÝ KỶ LUẬT (Phần 2: Thời",cc:"Khoản 4 Pieu 38 Luật Cán bộ, công chức số 80/2025/0(0H 15.",gt:"Trường hợp bị xử lý kỷ luật về hành vi không liên quan đến hoạt động công vụ thì không tính là căn cứ để xếp loại chất lượng trong năm đánh giá — tách bạch giữa vi phạm ngoài công vụ và kết quả thực thi công vụ.",mn:"Vi phạm ngoài công vụ ¬ không tính vào xếp loại chất lượng.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, trường hợp cán bộ, công chức bị xử lý kỷ luật về hành vi không liên quan đến hoạt động công vụ thì kết quả đó được xử lý như thế nào trong đánh giá?",o:["Không ảnh hưởng và vẫn được xếp loại hoàn thành xuất sắc","Đương nhiên bị xếp loại không hoàn thành nhiệm vụ","Bị hạ một mức xếp loại chất lượng","Không tính là căn cứ để xếp loại chất lượng trong năm đánh giá"],c:3},{id:"vb08-203",s:"CHƯƠNG V - KHEN THƯỞNG, XỬ LÝ KỶ LUẬT (Phần 2: Thời",cc:"Điều 39 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Người đứng đầu cơ quan, tổ chức có thẩm quyền có thể quyết định tạm đình chỉ công tác đối với cán bộ, công chức khi phát hiện có dấu hiệu vi phạm trong thi hành nhiệm vụ hoặc theo đề nghị của cơ quan, tổ chức có thẩm quyền.",mn:"Tạm đình chỉ công tác: do người đứng đầu quyết định.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, ai cú thẩm quyền quyết định tạm đình chỉ công tác đối với cán bộ, công chức?",o:["Người đứng đầu cơ quan, tổ chức có thẩm quyền","Chỉ Chính phủ và Thủ tướng Chính phủ","Cơ quan thanh tra nhà nước","Tập thể cán bộ, công chức trong cơ quan"],c:0},{id:"vb08-204",s:"CHƯƠNG V - KHEN THƯỞNG, XỬ LÝ KỶ LUẬT (Phần 2: Thời",cc:"Điều 39 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Tạm đình chỉ công tác được thực hiện khi phát hiện cán bộ, công chức có dấu hiệu vi phạm trong thi hành nhiệm vụ hoặc theo đề nghị của cơ quan, tổ chức có thẩm quyền.",mn:"Tạm đình chỉ: khi có dấu hiệu vi phạm trong thi hành nhiệm vụ.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, việc tạm đình chỉ công tác đối với cán bộ, công chức được thực hiện trong trường hợp nào?",o:["Khi cán bộ, công chức có đơn xin nghỉ việc","Khi cán bộ, công chức không hoàn thành nhiệm vụ trong năm","Khi phát hiện cán bộ, công chức có dấu hiệu vi phạm trong thi hành nhiệm vụ hoặc theo đề nghị của cơ quan, tổ chức có thẩm quyền","Khi cán bộ, công chức đến tuổi nghỉ hưu"],c:2},{id:"vb08-205",s:"CHƯƠNG V - KHEN THƯỞNG, XỬ LÝ KỶ LUẬT (Phần 2: Thời",cc:"Điểm a khoản 1 Điều 37 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Thời hiệu xử lý kỷ luật đối với hành vi ở mức khiển trách là 05 năm, tính từ thời điểm có hành vi vi phạm. Đã qua 06 năm nên hết thời hiệu, ông K không bị xử lý kỷ luật (uừ khi thuộc các trường hợp không áp dụng thời hiệu).",mn:"Quá 5 năm với hành vi mức khiển trách ¬ hết thời hiệu, không xử lý.",t:"m",q:"Một tình huống: Ông K là công chức, có hành vi vi phạm đến mức phải kỷ luật khiển trách. Tính từ thời điểm có hành vi vi phạm, đã qua 06 năm cơ quan mới phát hiện. Theo Luật Cán bộ, công chức số 80/2025/QH15, ông K có bị xử lý kỷ luật không?",o:['Không bị xử lý kỷ luật, vì đã hết thời hiệu 05 năm đối với hành vi vi phạm ở mức khiển trách Luôi CBCC 2025 "nÉgg 73',"Vẫn bị xử lý kỷ luật khiển trách bình thường","Bị xử lý kỷ luật ở mức cao hơn do đề lâu","Bị buộc thôi việc do vi phạm kéo dài"],c:0},{id:"vb08-206",s:"CHƯƠNG V - KHEN THƯỞNG, XỬ LÝ KỶ LUẬT (Phần 2: Thời",cc:"Điểm d khoản 2 Điều 37 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Hành vi sử dụng văn bằng, chứng chỉ, giấy chứng nhận, xác nhận giả hoặc không hợp pháp thuộc trường hợp không áp dụng thời hiệu xử lý kỷ luật. Do đó việc xử lý bà M không bị giới hạn bởi thời hiệu.",mn:"Văn bằng giả. không áp dụng thời hiệu (xử lý bắt kể thời gian).",t:"m",q:"Một tình huống: Bà M là công chức, bị phát hiện sử dụng văn bằng không hợp pháp từ nhiều năm trước. Theo Luật Cán bộ, công chức số 80/2025/QH15, việc xử lý kỷ luật đối với bà M có bí giới hạn bởi thời hiệu không?",o:["Bị giới hạn bởi thời hiệu 05 năm","Không bị giới hạn bởi thời hiệu, vì sử dụng văn bằng, chứng chỉ gia hoặc không hợp pháp thuộc trường hợp không áp dụng thời hiệu xử lý kỷ luật","Bị giới hạn bởi thời hiệu 10 năm","Không bị xử lý vị hành vi đã xảy ra quá lầu"],c:1},{id:"vb08-207",s:"CHƯƠNG V - KHEN THƯỞNG, XỬ LÝ KỶ LUẬT (Phần 2: Thời",cc:"Điều 37 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Có bốn nhóm hành vi không áp dụng thời hiệu xử lý kỷ luật (khai trừ đảng, bảo vệ chính trị nội bộ, xâm hại lợi ích quốc gia về quốc phòng, an ninh, đối ngoại, văn bằng giả). Vì vậy mọi hành vi đều áp dụng thời hiệu' là sai. A, B, C đều đúng.",mn:"Có 4 trường hợp KHÔNG áp dụng thời hiệu.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, nhận định nào sau đây về thời hiệu, thời hạn xử lý kỷ luật là KHÔNG đúng?",o:["Thời hiệu xử lý kỷ luật đối với hành vi ở mức khiển trách là 05 năm","Thời hiệu xử lý kỷ luật đối với hành vi không ở mức khiển trách là 10 năm","Mọi hành vi vi phạm đều áp dụng thời hiệu xử lý kỷ luật","Thời hạn xử lý kỷ luật không quá 90 ngày, phức tạp không quá 150 ngày"],c:2},{id:"vb08-208",s:"CHƯƠNG V - KHEN THƯỞNG, XỬ LÝ KỶ LUẬT (Phần 2: Thời",cc:"Điều 37 và Điều 38 Luật Còn bộ, công chức số 80/2025/QH15,",gt:"Tổng hợp: thời hiệu 05 năm (khiển trách) / 10 năm (khác) tính từ thời điểm vi phạm, trừ các hành vi không áp dụng thời hiệu; thời hạn xử lý không quá 90 ngày (phức tạp 150 ngày); người đang bị xử lý kỷ luật, điều tra không được bố nhiệm, điều động, đào tạo; cách chức do tham nhũng thì không được bổ nhiệm lãnh đạo, quản lý.",mn:"Thời hiệu 5/10 năm ~- thời hạn 90/150 ngày - đảng xử lý thì 'động bằng' bổ nhiệm — tham nhũng không lên lãnh đạo. Lưới t BCtC 2095 gi 75",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, phương án nào sau đây phản ánh ĐÚNG và ĐẦY ĐỦ nhất về thời hiệu, thời hạn và hệ quả liên quan đến xử lý kỷ luật?",o:["Người đang bị xử lý kỷ luật vẫn được bố nhiệm, điều động bình thường","Mọi hành vi vi phạm đều có thời hiệu 05 năm và thời hạn xử lý 30 ngày","Không có quy định về thời hiệu, thời hạn xử lý kỷ luật","Thời hiệu là 05 năm (khiển trách) hoặc 10 năm (trường hợp khác), tính từ thời điểm có hành vi vi phạm, trừ một số hành vi không áp dụng thời hiệu; thời hạn xử lý Lưới t BCtC 2095 gi 74 không quá 90 ngày (phức tạp 150 ngày); người đang bị xử lý kỷ luật, điều tra không được bổ nhiệm, điều động, đào tạo; cách chức do tham nhũng thì không được bổ nhiệm lãnh đạo, quản lý"],c:3},{id:"vb08-209",s:"CHƯƠNG VI - QUẢN LÝ CÁN BỘ, CÔNG CHỨC",cc:"Điều 409 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Nội dung quản lý cán bộ, công chức rất rộng, gồm: ban hành, tổ chức thực hiện văn bản quy phạm pháp luật; quy định chức vụ, chức danh, xây dựng, quản lý vị trí việc làm; quản lý biên chế; tuyển dụng, quy hoạch, bổ nhiệm, điều động, luân chuyển...: sử dụng, đánh giá, đào tạo, khen thưởng, kỷ luật; thanh tra, kiểm tra, giải quyết khiếu nại, tố cáo; ứng dụng công nghệ và phân cấp, ủy quyền.",mn:"Quản lý CBCC: ban hành VBQPPL - VIVL, biên chế - tuyển dụng, bổ nhiệm - đánh giá, đào tạo, kỷ luật — thanh tra, KNTC.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, nội dung quản lý cán bộ, công chức bao gồm những hoạt động nào sau đây?",o:["Ban hành, trình ban hành và tổ chức thực hiện văn bản quy phạm pháp luật về cán bộ, công chức; quy định chức vụ, chức danh, xây dựng, quản lý vị trí việc làm; quản lý biên chế; tuyển dụng, quy hoạch, bổ nhiệm, điều động: sử dụng, đánh giá, đào tạo, khen thưởng, kỷ luật; thanh tra, kiểm tra, giải quyết khiếu nại, tố cáo","Chỉ gồm việc tuyển dụng và bố nhiệm cán bộ, công chức","Chỉ gồm việc trả lương và thực hiện chế độ, chính sách","Chỉ gồm việc đánh giá, xếp loại chất lượng hằng năm"],c:0},{id:"vb08-210",s:"CHƯƠNG VI - QUẢN LÝ CÁN BỘ, CÔNG CHỨC",cc:"Khoản 8 Điều 40 Luật Cán bộ, công chức số 80/2025/QH 5S.",gt:"Nội dung mới: ứng dụng khoa học, công nghệ, chuyển đổi số trong quản lý cán bộ, công chức; xây dựng, quản lý, khai thác cơ sở dữ liệu quốc gia về cán bộ, công chức - hiện đại hóa công tác quản lý.",mn:"Quản lý CBCC mới: chuyển đổi số + cơ sở dữ liệu quốc gia về CBCC.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, một nội dung mới trong quản lý cán bộ, công chức gắn với hiện đại hóa nền công vụ là gì?",o:["Tăng số lượng biên chế cho các cơ quan, tổ chức","Thực hiện ứng dụng khoa học, công nghệ, chuyển đổi số trong quản lý cán bộ, công chức; xây dựng, quản lý, khai thác cơ sở dữ liệu quốc gia về cán bộ, công chức","Quản lý cán bộ, công chức theo thâm niên công tác","Bổ nhiệm cán bộ, công chức theo nhiệm kỳ 05 năm"],c:1},{id:"vb08-211",s:"CHƯƠNG VI - QUẢN LÝ CÁN BỘ, CÔNG CHỨC",cc:'Khoản 2 Điều 41 Luật Cán bộ, công chức số 80/2025/QH15. Luôi CBCC 2025 "nÉgg 70',gt:"Chính phủ thống nhất quản lý nhà nước về công chức và thực hiện quản lý cán bộ, công chức trong các cơ quan nhà nước.",mn:"Thống nhất QLNN về công chức: Chính phủ.",t:"m",q:"Theo Luật Cán bộ, công chức số 90/2025/QH15, cơ quan nào thống nhất quản lý nhà nước về công chức và thực hiện quản lý cán bộ, công chức trong các cơ quan nhà nước?",o:["Bộ Nội vụ","Quốc hội","Chính phủ","Ủy ban Thường vụ Quốc hội"],c:2},{id:"vb08-212",s:"CHƯƠNG VI - QUẢN LÝ CÁN BỘ, CÔNG CHỨC",cc:"Khoản 1 Điều 42 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Hồ sơ cán bộ, công chức gồm hồ sơ giấy và hồ sơ điện tử, được quản lý uên hệ thống thông tin và phê duyệt, cập nhật vào cơ sở dữ liệu quốc gia về cán bộ, công chức - điểm mới gắn với chuyển đổi số.",mn:"Hồ sơ CBCC: giấy + điện tử, đồng bộ với cơ sở dữ liệu quốc gia.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, hồ sơ cán bộ, công chức bao gồm những loại nào?",o:["Hồ sơ giấy lưu tại cơ quan và hồ sơ điện tử do cá nhân tự quản lý","Chỉ gồm hồ sơ giấy được lưu trữ tại cơ quan","Chỉ gồm hồ sơ điện tử trên hệ thống thông tin","Hồ sơ giấy và hồ sơ điện tử, được quản lý trên hệ thống thông tin và được phê duyệt, cập nhật vào cơ sở dữ liệu quốc gia về cán bộ, công chức"],c:3},{id:"vb08-213",s:"CHƯƠNG VI - QUẢN LÝ CÁN BỘ, CÔNG CHỨC",cc:"Khoản 2 Điều 42 Luật Cán bộ, công chức số 60/2025/QH15.",gt:"Cán bộ, công chức có trách nhiệm bố sung thông tin cá nhân theo quy định khi có thay đổi: cơ quan có thẩm quyền phê duyệt, cập nhật vào hồ sơ và đồng bộ với cơ sở dứt liệu quốc gia về cán bộ, công chức.",mn:"CBCC: bổ sung thông tin khi có thay đổi; cơ quan cập nhật, đồng bộ CSDL quốc gia.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, trách nhiệm của cán bộ, công chức đối với hồ sơ của mình được quy định như thế nào?",o:["Chỉ cần khai báo thông tin một lần khi được tuyển dụng","Tự quản lý toàn bộ hồ sơ giấy và hồ sơ điện tử của mình","Không có trách nhiệm øì đối với hồ sơ, do cơ quan quản lý hoàn toàn","Có trách nhiệm bổ sung thông tin cá nhân theo quy định khi có thay đổi; cơ quan có thẩm quyền phê duyệt, cập nhật vào hồ sơ và đồng bộ với cơ sở dữ liệu quốc gia"],c:3},{id:"vb08-214",s:"CHƯƠNG VI - QUẢN LÝ CÁN BỘ, CÔNG CHỨC",cc:"Khoản 1 Điều 41 Luật Cán bộ, công chức số 80/2025/QH15.",gt:'Việc quản lý cán bộ, công chức thực hiện theo Luật này, các quy định khác của pháp luật có liên quan, điều lệ của Đảng, Mặt trận Tổ quốc Việt Nam, tổ chức chính trị - xã hội và văn bản của cơ quan, tổ chức có thẩm quyền ~- thể hiện tính thống nhất, liên thông trong hệ thống chính trị. Luôi CBCC 2025 "rang 77',mn:"Quản lý CBCC: theo Luật + pháp luật liên quan + điều lệ Đảng, MTTQ, tổ chức CT-XH.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, việc quản lý cán bộ, công chức được thực hiện theo các căn cứ nào sau đây?",o:["Chỉ theo quy định của (thính phủ","Chỉ theo quy định của Luật Cán bộ, công chức","Theo quy định của Luật này, các quy định khác của pháp luật có liên quan, điều lệ của Đảng Cộng sản Việt Nam, Mặt trận Tổ quốc Việt Nam, tổ chức chính trị - xã hội và văn bản của cơ quan, tổ chức có thẩm quyền","Theo quy chế nội bộ của từng cơ quan, tổ chức, đơn vị"],c:2},{id:"vb08-215",s:"CHƯƠNG VI - QUẢN LÝ CÁN BỘ, CÔNG CHỨC",cc:"Khoản 5 Điều 41 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Cơ quan sử dụng cán bộ, công chức thực hiện thẩm quyền theo Luật này và các thẩm quyền khác theo phân cấp, ủy quyền của cơ quan quản lý cán bộ, công chức.",mn:"Cơ quan sử dụng: thực hiện thẩm quyền theo phân cấp, ủy quyền của cơ quan quản lý.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, cơ quan sử dụng cán bộ, công chức thực hiện thẩm quyền quản lý trên cơ sở nào?",o:["Tự quyết định mới nội dung quản lý không cần phân cấp","Thực hiện thẩm quyền quy định tại Luật này và các thẩm quyền khác theo phân cấp, ủy quyền của cơ quan quản lý cán bộ, công chức","Chỉ thực hiện theo chỉ đạo trực tiếp của Chính phủ","Thực hiện toàn bộ thẩm quyền như cơ quan quản lý cán bộ, công chức"],c:1},{id:"vb08-216",s:"CHƯƠNG VI - QUẢN LÝ CÁN BỘ, CÔNG CHỨC",cc:"Điều 40 Luật Cán bộ, công chức số 80/2025/C)H15.",gt:"Cả ba đều thuộc nội dung quản lý cán bộ, công chức: quản lý, sử dụng biên chế; thanh tra, kiểm tra hoạt động công vụ và giải quyết khiếu nại, tố cáo; phân cấp, ủy quyền thực hiện các nội dung quản lý.",mn:"Quản lý CBCC gồm cả: biên chế — thanh tra, KNTC - phân cấp, ủy quyền.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, các nội dung sau có cùng thuộc nội dung quản lý cán hộ, công chức hay không: (1) quản lý, sử dụng biên chế; (ii) thanh tra, kiểm tra hoạt động công vụ và giải quyết khiếu nại, tố cáo; (iii) phân cấp, ủy quyền thực hiện các nội dung quản lý?",o:["Cả ba nội dung đều thuộc nội dung quản lý cán bộ, công chức","Chỉ nội dung (i) và (ii) đúng","Chỉ nội dung (i) đúng","Không nội dung nào đúng"],c:0},{id:"vb08-217",s:"CHƯƠNG VI - QUẢN LÝ CÁN BỘ, CÔNG CHỨC",cc:"Khoản 1 Điều 42 Luật Cìản bộ, công chức số 80/2025/00H15.",gt:"Hồ sơ cán bộ, công chức phải có đầy đủ thành phần theo quy định, bảo đảm chính xác diễn biến, quá trình công tác và được lưu trữ theo quy định của pháp luật.",mn:"Hồ sơ: đầy đủ thành phần — chính xác quá trình công tác — lưu trữ đúng quy định. Lưới t BCtC 2095 gi 78",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, hồ sơ cán bộ, công chức phải bảo đảm yêu cầu nào sau đây?",o:["Có đầy đủ thành phần theo quy định, bảo đảm chính xác diễn biến, quá trình công tác của cán bộ, công chức và được lưu trữ theo quy định của pháp luật","Chỉ cần có sơ yếu lý lịch và bằng cấp","Do cá nhân cán bộ, công chức từ lập và tự lưu giữ","Chỉ lưu trữ dưới dạng điện tử, không cần hồ sơ giấy"],c:0},{id:"vb08-218",s:"CHƯƠNG VI - QUẢN LÝ CÁN BỘ, CÔNG CHỨC",cc:"Khoản 3 Điều 41 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Các cơ quan này trong phạm vi chức năng, nhiệm vụ của mình thực hiện quản lý cán bộ, công chức theo phân cấp của cơ quan có thẩm quyền và theo quy định của Chính phủ - bảo đảm tính thống nhất, liên thông.",mn:"UBTVQH, Đảng, MTTQ, tổ chức CT-XH: quản lý CBCC theo phân cấp và quy định Chính phủ.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, Ủy ban Thường vụ Quốc hội, cơ quan có thẩm quyền của Đảng, Mặt trận Tổ quốc Việt Nam, các tổ chức chính trị - xã hội thực hiện quản lý cán bộ, công chức như thế nào?",o:["Thực hiện toàn bộ việc quản lý cán bộ, công chức trong cả nước","Trong phạm vi chức năng, nhiệm vụ của mình, thực hiện việc quản lý cán bộ, công chức theo phân cấp của cơ quan có thẩm quyền và theo quy định của Chính phủ","Không tham gia quản lý cán bộ, công chức","Chỉ quản lý cán bộ, không quản lý công chức"],c:1},{id:"vb08-219",s:"CHƯƠNG VI - QUẢN LÝ CÁN BỘ, CÔNG CHỨC",cc:"Điều 40, Điều 41, Điều 42 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Cơ quan sử dụng cán bộ, công chức thực hiện thẩm quyền theo phân Cấp, ủy quyền của cơ quan quản lý cán bộ, công chức, không 'tự quyết định toàn hộ mà không cần phân cấp, ủy quyền'. Vì vậy phương án D sai.",mn:"Cơ quan sử dụng hoạt động theo phân cấp, ủy quyền, không tự quyết toàn bộ.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, nhận định nào sau đây về quản lý cán bộ, công chức là KHÔNG đúng?",o:["Chính phủ thống nhất quản lý nhà nước về công chức","Nội dung quản lý gồm tuyển dụng, sử dụng, đánh giá, đào tạo, khen thưởng, kỷ luật","Hồ sơ cán bộ, công chức gồm hồ sơ giấy và hồ sơ điện tử, đồng bộ với cơ sở dữ liệu quốc gia","Mới cơ quan sử dụng cán bộ, công chức tự quyết định toàn bộ nội dung quản lý mà không cần phân cấp, ủy quyền"],c:3},{id:"vb08-220",s:"CHƯƠNG VI - QUẢN LÝ CÁN BỘ, CÔNG CHỨC",cc:"Cúc điều 40, 41, 42 Luật Cán bộ, công chức số 80/2025/QH15.",gt:'Quản lý cán bộ, công chức là hoạt động toàn diện (thể chế, vị trí việc làm, biên chế, tuyển dụng, sử dụng, đánh giá, đào tạo, khen thưởng, kỷ luật, thanh tra, Luôi CBCC 2025 "nÉgg 79 kiểm tra); Chính phủ thống nhất quản lý nhà nước về công chức; thực hiện phân cấp, ủy quyền và ứng dụng chuyển đổi số, cơ sở dữ liệu quốc gia.',mn:"Quản lý CBCC: toàn diện - Chính phủ thống nhất - phân cấp, ủy quyền — chuyển đổi số. Lưới t BCtC 2095 TỪ TỪ 80",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, phương án nào sau đây phản ánh ĐÚNG và ĐẦY ĐỦ nhất về quản lý cán bộ, công chức?",o:["Quản lý cán bộ, công chức do từng cơ quan tự thực hiện độc lập","Quản lý cán bộ, công chức chỉ là việc tuyển dụng và trả lương","Quản lý cán bộ, công chức là hoạt động toàn diện từ ban hành thể chế, quản lý vị trí việc làm, biên chế, tuyển dụng, sử dụng, đánh giá, đào tạo, khen thưởng, kỷ luật đến thanh tra, kiểm tra; do Chính phủ thống nhất quản lý nhà nước về công chức; thực hiện phân cấp, ủy quyền và ứng dụng chuyển đổi số, cơ sở dữ liệu quốc gia","Quản lý cán bộ, công chức không cần ứng dụng công nghệ thông tin"],c:2},{id:"vb08-221",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Điều 44 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Luật có hiệu lực thi hành từ ngày 01/7/2025, trừ quy định về đánh giá công chức tại Mục 3 Chương IV được thực hiện từ ngày 01/01/2026.",mn:"Hiệu lực: 01/7/2025 (đánh giá công chức: 01/01/2026).",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, Luật này có hiệu lực thi hành từ thời điểm nào?",o:["Từ ngày 01 tháng 7 năm 2027","Từ ngày 24 tháng 6 năm 2025","Từ ngày 01 tháng 01 năm 2026","Từ ngày 01 tháng 7 năm 2025, trừ quy định về đánh giá công chức tại Mục 3 Chương IV được thực hiện từ ngày 01 tháng 01 năm 2026"],c:3},{id:"vb08-222",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Khoản 3 Điều 44 Luật Cán bộ, công chức số 60/2025/QH15.",gt:"Luật Cán bộ, công chức số 22/2008/QH12 (đã được sửa đổi, bổ sung theo Iuật số 52/2019/QH14) hết hiệu lực kể từ ngày Luật mới có hiệu lực thi hành (01/7/2025).",mn:"Luật CBCC 2025 thay thế Luật CBCC số 22/2008/QH12 (sđ Luật 52/2019/QH14).",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, văn bản nào hết hiệu lực kể từ ngày Luật này có hiệu lực thi hành?",o:["Luật Cán bộ, công chức số 22/2008/QH12 đã được sửa đổi, bổ sung một số điều theo Luật số 52/2019/QH14","Luật Viên chức năm 2010","Luật Tổ chức chính quyền địa phương","Luật Thi đua, khen thưởng"],c:0},{id:"vb08-223",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Khoản 1 Điều 45 Luật Cán bộ, công chức số 60/2025/QH15.",gt:"Cán bộ, công chức cấp xã được bầu/tuyển dụng trước ngày Luật có hiệu lực, nếu đáp ứng đủ tiêu chuẩn về trình độ đào tạo thì được chuyển thành cán bộ, công chức theo Luật này, bố trí công tác tại cấp xã hình thành sau sắp xếp, thuộc — ',, „Z0. ¡cai 81 Luút C BC biên chế địa phương và thực hiện tinh giản biên chế trong thời hạn 05 năm. Đây là quy định chuyển tiếp gắn với mô hình chính quyền hai cấp.",mn:"CBCC cấp xã đủ tiêu chuẩn: chuyển thành CBCOC, tinh giản biên chế ưung 05 năm.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, cán bộ, công chức cấp xã được bầu hoặc tuyển dụng trước ngày Luật có hiệu lực, nếu đáp ứng đủ tiêu chuẩn về trình độ đào tạo thì được xử lý chuyển tiếp như thế nào?",o:["Đương nhiên bị thôi việc do thay đổi mô hình chính quyền","Được chuyển thành cán bộ, công chức theo quy định của Luật này và được bố trí công tác tại cấp xã hình thành sau sắp xếp, thuộc biên chế của địa phương, thực hiện tinh giản biên chế trong thời hạn 05 năm","Phải thi tuyển lại để trở thành công chức","Được giữ nguyên vị trí và không thuộc diện tinh giản biên chế"],c:1},{id:"vb08-224",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Khoản 2 Điều 45 Luật Cán bộ, công chức số 80/2025/Ql115.",gt:"Chậm nhất đến ngày 01/7/2027, các Bộ, ngành, cơ quan trung ương, địa phương phải huàn thành việc bố trí vào vị trí việc làm và xếp ngạch tương ứng đối với công chức được tuyển dụng trước ngày Luật có hiệu lực.",mn:"Hoàn thành bố trí VTV1, xếp ngạch: chậm nhất 01/7/2027.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, chậm nhất đến thời điểm nào các Bộ, ngành, địa phương phải hoàn thành việc bố trí vào vị trí việc làm và xếp ngạch tương ứng đối với công chức được tuyển dụng trước ngày I.uật có hiệu lực?",o:["Chậm nhất đến ngày 01 tháng 01 năm 2026","Chậm nhất đến ngày 01 tháng 7 năm 2026","Chậm nhất đến ngày 01 tháng 7 năm 2027","Chậm nhất đến ngày 31 tháng 12 năm 2025"],c:2},{id:"vb08-225",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Khoản 3 Điều 43 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Mọi hành vi vi phạm trong thời gian công tác của cán bộ, công chức đã nghỉ việc, nghỉ hưu đều bị xử lý theo quy định của pháp luật; tùy tính chất, mức độ có thể bị xử lý hình sự, hành chính hoặc kỷ luật. Nguyên tắc 'hạ cánh không an toàn.",mn:"Nghỉ hưu vẫn bị xử lý vi phạm thời công tác (hình sự/hành chính/kỷ luật).",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, đối với hành vi vi phạm trong thời gian công tác của cán bộ, công chức đã nghỉ việc, nghỉ hưu được xử lý theo nguyên tắc nào?",o:["Không xử lý vi người vi phạm đã nghỉ việc, nghỉ hưu","Mọi hành vi vi phạm trong thời gian công tác đều bị xử lý theo quy định của pháp luật; tùy tính chất, mức độ có thể bị xử lý hình sự, hành chính hoặc kỷ luật","Chỉ xử lý nếu hành vi vi phạm bị phát hiện trong thời gian còn công tác","Chỉ nhắc nhở, rút kinh nghiệm"],c:1},{id:"vb08-226",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Điểm c khoản 3 Điều 43 Luật Cán bộ, công chức số 80/2025/QH15. Lưới t BCtC 2095 TỪ TỪ 82",gt:"Cán bộ, công chức đã nghỉ việc, nghỉ hưu mới phát hiện vì phạm trong thời gian công tác thì tùy tính chất, mức độ phải chịu một trong các hình thức: khiển trách, cảnh cáo, xóa tư cách chức vụ đã đảm nhiệm gắn với hệ quả pháp lý tương ứng. 'Xóa tư cách chức vụ đã đảm nhiệm' là hình thức đặc thù với người đã nghỉ.",mn:"Người đã nghỉ: khiển trách — cảnh cáo - xóa tư cách chức vụ đã đảm nhiệm.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, hình thức kỷ luật áp dụng đối với cán bộ, công chức đã nghỉ việc, nghỉ hưu khi phát hiện có vi phạm trong thời gian công tác bao gồm hình thức đặc thù nào sau đây?",o:["Bãi nhiệm và tước quyền công dân","Buộc thôi việc và thu hồi toàn bộ lương hưu","Khiển trách, cảnh cáo, xóa tư cách chức vụ đã đảm nhiệm gắn với hệ quả pháp lý tương ứng","Hạ ngạch và chuyển công tác"],c:2},{id:"vb08-227",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Khoản 3 Điều 45 Luật Cán bộ, công chức số 60/2025/QH15.",gt:"Kể từ ngày Luật có hiệu lực, người đang tập sự theo quy định của Luật cũ được xếp vào ngạch công chức tương ứng với vị trí việc làm tuyển dụng - nhất quán với cơ chế quản lý theo vị trí việc làm.",mn:"Người đang tập sự: được xếp ngạch tương ứng vị trí việc làm tuyển dụng.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, kể từ ngày Luật có hiệu lực, người đang tập sự theo quy định của Luật Cán bộ, công chức cử được xử lý như thế nào?",o:["Được xếp vào ngạch công chức tương ứng với vị trí việc làm tuyển dụng","Phải tập sự lại từ đầu theo quy định mới","Đương nhiên trở thành công chức chính thức không quả xếp ngạch","Bị chấm dứt việc tập sự"],c:0},{id:"vb08-228",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Ø)iều 44 và Điều 45 Luật Cán bộ, công chức số 80/2025/0QH15.",gt:"Tổng hợp: Luật có hiệu lực 01/7/2025 (đánh giá công chức 01/01/2026), thay thế Luật CBCGC 2008 sửa đổi 2019; cán bộ, công chức cấp xã đủ tiêu chuẩn được chuyển tiếp, tinh giản biên chế trong 05 năm; hoàn thành bố trí vị trí việc làm, xếp ngạch chậm nhất 01/7/2027.",mn:"Hiệu lực 01/7/2025 -— đánh giá 01/01/2026 - bố trí VTVL chậm nhất 01/7/2027. 6) 1 lị h 2075.52.27//0/063 Luút C BC CHUYÊN ĐỀ NÂNG CAO - CÁC ĐIỂM MỚI NỔI BẬT CỦA LUẬT CÁN BỘ, CÔNG CHỨC NĂM 2025 Phần nâng cao ở mức vận dụng, phân tích, liên hệ thực tiễn, tập trung vào những điểm mới mang tính đột phá của Luật Cán bộ, công chức số 80/2025/QH15 so với quy định trước đây: quản lý theo vị trí việc làm; liên thông và thống nhất chế độ công vụ gắn với chính quyền hai cấp; thu hút, trọng dụng nhân tài; trả lương theo vị trí việc làm và kết quả; đánh giá đa chiều, định lượng, sáng lọc; báo về cán bộ năng động, sáng tạo; chuyển đổi số trong quản lý công chức.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, phương án nào sau đây phản ánh ĐÚNG và ĐẦY ĐỦ nhất về hiệu lực và chuyển tiếp của Luật?",o:["Luật không thay thế Luật Cán bộ, công chức năm 2008","Luật có hiệu lực từ 24/6/2025 và không có quy định chuyển tiếp","Luật có hiệu lực từ 01/01/2026 cho toàn bộ nội dung","Luật có hiệu lực từ 01/7/2025 (đánh giá công chức từ 01/01/2026), thay thế Luật CBCC 2008 (sửa đổi 2019); cán bộ, công chức cấp xã đủ tiêu chuẩn được chuyển tiếp và tinh giản biên chế trong 05 năm; hoàn thành bố trí vị trí việc làm, xếp ngạch chậm nhất 01/7/2027"],c:3},{id:"vb08-229",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Ø)iều 1, Điều 3, Điều 23 Luật Cán bộ, công chức số 80/2025/QH16.",gt:"Điểm cốt lợi của Luật 2025 là chuyên trọng tâm quản lý sang vị trí việc làm: tuyển dụng, bố trí, đánh giá, trả lương đều gắn với vị trí việc làm và kết quả, hiệu quả thực thi nhiệm vụ. Hệ thống ngạch vẫn còn (sáu ngạch) nhưng được xếp tương ứng với vị trí việc làm, không thay bằng quản lý theo thâm niên.",mn:"Triết lý mới: quản lý theo VỊ TRÍ VIỆC LÀM và kết quả, không theo thâm niên.",t:"m",q:"Phân tích triết lý xuyên suốt của Luật Cán bộ, công chức số 80/2025/QH15, đầu là sự thay đổi cần ban nhất trong phương thức quản lý công chức so với trước đây?",o:["Quản lý công chức hoàn toàn theo thâm niên công tác và bằng cấp","Chuyển trọng tâm quản lý sang 'vị trí việc làm - tuyển dụng, bố trí, đánh giá, trả lương đều gắn với vị trí việc làm và kết quả, hiệu quả thực thi nhiệm vụ, thay cho cách quản lý năng về ngạch, bậc và thâm niên","Bỏ hoàn toàn hệ thống ngạch công chức","Giao toàn bộ việc quản lý công chức cho từng cơ quan tự quyết định"],c:1},{id:"vb08-230",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Điều 1 và Điều 45 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Luật 2025 xác định cán bộ, công chức làm việc ở trung ương, cấp tỉnh, cấp xã (phù hợp mô hình hai cấp, không còn cấp huyện) và thống nhất một chế độ công vụ, liên thông cán bộ, công chức cấp xã với cấp tỉnh, trung ương - xóa bỏ sự tách biệt của chế độ công chức cấp xã trước đây.",mn:"Điểm mới: liên thông, thống nhất công vụ; CBCC cấp xã - tỉnh - TW (bộ cấp huyện). Luôt CBCC 2025 2g 84",t:"m",q:"Liên hệ với chủ trương sắp xếp tổ chức bộ máy và mô hình chính quyền địa phương hai cấp, điểm mới nào của Luật Cán bộ, công chức số 80/2025/QH15 thể hiện rõ nhất sự gắn kết này?",o:["Giữ nguyên chế độ công chức cấp xã riêng biệt như trước","Tăng thêm biên chế cho cấp xã","Xác định cán bộ, công chức làm việc ở trung ương, cấp tỉnh, cấp xã (không còn cấp huyện) và thống nhất một chế độ công vụ, liên thông cán bộ, công chức cấp xã với cấp tỉnh, trung ương","Chuyến toàn bộ công chức cấp xã thành viên chức"],c:2},{id:"vb08-231",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Điều 1, Điều 30, Điều 45 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Việc thống nhất, liên thông chế độ công vụ tạo điều kiện sử dụng, điều động, bổ nhiệm cán bộ, công chức thông suốt giữa các cấp, nâng cao chất lượng đội ngũ ở cơ sở và bảo đảm bình đẳng về chế độ, chính sách - có giá trị thực tiễn lớn, không chỉ là thay đổi hình thức.",mn:"Liên thông công vụ: dùng người thông suốt giữa các cấp + bình đẳng chế độ.",t:"m",q:"Một ý kiến cho rằng: 'Việc bỏ chế độ công chức cấp xã riêng và liên thông với cấp tỉnh, trung ương chỉ là thay đổi hình thức, không tạo ra giá trị thực tiễn'. Theo tinh thần Luật Cán bộ, công chức số 80/2025/QH15, cần đánh giá ý kiến này như thế nào?",o:["Chưa chính xác, vì việc thống nhất, liên thông chế độ công vụ tạo điều kiện sử dụng, điều động, bổ nhiệm cán bộ, công chức thông suốt giữa các cấp, nâng cao chất lượng đội ngũ ở cơ sở và bảo đảm bình đẳng về chế độ, chính sách","Chính xác, vị không có thay đổi nào về bản chất","Chính xác, vì cán bộ, công chức cấp xã vẫn bị phân biệt đối xử","Chưa chính xác, vi liên thông làm tăng thủ tục hành chính"],c:0},{id:"vb08-232",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Khoản 1 Điều 10 và Điều 23 Luật Cán bộ. công chức số 80/2025/QH15.",gt:"Trả lương theo kết quả, sản phẩm của vị trí việc làm giúp gản thu nhập với hiệu quả công việc thực tế, tạo động lực phấn đấu, khắc phục tình trạng cáo bằng, 'sống lâu lên lão làng', khuyến khích công chức nâng cao năng suất, chất lượng.",mn:"Lương theo kết quả, vị trí việc làm: chống cáo bằng, tạo động lực.",t:"m",q:"Phân tích ý nghĩa của quy định trả lương 'theo kết quả, sản phẩm của vị trí việc làm' trong Luật Cán bộ, công chức số 80/2025/QH15 so với cách trả lương theo ngạch, bậc, thâm niên trước đây?",o:["Xóa bỏ hoàn toàn vai trò của ngạch, bậc trong xác định lượng","Làm giảm thu nhập của mỗi công chức","Chỉ áp dụng cho công chức lãnh đạo, quản lý","Gắn thu nhập với hiệu quả công việc thực tế, tạo động lực phấn đấu, khắc phục tình trạng cáo bằng, 'sống lâu lên lão làng', khuyến khích công chức nâng cao năng suất, chất lượng"],c:3},{id:"vb08-233",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Điều 4 và Điều 21 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Cơ chế thu hút nhân tài và hợp đồng thực hiện nhiệm vụ tạo sự linh hoạt trong sử dụng nhân lực chất lượng cao từ khu vực ngoài nhà nước (chuyên gia, nhà khoa học, doanh nhân tiêu biểu...) vào thực hiện nhiệm vụ công vụ, kể cả vị trí lãnh đạo, quản lý, không bị bó hẹp bởi quy trình tuyển dụng truyền thống.",mn:"Thu hút nhân tài + hợp đồng nhiệm vụ: linh hoạt đưa người giới ngoài NN vào công vụ.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, cơ chế thu hút, trọng dụng người có tài năng và cơ chế hợp đồng thực hiện nhiệm vụ có ý nghĩa nổi bật nào sau đây?",o:["Tạo sự linh hoạt trong sử dụng nhân lực chất lượng cao từ khu vực ngoài nhà nước (chuyên gia, nhà khoa học, doanh nhân tiêu biểu...) vào thực hiện nhiệm vụ công vụ, kể cả vị trí lãnh đạo, quản lý, mà không bị bó hẹp bởi quy trình tuyển dụng truyền thống","Thay thế hoàn toàn việc tuyển dụng công chức bằng hợp đồng","Chỉ áp dụng cho các vị trí hỗ trợ, phục vụ","Làm giảm chất lượng đội ngũ công chức"],c:0},{id:"vb08-234",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",gt:"Đánh giá mới: đa chiều, xuyên suốt, liên tục, định lượng tối đa theo kết quả, sản phẩm gắn vị trí việc làm, ứng dụng công nghệ; kết quả được dùng để bố trí, sử dụng, khen thưởng hoặc bố trí thấp hơn, cho thôi việc - khắc phục đánh giá hình thức, cấm tính.",mn:"Đánh giá mới: đa chiều — định lượng - công nghệ — gắn với sử dụng và cho thôi việc.",t:"m",q:"Phần tích điểm mới về đánh giá công chức theo Luật Cán bộ, công chức số 80/2025/QH15, đầu là sự khác biệt cần bản so với cách đánh giá hình thức trước đây?",o:["Đánh giá một lần cuối năm bằng nhận xét định tình","Đánh giá đa chiều, xuyên suốt, liên tục, định lượng tối đa theo kết quả, sản phẩm gắn với vị trí việc làm, ứng dụng công nghệ: kết quả đánh giá được dùng để bố trí, sử dụng, khen thưởng hoặc bố trí thấp hơn, cho thôi việc","Đánh giá chí để bình xét thi đua, không ảnh hưởng đến việc sử dụng","Đánh giá theo thâm niên và bằng cấp"],c:1},{id:"vb08-235",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Điều 27 và Điều 32 Luật Cán bộ, công chức số 60/2025/QH15.",gt:"Quy định này thể hiện chủ trương xây dựng nên công vụ 'có vào, có ra', 'có lên, có xuống, sáng lọc những người không đáp ứng yêu cầu, nâng cao chất lượng và kỷ luật, kỷ cương. Đây là cơ chế đánh giá - sử dụng, khác với giảm biên chế cơ học hay xử lý kỷ luật.",mn:"'Có vào cơ ra, có lớn có xuống' — sàng lọc theo kết quả.",t:"m",q:"Liên hệ thực tiễn, quy định cho phép 'bố trí vào vị trí việc làm thấp hơn hoặc cho thôi việc' đối với công chức không hoàn thành nhiệm vụ theo Luật Cán bộ, công chức số 80/2025/QH15 thể hiện chủ trương nào?",o:["Chủ trương duy trì ổn định tuyệt đối đội ngũ công chức","Chủ trương giảm biên chế một cách cơ học theo tỷ lệ cố định","Chủ trương xử lý kỷ luật thay cho đánh giá","Chủ trương xây dựng nền công vụ 'có vào, có ra', 'có lên, có xuống', sáng lọc những người không đáp ứng yêu cầu, nâng cao chất lượng và kỷ luật, kỷ cương của đội ngũ"],c:3},{id:"vb08-236",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Điều 34 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Cơ chế này nhằm bảo vệ, khuyến khích cán bộ, công chức năng động, sáng tạo, dám nghĩ, dám làm, dám chịu trách nhiệm vì lợi ích chung, tạo hành lang pháp lý để yên tâm đổi mới khi có động cơ trong sáng, làm đúng chủ trương. Đây không phải miễn trừ cho mọi sai phạm.",mn:"Loại trừ trách nhiệm: bảo vệ người dám nghĩ, dám làm vì lợi ích chung.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, cơ chế loại trừ, miễn, giảm trách nhiệm' đối với cán bộ, công chức có ý nghĩa chính sách nào nổi bật?",o:["Giảm nhẹ trách nhiệm cho cán bộ lãnh đạo trong mọi trường hợp",'Miễn trừ trách nhiệm cho mọi sai phạm của cán bộ, công chức Luật CBCC 2025 "rang 86',"Bảo vệ, khuyến khích cán bộ, công chức năng động, sáng tạo, dám nghĩ, dám làm, dám chịu trách nhiệm vì lợi ích chung; tạo hành lang pháp lý để cán bộ yên tâm đổi mới mà không sợ bị quy kết khi có động cơ trong sáng, làm đúng chủ trương","Khuyến khích cán bộ, công chức né tránh trách nhiệm"],c:2},{id:"vb08-237",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Điều 14 và Điều 34 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Hai vêu cầu không mâu thuẫn: cơ chế bảo vệ chỉ áp dụng khi cần hộ thực hiện đúng chủ trương, được cấp có thẩm quyền cho phép, có động cơ trong sáng, vì lợi ích chung: còn hành vi vụ lợi, tham nhũng vẫn bị xử lý nghiêm theo những việc không được làm và quy định kỷ luật.",mn:"Bảo vệ đổi mới (trong sáng, vì lợi ích chung) Z dung từng tham nhũng, vụ lợi.",t:"m",q:"Phân tích mối quan hệ giữa cơ chế bảo vệ cán bộ dám nghĩ, dám làm và yêu cầu phòng, chống tham nhũng, tiêu cực trong Luật Cán bộ, công chức số 80/2025/QH15, nhận định nào sau đây là DÙNG?",o:["Phòng, chống tham nhũng triệt tiêu mới đối mới, sáng tạo","Hai yêu cầu mâu thuẫn nhau, không thể cùng tồn tại","Cơ chế bảo vệ làm vô hiệu hóa việc phòng, chống tham nhũng","Hai yêu cầu này không mâu thuẫn: chỉ bảo vệ khi cán bộ thực hiện đúng chủ trương, được cấp có thẩm quyền cho phép, có động cơ trong sáng, vì lợi ích chung: còn hành vi vụ lợi, tham nhũng vẫn bị xử lý nghiêm"],c:3},{id:"vb08-238",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Khoản 8 Điều 40 và Điều 42 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Ứng dụng công nghệ, chuyển đổi số và cơ sở dữ liệu quốc gia giúp hiện đại hóa quản lý, bảo đảm dữ liệu chính xác, liên thông, minh bạch, phục vụ theo dõi, đánh giá, sử dụng cán bộ, công chức hiệu quả và giảm thủ tục hành chính trong quản lý nhân sự.",mn:'Chuyển đổi số + CSDL quốc gia: quản lý minh bạch, liên thông, giảm thủ tục. Luật CBCC 2025 "rang 87',t:"m",q:"Theo Luật Cán bộ, công chức số 90/2025/QH15, việc ứng dụng khoa học, công nghệ, chuyển đổi số và xây dựng cơ sở dữ liệu quốc gia về cán bộ, công chức có ý nghĩa nào sau đây?",o:["Hiện đại hóa công tác quản lý, bảo đảm dữ liệu chính xác, liên thông, minh bạch, phục vụ theo dõi, đánh giá, sử dụng cán bộ, công chức hiệu quả và giám thủ tục hành chính trong quản lý nhân sự","Chỉ nhằm số hóa hồ sơ giấy, không thay đổi cách quản lý","Làm tăng chi phí và thủ tục quản lý cán bộ, công chức","Thay thế hoàn toàn vai trò của cơ quan quản lý cán bộ, công chức"],c:0},{id:"vb08-239",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Khoản 3 Điều 43 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Quy định này thể hiện nguyên tắc mọi hành vi vi phạm trong thời gian công tác đều bị xử lý, không có vùng cấm, không 'hạ cánh an toàn', bảo đảm kỷ luật, kỷ cương và trách nhiệm đến cùng - kể cả khi cán bộ, công chức đã nghỉ việc, nghỉ hưu.",mn:"Nghỉ hưu vẫn bị xử lý vi phạm: không có 'hạ cánh an toàn”.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, quy định xử lý vi phạm đối với cán bộ, công chức đã nghỉ việc, nghỉ hưu (kể cả hình thức 'xóa tư cách chức vụ đã đảm nhiệm') thể hiện nguyên tắc nào?",o:["Miễn trách nhiệm cho người đã nghỉ hưu","Chí xử lý vi phạm khi người đó còn đang công tác","Mọi hành vi vi phạm trong thời gian công tác đều bị xử lý, không có vùng cấm, không có 'hạ cánh an toàn', bảo đảm kỷ luật, kỷ cương và trách nhiệm đến cùng của cán bộ, công chức","Chỉ áp dụng đối với cán bộ lãnh đạo cấp cao"],c:2},{id:"vb08-240",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Khoản 5 Điều 8 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Người đứng đầu có nghĩa vụ rà soát, cắt giảm tối đa thủ tục hành chính, tạo thuận lợi cho người dân, doanh nghiệp và chịu trách nhiệm về việc giải quyết thủ tục hành chính thuộc phạm vi quản lý — gắn trách nhiệm người đứng đầu với cải cách hành chính.",mn:"Người đứng đầu: cắt giảm tối đa TTHC + chịu trách nhiệm giải quyết TIHC.",t:"m",q:"Liên hệ với yêu cầu cải cách hành chính, nghĩa vụ nào của người đứng đầu theo Luật Cán bộ, công chức số 80/2025/QH15 thể hiện rõ trách nhiệm phục vụ người dân, doanh nghiệp?",o:["Tăng cường ban hành thêm thủ tục đề quản lý chặt chẽ","Thường xuyên rà soát để cắt giảm tối đa thủ tục hành chính, tạo điều kiện thuận lợi cho người dân, doanh nghiệp; lãnh đạo, chỉ đạo và chịu trách nhiệm về việc giải quyết thủ tục hành chính thuộc phạm vi quản lý","Giao toàn bộ việc giải quyết thủ tục cho cấp dưới và không chịu trách nhiệm","Chỉ giải quyết thủ tục khi có chỉ đạo của cấp trên"],c:1},{id:"vb08-241",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Điều 19 Luật Cán bộ, công chức số 80/2025/QH15. Lưới t BCtC 2095 TỪ TỪ 88",gt:"Điều kiện chỉ có 01 quốc tịch là quốc tịch Việt Nam bảo đảm yêu cầu chính trị, an ninh của nền công vụ; điều kiện đủ 18 tuổi trở lên gắn cơ hội dự tuyển với năng lực đáp ứng vị trí việc làm, không câu nệ tuổi tối đa hay bằng cấp cứng nhắc.",mn:"Dự tuyển: 01 quốc tịch VN (an ninh công vụ) + đủ 18 tuổi (gắn năng lực, VTVL).",t:"m",q:"Phân tích điểm mới trong điều kiện dự tuyển công chức theo Luật Cán bộ, công chức số 80/2025/QH15 về quốc tịch và độ tuổi, ý nghĩa của các quy định này là gì?",o:["Bó mọi điều kiện về quốc tịch và do tuối","Cho phép người có nhiều quốc tịch dự tuyển và giới hạn độ tuổi tối đa","Yêu cầu phải là đảng viên và đủ 21 tuổi","Yêu cầu chỉ có 01 quốc tịch là quốc tịch Việt Nam (bảo đảm yêu cầu chính trị, an ninh của nền công vụ) và đủ 18 tuổi trở lên (mở rộng cơ hội dự tuyển, gắn với năng lực đáp ứng vị trí việc làm)"],c:3},{id:"vb08-242",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Khoản 2 Điều 20 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"(`ơ chế tiếp nhận (không qua thi) tạo sự linh hoạt thu hút người có năng lực, kinh nghiệm thực tiễn vào nền công vụ, đáp ứng ngay yêu cầu vị trí việc làm, khắc phục rào cản của quy trình thì tuyên truyền thống - nhưng vẫn bảo đảm tiêu chuẩn vị trí việc làm.",mn:"Tiếp nhận (không thi): thu hút người giỏi, có kinh nghiệm, đáp ứng ngay VTVL.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, việc tiếp nhận chuyên gia, nhà khoa học, doanh nhân tiêu biểu hoặc viên chức có kinh nghiệm vào làm công chức không qua thi tuyển có ý nghĩa nào sau đây?",o:["Hạ thấp tiêu chuẩn tuyển dụng công chức","Tạo cơ chế linh hoạt thu hút người có năng lực, kinh nghiệm thực tiễn vào nền công vụ, đáp ứng ngay yêu cầu vị trí việc làm, khắc phục rào cản của quy trình thi tuyển truyền thống","Xóa bỏ hình thức thi tuyển, xét tuyển","Chỉ áp dụng cho người thần của cán bộ, công chức"],c:1},{id:"vb08-243",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Điều 4 và Điều 21 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Địa phương có thể vận dụng cơ chế thu hút nhân tài và ký hợp đồng thực hiện nhiệm vụ với chuyên gia để thực hiện nhiệm vụ của vị trí việc làm, kể cả vị trí lãnh đạo, quản lý, mà không bắt buộc qua thi tuyển.",mn:"Cần chuyên gia giỏi: dùng cơ chế thu hút nhân tài + hợp đồng nhiệm vụ.",t:"m",q:"Một tình huống liên hệ: Một địa phương sau sắp xếp có nhu cầu một chuyên gia công nghệ giỏi để dẫn dắt chuyển đổi số nhưng người này chưa từng là công chức. Theo Luật Cán bộ, công chức số 80/2025/QH15, địa phương có thế vận dụng cơ chế nào?",o:["Phải cho tổ chức kỳ thi tuyển công chức chuyên ngành","Không thể sử dụng vi người này chưa thi tuyển công chức","Vận dụng cơ chế thu hút nhân tài và ký hợp đồng thực hiện nhiệm vụ với chuyên gia để thực hiện nhiệm vụ của vị trí việc làm, kể cả vị trí lãnh đạo, quản lý theo quy định","Chỉ có thể thuê theo hợp đồng lao động thông thường"],c:2},{id:"vb08-244",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Điểm c khoản 2 Điều 23 và Điều 25 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Bản mô tả công việc và khung năng lực là công cụ then chốt để tuyển dụng đúng người, bố trí đúng việc, đánh giá theo kết quả và xác định nhu cầu đào tạo, làm cơ sở cho quản lý công chức khoa học, minh bạch theo vị trí việc làm.",mn:"Bản mô tả công việc + khung năng lực: nền tảng tuyến - hố trí — đánh giá — đào tạo.",t:"m",q:"Phân tích vai trò của 'bản mô tả công việc và khung năng lực' của vị trí việc làm theo Luật Cán bộ, công chức số 80/2025/QH15 trong quản lý công chức?",o:['Là công cụ then chốt để tuyển dụng đúng người, bố trí đúng việc, đánh giá theo kết quả và xác định nhu cầu đào tạo, làm cơ sở cho quản lý công chức khoa học, minh bạch theo vị trí việc làm Luôi CBCC 2025 "nÉg 89',"Chỉ là thủ tục hình thức khi xây dựng vị trí việc làm","Chỉ dùng để xác định hệ số lương","Chỉ áp dụng cho vị trí lãnh đạo, quản lý"],c:0},{id:"vb08-245",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"khoản 4 Điều 3 và Điều 27 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Việc gắn kết quả đánh giá với đào tạo, quy hoạch, bổ nhiệm, khen thưởng hoặc cho thôi việc thể hiện nguyên tắc đánh giá, bố trí, sử dụng căn cứ vào phẩm chất, năng lực và kết quả, hiệu quả thực thi nhiệm vụ theo yêu cầu vị trí việc làm.",mn:"Đánh giá — sử dụng: theo năng lực + kết quả gắn vị trí việc làm.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, việc gắn kết quả đánh giá, xếp loại với đào tạo, quy hoạch, bổ nhiệm, khen thưởng hoặc cho thôi việc thể hiện nguyên tắc quản lý nào?",o:["Nguyên tắc đánh giá, bố trí, sử dụng cán bộ, công chức căn cứ vào phẩm chất, năng lực và kết quả, hiệu quả thực thi nhiệm vụ theo yêu cầu vị trí việc làm","Nguyên tắc đánh giá theo thâm niên và bằng cấp","Nguyên tắc bình quân, cáo bằng trong sử dụng cán bộ","Nguyên tắc bổ nhiệm theo nhiệm kỳ cố định"],c:0},{id:"vb08-246",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Điểm a khoản 1 Điều 32 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Quy định này nhằm ngăn ngừa việc lợi dụng thôi việc để né tránh trách nhiệm kỷ luật hoặc trách nhiệm hình sự, bảo đảm kỷ cương và xử lý vi phạm đến cùng.",mn:"Không cho thôi việc khi đang bị xem xét: chống né tránh trách nhiệm.",t:"m",q:"Liên hệ thực tiễn, quy định 'không giải quyết thôi việc đối với công chức đang trong thời gian xem xét xử lý kỷ luật hoặc bị truy cứu trách nhiệm hình sự' theo Luật Cán bộ, công chức số 80/2025/QH15 nhằm mục đích gì?",o:["Bảo đảm công chức được hưởng đủ chế độ trước khi thôi việc","Hạn chế quyền thôi việc của công chức một cách tùy tiện","Kéo dài thời gian công tác của công chức vi phạm","Ngăn ngừa việc lợi dụng thôi việc để né tránh, trốn tránh trách nhiệm kỷ luật hoặc trách nhiệm hình sự, bảo đảm kỷ cương và xử lý vi phạm đến cùng"],c:3},{id:"vb08-247",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Điều 35 và Điều 36 Luật Cán bộ, công chức số 60/2025/QH15.",gt:"Sự khác biệt xuất phát từ bản chất hình thành chức vụ: cán bộ gắn với bầu cử, phê chuẩn, bổ nhiệm, chỉ định theo nhiệm kỳ nên có hình thức 'bãi nhiệm”; công chức gắn với tuyển dụng, vị trí việc làm nền có hình thức 'buộc thôi việc'.",mn:"Cán bộ (nhiệm kỳ) — bãi nhiệm; Công chức (tuyển dụng) ¬ buộc thôi việc.",t:"m",q:"Phân tích sự khác biệt giữa hình thức kỷ luật của cán bộ và của công chức theo Luật Cán bộ, công chức số 80/2025/QH15 dưới góc do bản chất hình thành chức vụ?",o:["Cả hai có hình thức kỷ luật giống hệt nhau Lưới t BCtC 2095 gi 90","Cán bộ gắn với cơ chế bầu cử, phê chuẩn, bổ nhiệm, chỉ định theo nhiệm kỳ nên có hình thức bãi nhiệm'; công chức gắn với tuyển dụng và làm việc theo vị trí việc làm nền có hình thức 'buộc thôi việc'","Cán bộ có “buộc thôi việc, công chức có 'bãi nhiệm","Sự khác biệt chỉ mang tính hình thức, không có cơ sở"],c:1},{id:"vb08-248",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"!)iều 37 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Quy định thể hiện sự cần bằng: vừa bảo đảm tính ổn định, nhận văn (hết thời hiệu thì không xử lý), vừa xử lý nghiêm khác, không giới hạn thời gian đối với các vi phạm đặc biệt nghiêm trọng (khai trừ đảng, bảo vệ chính trị nội bộ, xâm hại lợi ích quốc gia, văn bằng giả).",mn:"Thời hiệu: căn bằng ổn định/nhận văn với nghiêm khác (4 trường hợp không thời hiệu).",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, quy định về thời hiệu xử lý kỷ luật (05 năm/10 năm) và các trường hợp không áp dụng thời hiệu thể hiện sự cần bằng nào?",o:["Chỉ nhằm xử lý nghiêm mọi vi phạm không giới hạn thời gian","Chỉ nhằm tạo thuận lợi cho người vi phạm","Cân bằng giữa tính ổn định, nhận văn (sau thời hiệu thì không xử lý) với yêu cầu xử lý nghiêm khác, không giới hạn thời gian đối với các vi phạm đặc biệt nghiêm trọng (khai trừ đảng, bảo vệ chính trị nội bộ, xâm hại lợi ích quốc gia, văn bằng giả)","Không có ý nghĩa thực tiễn"],c:2},{id:"vb08-249",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Các điều 1,3,4, 10, 21,25, 27. 34, 40 Luật Cán bộ, công chức số 80/2025/QH15.",gt:'Ý kiến chưa chính xác. Luật 2025 có nhiều đột phá: quản lý theo vị trí việc làm; liên thông, thống nhất chế độ công vụ; thu hút nhân tài; trả lương Luôi CBCC 2025 "nÉgg g1 theo kết quả; đánh giá đa chiều gắn sàng lọc; bảo vệ cán bộ năng động, sáng tạo; chuyển đổi số.',mn:"Luật 2025 nhiều đột phá, không chỉ thay đổi kỹ thuật.",t:"m",q:"Một ý kiến cho rằng: 'Luật Cán bộ, công chức năm 2025 chỉ thay đổi về kỹ thuật, không có tính đột phá'. Theo các điểm mới đã phân tích, cần đánh giá ý kiến này như thế nào?",o:["Chính xác, vì chỉ thay đổi tên gọi một số khái niệm","Chính xác, vì Luật không có nội dung mới","Chưa chính xác, vì Luật có nhiều đột phá: chuyển sang quản lý theo vị trí việc làm, liên thông và thống nhất chế độ công vụ, thu hút nhân tài, trả lương theo kết quả, đánh giá đa chiều gắn sàng lọc, bảo vệ cán bộ năng động, sáng tạo và chuyển đổi số","Chưa chính xác, nhưng các thay đổi đều mang tính hình thức"],c:2},{id:"vb08-250",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Điểm c khoản 4 Điều 25 và Điều 34 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Hai nội dung cùng hướng tới xây dựng đội ngũ năng động, dám đổi mới: vừa đánh giá, ghi nhận năng lực đối mới, sáng tạo, vừa bảo vệ người đổi mới đúng chủ trương, động cơ trong sáng khói bị quy kết khi gặp rủi ro khách quan - tạo hệ sinh thái khuyến khích đổi mới.",mn:"Đánh giá ghi nhận đối mới + cơ chế bảo vệ đổi mới = khuyến khích dám nghĩ, dám làm.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, việc bổ sung nội dung đánh giá về 'năng lực đổi mới, sáng tạo, dám nghĩ, dám làm, dám chịu trách nhiệm vì lợi ích chung' có mối liên hệ nào với cơ chế loại trừ, miễn, giảm trách nhiệm?",o:["Cả hai chỉ áp dụng cho công chức lãnh đạo, quản lý","Hai nội dung không liên quan đến nhau","Hai nội dung mâu thuẫn với nhau","Cùng hướng tới xây dựng đội ngũ cán bộ, công chức năng động, dám đổi mới: một mặt đánh giá, ghi nhận năng lực đối mới; mặt khác bảo vệ người đổi mới đúng chủ trương, có động cơ trong sáng khói bị quy kết trách nhiệm khi gặp rủi ro khách quan"],c:3},{id:"vb08-251",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Khoản 7 Điều 9 và Điều 34 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Việc quy định 'được xem xét loại trừ, miễn, giảm trách nhiệm' như một quyền nâng việc bảo vệ cán bộ năng động, sáng tạo thành quyền của công chức, tạo cơ sở pháp lý vững chắc để công chức yên tâm thực thi nhiệm vụ, đổi mới vì lợi ích chung (vấn gắn điều kiện chặt chẽ tại Điều 34).",mn:"Bảo vệ người dám làm được nâng thành quyền của công chức.",t:"m",q:"Phân tích ý nghĩa của việc Luật Cán bộ, công chức số 80/2025/QH15 quy định công chức 'được xem xét loại trừ, miễn, giảm trách nhiệm' như một quyền (tài nhóm quyền về điều kiện thi hành công vụ)?",o:["Biến việc miễn trách nhiệm thanh đặc quyền không điều kiện","Nâng việc bảo vệ cán bộ năng động, sáng tạo thành một quyền của công chức, tạo cơ sở pháp lý vững chắc để công chức yên tâm thực thi nhiệm vụ, đổi mới vì lợi ích chung","Làm giảm trách nhiệm công vụ của công chức","Chỉ mang tính tuyên ngôn, không có giá trị thực tiễn"],c:1},{id:"vb08-252",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Khoản 1 Điều 3 và Điều 41 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Việc quản lý theo Luật, pháp luật liên quan và điều lệ của Đảng, Mặt trận Tổ quốc Việt Nam, tổ chức chính trị - xã hội thể hiện đặc trung thống nhất, liên thông trong hệ thống chính trị và bảo đảm sự lãnh đạo của Đảng đối với công tác cán bộ.",mn:"Công vụ VN: thống nhất, liên thông trong hệ thống chính trị + Đảng lãnh đạo.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, việc thống nhất quản lý cán bộ, công chức theo Luật, pháp luật liên quan và điều lệ của Đảng, Mặt trận Tổ quốc Việt Nam, tổ chức chính trị - xã hội thể hiện đặc trưng nào của nền công vụ Việt Nam?",o:["Đặc trưng về sự thống nhất, liên thông trong hệ thống chính trị và bảo đảm sự lãnh đạo của Đảng đối với công tác cán bộ Lưới t BCtC 2095 gi 92","Đặc trưng về sự độc lập hoàn toàn của từng cơ quan trong quản lý cán bộ","Dặc trưng về việc tách rời công tác cán bộ khỏi sự lãnh đạo của Đảng","Đặc trưng về quản lý cán bộ thuần tùy theo pháp luật hành chính"],c:0},{id:"vb08-253",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Ø)iếm c khoản 1 Điều 34 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Công chức A thực hiện đề xuất đổi mới, sáng tạo được cấp có thẩm quyền cho phép, đúng chủ trương, có động cơ trong sáng, vì lợi ích chung nên được xem xét loại trừ, miễn, giảm trách nhiệm - đúng tinh thần bảo vệ cán bộ dám nghĩ, dám làm.",mn:"Đổi mới được cho phép, trong sáng, vì lợi ích chung ¬› được bảo vệ trách nhiệm.",t:"m",q:"Một tình huống liên hệ: Công chức A có sáng kiến cải tiên quy trình giải quyết thủ tục hành chính, được cấp có thẩm quyền cho phép thí điểm, thực hiện đúng chủ trương, không vụ lợi, nhưng do yếu tố khách quan kết quả chưa đạt như kỳ vọng và phát sinh một số thiệt hại. Theo Luật Cán bộ, công chức số 80/2025/QH15, công chức A được xem xét như thế nào?",o:["Được xem xét loại trừ, miễn, giảm trách nhiệm vì đã thực hiện đề xuất đổi mới, sáng tạo được cho phép, đúng chủ trương, có động cơ trong sáng, vì lợi ích chung","Phái chịu trách nhiệm kỳ luật vi gây thiệt hại","Bị buộc thôi việc do sáng kiến không thành công","Phải bồi thường toàn bộ thiệt hại phát sinh"],c:0},{id:"vb08-254",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Các điều 1,3, 4, 21, 23, 34 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Luật 2025 xóa bỏ chế độ công chức cấp xã riêng biệt (thống nhất, liên thông) và chuyển sang quản lý theo vị trí việc làm, kết quả (không theo thâm niên). Vì vậy phương án D sai. Các nhận định A, B, C đều đúng với điểm mới.",mn:"Không còn công chức cấp xã riêng + quản lý theo thâm niên.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, nhận định nào sau đây về các điểm mới của Luật là KHÔNG đúng?",o:["Chuyến trọng tâm quản lý sang vị trí việc làm và kết quả công việc","Duy trì chế độ công chức cấp xã riêng biệt và quản lý chủ yếu theo thâm niên","Có cơ chế thu hút nhân tài, hợp đồng thực hiện nhiệm vụ và bảo vệ cán bộ dám nghĩ, dám làm","Thống nhất, liên thông chế độ công vụ giữa cấp xã, cấp tỉnh và trung ương"],c:1},{id:"vb08-255",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Toàn văn Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Tinh thần đổi mới của Luật: xây dựng nên công vụ thống nhất, liên thông, chuyên nghiệp, hiện đại, hoạt động theo vị trí việc làm và kết quả; thu hút, trọng dụng nhân tài; đánh giá thực chất gắn sàng lọc; bảo vệ cán bộ năng động, sáng tạo; chuyển đổi số và đề cao kỷ luật, kỷ cương, trách nhiệm đến cùng.",mn:"Nền công vụ mới: vị trí việc làm — nhân tài — đánh giá thực chất — bảo vệ đổi mới - chuyển đổi số - trách nhiệm đến cùng.",t:"m",q:"Theo Luật Cán bộ, công chức số 80/2025/QH15, phương án nào sau đây khái quát ĐÚNG và ĐẦY ĐỦ nhất tinh thần đổi mới của Luật?",o:["Duy trì ổn định tuyệt đối đội ngũ, không sàng lọc Luật CBCC 2025 “rang 93","Tăng cường quản lý hành chính theo thâm niên và bằng cấp","Xây dựng nền công vụ thống nhất, liên thông, chuyên nghiệp, hiện đại, hoạt động theo vị trí việc làm và kết quả; thu hút, trọng dụng nhân tài; đánh giá thực chất gắn sàng lọc; bảo vệ cán bộ năng động, sáng tạo; đẩy mạnh chuyển đổi số và đề cao kỷ luật, kỷ cương, trách nhiệm đến cùng","Giảm vai trò của Nhà nước trong quản lý công vụ"],c:2},{id:"vb08-256",s:"CHƯƠNG VII - ĐIỀU KHOẢN THI HÀNH",cc:"Điều 27, Điều 32 và Điều 34 Luật Cán bộ, công chức số 80/2025/QH15.",gt:"Việc kết hợp cơ chế sàng lọc (cho thôi việc khi không hoàn thành nhiệm vụ) và cơ chế bảo vệ (loại trừ, miễn, giảm trách nhiệm cho người đổi mới) phản ánh quan điểm vừa kiên quyết loại bỏ người không đáp ứng yêu cầu, vừa khuyến khích, bảo vệ người đảm đổi mới vì lợi ích chung - kết hợp hài hòa 'siết kỷ cương' và mở không gian sáng tạo'.",mn:'Vừa sàng lọc người yếu, vừa bảo vệ người đảm đổi mới = hai mất năng chất lượng đội ngũ. Luút CBCC 2025 "rung 94',t:"m",q:"Tổng hợp và liên hệ, việc Luật Cán bộ, công chức số 80/2025/QH15 đồng thời quy định cơ chế 'sàng lọc' (cho thôi việc khi không hoàn thành nhiệm vụ) và cơ chế 'bảo vệ' (loại trừ, miễn, giảm trách nhiệm cho người đổi mới) phản ánh quan điểm nào về xây dựng đội ngũ?",o:["Hai cơ chế mâu thuẫn và triệt tiêu lẫn nhau","Chí chú trọng loại bộ người yếu kém mà không khuyến khích đổi mới","Chỉ chú trọng bảo vệ cán bộ mà buông lỏng kỷ cương","Vừa kiên quyết loại bỏ người không đáp ứng yêu cầu, vừa khuyến khích, bảo vệ người đảm đổi mới vì lợi ích chung - kết hợp hài hòa giữa 'siết kỷ cương' và 'mở không gian sáng tạo' để nâng cao chất lượng đội ngũ"],c:3}];export{n as default};
